import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-b2-001","clusterId":"B","werkstueckRef":"B.17","stufe":1,"question":"Welche Antwort auf diese beiden Aussagen trifft den Kern, ohne das Gespräch ins Gegenteil kippen zu lassen?","options":["Beide haben recht: Wer urteilt, ignoriert den Kontext, und wer den Kontext nennt, spricht die Handelnden damit frei.","Der erste Satz ersetzt Verstehen durch ein heutiges Urteil, der zweite verbietet jedes Urteil. Beides ist verkürzt.","Der erste Satz ist richtig, weil sich moralische Maßstäbe nie verändert haben, und der Hinweis auf den Kontext ist bloß eine Ausrede.","Der zweite Satz ist richtig, weil jede Epoche nur an sich selbst zu messen ist, und spätere Generationen haben kein Recht auf ein Urteil."],"correctIndex":1,"explanation":"Der erste Satz begeht den Fehler des Präsentismus: Er misst Menschen früherer Zeiten an Normen und Wissen von heute und hält das für das ganze Bild. Damit bleibt unverstanden, in welchem Weltbild, mit welchem Wissen und mit welchen Handlungsmöglichkeiten sie lebten. Die Gegenposition schießt übers Ziel hinaus: Wer Verstehen verlangt, muss deshalb nicht auf Bewertung verzichten. Das zeigt der Fall Thomas Jefferson: Den Kontext zu beachten entschuldigt die Sklaverei nicht, ihn zu ignorieren verhindert aber das Verständnis der Widersprüche, mit denen er rang. Jefferson nannte die Sklaverei in seinen „Notes on the State of Virginia“ selbst einen „unablässigen Despotismus“ und hielt zugleich die Unterlegenheit Schwarzer „nur als Verdacht“ für möglich. Falsch wird es erst, wenn Verurteilung oder Verklärung das Verständnis ersetzen. Gute Prüffrage: Versuche ich gerade, diese Person aus ihrer eigenen Realität heraus zu verstehen, oder benutze ich sie nur als Leinwand für heutige Urteile?","coreRule":"⚡ Verstehen und Urteilen schließen sich nicht aus. Falsch wird es, wenn das Urteil das Verständnis ersetzt.","quote":"Versuche ich gerade, diese Epoche/Person aus ihrer eigenen, komplexen Realität heraus zu verstehen?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.17 (Kernidee; Kipppunkt)","status":"entwurf","scenario":"In einer Diskussion über historische Figuren sagt jemand: „Wer vor 250 Jahren Menschen als Besitz gehalten hat, war eben ein Verbrecher, und alle damaligen Zeitgenossen gleich mit. Da gibt es nichts zu verstehen.“ Eine andere Person entgegnet: „Das ist unfair, man muss jede Zeit an ihren eigenen Maßstäben messen. Urteilen darf man über die Vergangenheit gar nicht.“","kurz":"Der erste Satz setzt ein heutiges Urteil an die Stelle des Verstehens, der zweite verbietet jedes Urteil. Beides ist verkürzt: Den Kontext zu beachten entschuldigt nichts, und wer verstehen will, darf trotzdem bewerten.","prueffrage":"Gab es vor 250 Jahren schon Menschen, die Sklaverei öffentlich als Unrecht bezeichneten, und wie reagierte ihre Umgebung darauf?","rueckmeldung":[{"option":0,"text":"Dass ein schnelles Urteil den Kontext ausblenden kann, stimmt. Der Kontext spricht aber niemanden frei: Man kann ihn nennen und trotzdem bewerten. Und der zweite Satz verbietet das Urteil ganz, auch das lässt sich nicht halten."},{"option":2,"text":"Dass Sklaverei Unrecht war, ist richtig. Dass sich moralische Maßstäbe nie verändert hätten, trägt aber nicht, und der Kontext ist keine Ausrede: Ohne ihn bleibt unverständlich, wie Menschen wie Jefferson ihre Widersprüche erlebten."},{"option":3,"text":"Den Kontext ernst zu nehmen, ist berechtigt. Daraus folgt aber kein Urteilsverbot: Verstehen und Bewerten schließen sich nicht aus, und späteren Generationen ein Urteil abzusprechen, wäre selbst eine unbegründete Absolutsetzung."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XVIII „Manners“ (Scholars' Lab, University of Virginia, Faksimile der Ausgaben 1784/1787)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/manners.html","seite":"Query XVIII","abruf":"2026-10-12"},{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XIV „Laws“ (Scholars' Lab, University of Virginia)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/laws.html","seite":"Query XIV","abruf":"2026-10-12"},{"typ":"url","kurz":"Hunt, L. (2002): From the President: Against Presentism. Perspectives on History (American Historical Association)","oeffentlich":true,"url":"https://historians.org/perspectives-article/against-presentism-may-2002/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b2-002","clusterId":"B","werkstueckRef":"B.17","stufe":2,"question":"Welche Entgegnung prüft die Schwärmerei von der „guten alten Zeit“ in der Sache, ohne selbst die Vorfahren abzuwerten?","scenario":"Beim Abendessen schwärmt ein Freund nach einem Historienfilm, der um 1800 spielt: „Früher waren die Menschen naturverbundener, hatten stärkere Gemeinschaften und keinen Stress. Wir sollten wieder so leben.“","options":["Man stellt der Schwärmerei überprüfbare Lebensdaten dieser Zeit gegenüber, etwa dass die Lebenserwartung um 1800 in keiner Weltregion über 40 Jahren lag, auch wegen vieler früh sterbender Kinder.","Man weist darauf hin, dass sich über frühere Lebensweisen nichts Zuverlässiges sagen lässt, sodass seine Aussage wie jede andere über diese Zeit gleich wertlos ist.","Man hält dagegen, dass heutige Gemeinschaften mindestens so eng sind wie damalige und der Freund die Nähe nur wegen Smartphones und Dauerstress nicht bemerkt.","Man erwidert, dass die Menschen früher moralisch rückständiger waren als wir und ihr Leben deshalb auch dann nicht erstrebenswert sein kann, wenn es äußerlich schön aussah."],"correctIndex":0,"explanation":"Die Schwärmerei pickt Ästhetisches heraus (schöne Kleider, keine Smartphones) und blendet Hunger, Krankheiten, Kindersterblichkeit, erdrückende soziale Kontrolle und fehlende Rechte aus. Der stärkste Einwand setzt dort an, wo sich etwas überprüfen lässt: Lebensdaten sind Tatsachen, kein Werturteil, und sie stellen das idealisierte Bild auf die Probe. Die Behauptung, über die Vergangenheit lasse sich nichts sagen, ist überzogen, denn es gibt belastbare Daten. Die Gegenbehauptung zu heutigen Gemeinschaften ist ebenso unbelegt wie die ursprüngliche Schwärmerei und tauscht nur eine Verklärung gegen eine andere. Die moralische Abwertung der Vorfahren ist die Kehrseite desselben Fehlers: Wer die Vergangenheit mit heutigen Maßstäben verurteilt, versteht sie genauso wenig wie wer sie verklärt. Gegen beides hilft der Blick auf den ganzen Alltag der Epoche.","coreRule":"⚡ Gegen die Verklärung der Vergangenheit helfen überprüfbare Daten über den ganzen Alltag der Epoche, nicht ihre Verurteilung.","beleg":"Werkstück B.17, Abschnitt „Die zweite, subtilere Falle: Die naive Romantisierung“ und Abschnitt „Bei Esoterik & New Age“; Fn. gl-b-lebenserwartung (Dattani u. a. 2023, Our World in Data)","status":"entwurf","kurz":"Lebensdaten sind überprüfbare Tatsachen und stellen das Idealbild auf die Probe, ohne die Vorfahren zu bewerten. Die Schwärmerei pickt Schönes heraus und blendet Hunger, Krankheit und früh sterbende Kinder aus.","prueffrage":"Welche Seiten des damaligen Lebens zeigt ein Historienfilm, und welche lässt er meistens weg?","rueckmeldung":[{"option":1,"text":"Über frühere Zeiten ist manches tatsächlich unsicher. Daraus folgt aber nicht, dass sich nichts sagen lässt: Es gibt belastbare Daten, und Aussagen sind deshalb nicht gleich wertlos."},{"option":2,"text":"Ein Gegengewicht zur Schwärmerei ist berechtigt. Doch dass heutige Gemeinschaften mindestens so eng seien, ist ebenso unbelegt wie das Idealbild des Freundes; so wird nur eine Verklärung gegen eine andere getauscht."},{"option":3,"text":"Frühere Zeiten hatten harte Seiten, etwa fehlende Rechte. Die Vorfahren pauschal als moralisch rückständig abzutun, misst sie aber an heutigen Maßstäben und prüft die Behauptung des Freundes nicht in der Sache."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dattani, S. u. a. (2023): Life Expectancy. Our World in Data","oeffentlich":true,"url":"https://ourworldindata.org/life-expectancy","abruf":"2026-10-12"},{"typ":"url","kurz":"Hunt, L. (2002): From the President: Against Presentism. Perspectives on History (AHA)","oeffentlich":true,"url":"https://historians.org/perspectives-article/against-presentism-may-2002/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Clauss, M. (2009): Ritter und Raufbolde. Vom Krieg im Mittelalter. Darmstadt: Primus","oeffentlich":false,"seite":"S. 7–8, 75–77"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b2-003","clusterId":"B","werkstueckRef":"B.17","stufe":3,"question":"Du hörst in einer Diskussion: „Thomas Jefferson hatte Sklaven – also war er ein monströser Heuchler.“ Jemand kontert: „Damals dachten eben alle so, also darf man ihn nicht verurteilen.“ Dann kommt der Hinweis, dass Jefferson die Sklaverei in einem eigenen Buch einen „unablässigen Despotismus“ nannte und schrieb, er zittere um sein Land, wenn er bedenke, dass Gott gerecht sei – im selben Buch äußerte er „nur als Verdacht“, Schwarze seien Weißen an Körper und Geist unterlegen. Was folgt daraus für das Argument „Damals dachten alle so“?","options":["Der Kontext verbietet jede Bewertung, weil Menschen einer fremden Epoche nur an den Maßstäben ihrer eigenen Zeit gemessen werden dürfen.","Der Kontext erklärt, aber entschuldigt nicht: Jefferson sah den Widerspruch selbst, und diesen zu verstehen bringt mehr als ein Etikett.","Der Kontext entlastet Jefferson weitgehend, weil Sklaverei damals als natürliche Ordnung galt und er sie nur kritisch kommentierte.","Der Kontext ist wertlos, weil es in jeder Zeit Menschen gab, die anders dachten als die Mehrheit, und an ihnen wird jede Figur gemessen."],"correctIndex":1,"explanation":"Beide Kurzschlüsse greifen zu kurz: weder „monströser Heuchler“ noch „Kind seiner Zeit, also unschuldig“. Dass alle gleich dachten, trifft nicht zu: Jefferson nannte die Sklaverei selbst einen „unablässigen Despotismus“, äußerte im selben Buch aber zugleich „nur als Verdacht“, Schwarze seien Weißen an Körper und Geist unterlegen. Den Widerspruch sah er also selbst. Das entschuldigt die Sklaverei nicht, aber es zu ignorieren, verhindert das Verständnis der tiefen Widersprüche, mit denen historische Akteure rangen.","coreRule":"⚡ Kontext ist eine Erklärung, kein Freispruch – und ohne ihn bleibt das Urteil blind.","beleg":"Werkstück B.17 (Anwendung: Bewertung historischer Figuren; Jefferson)","status":"entwurf","scenario":"","kurz":"Dass alle so dachten, stimmt hier nicht: Jefferson nannte die Sklaverei selbst „unablässigen Despotismus“ und äußerte zugleich den „Verdacht“, Schwarze seien unterlegen. Er sah den Widerspruch also selbst. Das entschuldigt nichts, erklärt aber mehr als ein Etikett.","prueffrage":"Was hat Jefferson selbst über die Sklaverei geschrieben, und deckt sich das mit der Behauptung, alle hätten damals gleich gedacht?","rueckmeldung":[{"option":0,"text":"Kontext gehört zum Verstehen einer Person tatsächlich dazu. Ein Bewertungsverbot folgt daraus aber nicht, zumal Jefferson die Sklaverei selbst „Despotismus“ nannte und sich so an seinen eigenen Maßstäben messen lassen muss."},{"option":2,"text":"Die Sklaverei war damals weit verbreitet, das stimmt. Dass sie allgemein als natürliche Ordnung galt, passt aber nicht zu Jeffersons eigenen Worten. Kritische Kommentare entlasten ihn auch nicht, sie zeigen eher, dass er den Widerspruch kannte."},{"option":3,"text":"Dass es auch damals Menschen gab, die anders dachten, trifft zu und widerlegt „alle dachten so“. Daraus folgt aber nicht, dass Kontext wertlos wäre. Er hilft zu verstehen, wie Einsicht und Handeln so weit auseinandergehen konnten."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XVIII „Manners“ (Scholars' Lab, UVA)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/manners.html","seite":"Query XVIII","abruf":"2026-10-12"},{"typ":"url","kurz":"Jefferson, T. (1787): Notes on the State of Virginia, Query XIV „Laws“ (Scholars' Lab, UVA)","oeffentlich":true,"url":"https://notes.scholarslab.org/milestones/laws.html","seite":"Query XIV","abruf":"2026-10-12"},{"typ":"url","kurz":"Hunt, L. (2002): Against Presentism. Perspectives on History (AHA)","oeffentlich":true,"url":"https://historians.org/perspectives-article/against-presentism-may-2002/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b2-004","clusterId":"B","werkstueckRef":"B.17","stufe":4,"question":"Welche Rückfrage prüft die Behauptung am besten, ohne sie sofort zu verwerfen oder zu übernehmen?","scenario":"Ein Politiker beschwört „die guten alten 50er“ und nennt heutige gesellschaftliche Veränderungen „Verfall und Dekadenz“.","options":["Hatten die Menschen damals moralisch überhaupt eine Wahl, und müssen wir sie von jeder Verantwortung freisprechen, weil sie es nicht besser wussten?","Wie viele Menschen glauben heute an diese Erzählung, und zeigt das, ob das Bild stimmt, weil Verbreitung ein guter Hinweis auf Wahrheit ist?","Waren die 50er nicht objektiv die beste Zeit, und lohnt sich jede Rückbesinnung schon deshalb, weil sie keine Prüfung braucht?","Wie sahen Alltag, Rechte und Gesundheit damals tatsächlich aus, und wozu wird dieses Bild heute gebraucht, etwa um Veränderungen als Verfall darzustellen?"],"correctIndex":3,"explanation":"Eine „goldene“ Vergangenheit ist oft ein idealisiertes Zerrbild: Man pickt die angenehmen Seiten heraus (schöne Kleider, keine Smartphones) und blendet den Rest aus, etwa hohe Kindersterblichkeit, fehlende Rechte oder soziale Kontrolle. Außerdem dient ein solches Bild häufig dazu, gegenwärtige Veränderungen, zum Beispiel mehr Rechte für Minderheiten, als Verfall darzustellen. Eine gute Prüfung fragt deshalb zweierlei: Wie sah der tatsächliche Alltag der Epoche aus, und welche Funktion hat das Bild in der heutigen Debatte? So wird die Behauptung weder pauschal abgetan noch übernommen. Dass viele Menschen eine Erzählung glauben, belegt dagegen nicht, dass sie stimmt.","coreRule":"⚡ Prüfe bei jeder „guten alten Zeit“, wie der Alltag damals tatsächlich aussah und wofür das Bild heute gebraucht wird.","beleg":"Werkstück B.17 (Anwendung: Verschwörungsmythen, rechts-konservative Variante; Red Flags)","status":"entwurf","kurz":"Ob das Bild der „guten alten Zeit“ trägt, zeigt erst der Blick auf den tatsächlichen Alltag der Epoche und die Frage, wozu das Bild heute gebraucht wird. Der naheliegende Fehler ist, nur die angenehmen Seiten zu sehen oder die Behauptung gleich zu verwerfen.","prueffrage":"Für wen waren die 50er „gut“, und wer hätte damals wohl ganz anders darüber gesprochen?","rueckmeldung":[{"option":0,"text":"Die Frage nach Entscheidungsfreiheit klingt gründlich, trifft aber nicht das Thema: Es geht darum, wie die Epoche wirklich aussah und wozu das Bild heute dient. Ein Freispruch von Verantwortung ist zudem eine Annahme, die nichts prüft."},{"option":1,"text":"Wie viele die Erzählung teilen, erklärt höchstens, warum sie wirkt. Ob sie stimmt, zeigt es nicht: Auch weit verbreitete Bilder können lückenhaft sein, und genau das bliebe so ungeprüft."},{"option":2,"text":"Hier steht das Ergebnis schon in der Frage: „objektiv die beste Zeit“ ist unbelegt, und „keine Prüfung nötig“ schließt gerade das aus, worum es geht. Ein solches Bild blendet oft Unangenehmes aus, etwa hohe Kindersterblichkeit oder fehlende Rechte."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dattani, S. u. a. (2023): Life Expectancy. Our World in Data","oeffentlich":true,"url":"https://ourworldindata.org/life-expectancy","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Clauss, M. (2009): Ritter und Raufbolde. Vom Krieg im Mittelalter. Darmstadt: Primus","oeffentlich":false,"seite":"S. 7–8, 75–77"}],"thema":"Zusammenleben"},{"id":"qx-b2-005","clusterId":"B","werkstueckRef":"B.18","stufe":1,"question":"Was ist an dieser Begründung für das Weitermachen fehlerhaft?","options":["Sie schließt aus dem bisherigen Ausbleiben eines Schadens auf Sicherheit und deutet das Schweigen der anderen als Zustimmung, obwohl es auch Selbstzensur sein kann.","Sie stützt sich auf die Erfahrung des Teams, doch Erfahrung ist grundsätzlich wertlos, weil vergangene Ereignisse nie etwas über die Zukunft aussagen.","Sie holt zu schnell eine Entscheidung herbei, doch Einigkeit in einer Gruppe ist grundsätzlich verdächtig und bedeutet immer, dass jemand getäuscht wurde.","Sie lässt Bedenken zu, ohne sie zu prüfen, doch dass das Team ihr nicht widerspricht, belegt für sich genommen, dass die Warnzeichen unbegründet waren."],"correctIndex":0,"explanation":"Zwei Schlüsse tragen hier nicht. Erstens: Dass dreimal nichts passiert ist, zeigt nicht, dass das Risiko klein ist. Ein Schaden, der bisher ausblieb, kann beim nächsten Mal eintreten. Genau so wurde bei der Challenger über Jahre der Dichtungsschaden als „annehmbares Risiko“ verbucht, weil Flug um Flug gut ging, bis der Start bei großer Kälte zur Katastrophe führte. Zweitens: Wer Bedenken ausdrücklich unerwünscht macht, darf Schweigen nicht als Zustimmung lesen. Ausbleibender Widerspruch kann auch Selbstzensur aus Angst vor Ausgrenzung sein. Hier wird aus einem individuellen Impuls („die anderen sehen es offenbar auch so“) über sozialen Druck ein Gruppendenken, bei dem Einigkeit wichtiger wird als eine gute Entscheidung. Der Gruppendruck erklärt solche Entscheidungen allerdings nur zum Teil; hinzu kommt die schleichende Normalisierung der Abweichung. Kritik gehört deshalb nicht unterdrückt, sondern gezielt eingeholt.","coreRule":"⚡ Wer „bisher ging es gut“ als Beweis nimmt und Schweigen als Zustimmung liest, übersieht Risiko und Selbstzensur.","beleg":"Werkstück B.18 (Kernidee; Analyse: Die drei Stufen; Abschnitt „Die Nacht erzählt allerdings nur das Ende“; Fn. gl-b-normalisierung)","status":"entwurf","scenario":"Ein Projektteam hat dreimal in Folge Warnzeichen für ein Qualitätsproblem bemerkt, jedes Mal ohne sichtbaren Schaden. In der Sitzung sagt die Leiterin: „Bisher ist immer alles gut gegangen, also verkraftet die Konstruktion das. Wenn jemand Bedenken hat, soll er sie bitte für sich behalten, wir sind uns doch alle einig.“","kurz":"Dreimal ohne Schaden zeigt nicht, dass das Risiko klein ist; der Schaden kann beim nächsten Mal eintreten. Und wo Bedenken unerwünscht sind, ist Schweigen kein verlässliches Zeichen von Zustimmung, es kann ebenso Selbstzensur sein.","prueffrage":"Was ist aus den drei Warnzeichen geworden, und wer im Team hat in der Sitzung überhaupt etwas dazu gesagt?","rueckmeldung":[{"option":1,"text":"Erfahrung ist durchaus eine Informationsquelle und nicht grundsätzlich wertlos. Das Problem ist der Schluss: Dreimal ohne Schaden belegt keine Sicherheit, weil ein Schaden beim nächsten Mal eintreten kann."},{"option":2,"text":"Dass der Druck zur Einigkeit hier heikel ist, stimmt. Einigkeit ist aber nicht grundsätzlich verdächtig, und niemand muss getäuscht worden sein: Fehlerhaft ist, Bedenken unerwünscht zu machen und Schweigen als Zustimmung zu lesen."},{"option":3,"text":"Die Leiterin lässt Bedenken ja gerade nicht zu, sondern bittet darum, sie für sich zu behalten. Und fehlender Widerspruch sagt unter solchem Druck nichts über die Warnzeichen aus, er kann ebenso Selbstzensur sein."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Columbia Accident Investigation Board (2003): Report, Bd. 1, Kap. 8 „History As Cause: Columbia and Challenger“","oeffentlich":true,"url":"http://s3.amazonaws.com/akamai.netstorage/anon.nasa-global/CAIB/CAIB_lowres_chapter8.pdf","seite":"S. 196","abruf":"2026-10-12"},{"typ":"url","kurz":"Rogers Commission (1986): Report, Bd. 1, Kap. V „The Contributing Cause of the Accident“ (NASA)","oeffentlich":true,"url":"https://www.nasa.gov/history/rogersrep/v1ch5.htm","abruf":"2026-10-12"},{"typ":"doi","kurz":"Esser, J. K.; Lindoerfer, J. S. (1989): Groupthink and the space shuttle Challenger accident. Journal of Behavioral Decision Making 2(3)","oeffentlich":false,"doi":"10.1002/bdm.3960020304","seite":"S. 173"}],"thema":"Zusammenleben"},{"id":"qx-b2-006","clusterId":"B","werkstueckRef":"B.18","stufe":2,"question":"Was ist an dieser Schlussfolgerung der Kollegin fehlerhaft?","scenario":"In der Teamsitzung stimmt dir eine Zahl nicht. Alle nicken, du schweigst – nicht weil du glaubst, die anderen wüssten es besser, sondern weil du nicht als Spielverderber dastehen willst. Später sagt dir eine Kollegin: „Du hast das ja einfach mitgetragen, also warst du überzeugt.“","options":["Sie hält dein Schweigen für Zustimmung, obwohl es auch aus Furcht vor sozialer Ablehnung entstehen kann und dann nichts über deine Überzeugung sagt.","Sie unterstellt dir Zustimmung, obwohl Schweigen in Gruppen fast immer Ablehnung bedeutet und nur selten Zustimmung.","Sie schließt aus deinem Verhalten auf eine Überzeugung, obwohl man die Meinung eines Menschen nur aus dem erfahren kann, was er laut sagt.","Sie vergisst, dass in Gruppen alle Mitglieder gleich viel Einfluss haben und deshalb ein einzelnes Schweigen nichts verändert."],"correctIndex":0,"explanation":"Äußeres Verhalten und innere Überzeugung fallen nicht zusammen. Es gibt zwei Gründe, sich einer Gruppe anzuschließen: Man hält die anderen für wissender (informativer Einfluss), oder man fürchtet Ausgrenzung, Lächerlichkeit oder Bestrafung (normativer Einfluss). Dein Schweigen entspringt dem zweiten Grund, und dann sagt das Nicken der Gruppe nichts darüber, was die Einzelnen wirklich denken. Genau so entsteht in eng verbundenen Gruppen die Illusion der Einstimmigkeit: Schweigen wird fälschlich als Zustimmung gedeutet, während Einzelne ihre Zweifel zurückhalten (Selbstzensur). In Asch-Experimenten gaben rund drei Viertel der Versuchspersonen mindestens einmal öffentlich eine offensichtlich falsche Antwort, nur weil alle anderen es taten. Wer Einigkeit nur an äußerer Zustimmung misst, kann sich täuschen. Eine gute Frage wäre: „Welche Argumente haben wir noch nicht gehört oder trauen uns nicht auszusprechen?“","coreRule":"⚡ Schweigen ist kein Beleg für Zustimmung: Es kann auch aus Angst vor dem Gruppenurteil entstehen.","beleg":"Werkstück B.18 (Stufe 2; Symptom 6 Selbstzensur)","status":"entwurf","kurz":"Aus deinem Schweigen auf Überzeugung zu schließen, trägt nicht: Du hast geschwiegen, weil du nicht auffallen wolltest, nicht weil du es glaubst. Verhalten und Überzeugung fallen nicht zusammen, wenn die Furcht vor Ablehnung das Verhalten lenkt.","prueffrage":"Wie viele der Nickenden hatten vielleicht eigene Bedenken, und woran hätte die Kollegin das von außen erkennen können?","rueckmeldung":[{"option":1,"text":"Dass Schweigen nicht automatisch Zustimmung bedeutet, stimmt. Fast immer Widerspruch bedeutet es aber auch nicht: Manche schweigen, weil sie zustimmen, andere aus Zweifel, und von außen lässt sich das nicht unterscheiden."},{"option":2,"text":"Richtig daran ist, dass Verhalten nicht immer die Überzeugung zeigt; doch auch Gesagtes kann unter Gruppendruck täuschen, und Verhalten verrät oft viel. Der Fehler ist nicht der Blick auf Verhalten, sondern Schweigen nur als Zustimmung zu lesen."},{"option":3,"text":"Wie viel Einfluss einzelne Mitglieder haben, ist hier gar nicht der Punkt, und gleich verteilt ist er in Gruppen meist nicht. Es geht darum, was dein Schweigen über dich aussagt, nicht darum, was es in der Gruppe bewirkt."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Spielman, R. M.; Jenkins, W. J.; Lovett, M. D.: Psychology 2e, Kap. 12.4 „Conformity, Compliance, and Obedience“ (OpenStax)","oeffentlich":true,"url":"https://openstax.org/books/psychology-2e/pages/12-4-conformity-compliance-and-obedience","abruf":"2026-10-12"},{"typ":"doi","kurz":"Asch, S. E. (1956): Studies of Independence and Conformity: I. A Minority of One Against a Unanimous Majority. Psychological Monographs 70(9)","oeffentlich":false,"doi":"10.1037/h0093718","seite":"S. 10–11"},{"typ":"doi","kurz":"Deutsch, M.; Gerard, H. B. (1955): A Study of Normative and Informational Social Influences upon Individual Judgment. Journal of Abnormal and Social Psychology 51(3)","oeffentlich":false,"doi":"10.1037/h0046408","seite":"S. 629–633"}],"thema":"Zusammenleben"},{"id":"qx-b2-007","clusterId":"B","werkstueckRef":"B.18","stufe":3,"question":"Ein Kommentator sagt: „Der Gruppendruck in der Nacht davor erklärt alles.“ Was spricht dagegen, diese Erklärung als vollständig zu akzeptieren?","options":["Die Dichtungsschäden waren schon bei früheren Flügen aufgetreten und galten als annehmbares Risiko, weil die Flüge gut gegangen waren.","Die oberste Startleitung hatte die Einwände der Ingenieure gehört und sie bewusst überstimmt, um den Zeitplan einzuhalten.","Die Dichtungen waren vor jener Nacht nie beschädigt worden, sodass niemand im Team das Risiko im Voraus erkennen konnte.","Die Ingenieure hatten ihre Bedenken nie ausgesprochen, sodass es in jener Nacht gar keinen Druck auf das Management gab."],"correctIndex":0,"explanation":"Eine einzelne dramatische Szene ist eine verlockende Ursache, aber selten die ganze. Hier hatten die Ingenieure dringend abgeraten, ihr Management revidierte die Warnung, und die oberste Startleitung erfuhr nach eigener Aussage nichts davon. Dahinter steht eine längere Vorgeschichte: Schon seit den ersten Flügen waren Dichtringe immer wieder angegriffen worden, ein Jahr zuvor nach Kältenächten besonders stark. Weil die Flüge trotzdem gut gingen, galt jeder neue Schaden als Beweis, dass die Konstruktion ihn verkraftet. Dieses Muster wird „Normalisierung der Abweichung“ genannt; die Untersuchung nach dem Absturz der Columbia 2003 fand es auch beim Isolierschaum wieder. Eine gute Ursachenanalyse fragt deshalb nicht nur, wer in der entscheidenden Nacht was sagte, sondern auch, welche Gewöhnung diese Entscheidung über Jahre vorbereitet hat.","coreRule":"⚡ Wer ein Unglück mit der letzten Entscheidung erklärt, übersieht oft die Gewöhnung an Warnzeichen, die Jahre vorher begann.","beleg":"Werkstück B.18; Fn. gl-b-challenger (Rogers Commission 1986, Bd. 1, Kap. V; Vaughan 1996); Fn. gl-b-normalisierung (CAIB 2003, Bd. 1, Kap. 8, S. 196–197)","status":"entwurf","scenario":"Vor einem Raumfähren-Start bei Kälte rieten Ingenieure des Herstellers der Feststoffraketen dringend ab: Die Dichtungen waren bei Kälte nicht für einen sicheren Start zertifiziert. Ihr Management gab am Vorabend dennoch die Freigabe, und die oberste Startleitung sagte später aus, von den Einwänden nichts gewusst zu haben. Schon bei früheren Flügen waren Dichtringe angegriffen worden, doch weil die Flüge gut gegangen waren, wurde der Schaden als „annehmbares Risiko“ geführt. Der Start endete in der Katastrophe.","kurz":"Die Nacht der Entscheidung ist nur der letzte Schritt: Schon bei früheren Flügen waren Dichtringe angegriffen worden und galten als annehmbar, weil es gut ausging. Wer nur die dramatische Szene betrachtet, übersieht diese Gewöhnung.","prueffrage":"Wer wusste in jener Nacht was über die Dichtungen, und seit wann war das bekannt?","rueckmeldung":[{"option":1,"text":"Dass jemand Einwände bewusst überging, klingt nach einer klaren Schuldfrage. Die oberste Startleitung sagte aber aus, von den Einwänden nichts gewusst zu haben; überstimmt wurde die Warnung im Management der Firma."},{"option":2,"text":"Wäre vorher nie etwas passiert, wäre die Katastrophe tatsächlich schwer vorherzusehen gewesen. Doch Dichtringe waren schon bei früheren Flügen angegriffen worden, und die Ingenieure warnten. Das Risiko war erkennbar, galt aber als annehmbar."},{"option":3,"text":"Dass Gruppendruck nicht alles erklärt, heißt nicht, dass es ihn nicht gab: Die Ingenieure hatten dringend abgeraten, und das Management nahm die Warnung zurück. Der Druck gehört zur Erklärung, nur reicht er allein nicht aus."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Rogers Commission (1986): Report, Bd. 1, Kap. V (NASA)","oeffentlich":true,"url":"https://www.nasa.gov/history/rogersrep/v1ch5.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"Columbia Accident Investigation Board (2003): Report, Bd. 1, Kap. 8 „History As Cause: Columbia and Challenger“","oeffentlich":true,"url":"http://s3.amazonaws.com/akamai.netstorage/anon.nasa-global/CAIB/CAIB_lowres_chapter8.pdf","seite":"S. 196–197","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Vaughan, D. (1996): The Challenger Launch Decision. Chicago: University of Chicago Press","oeffentlich":false}],"thema":"Technik und KI"},{"id":"qx-b2-008","clusterId":"B","werkstueckRef":"B.18","stufe":4,"question":"Was ist an dieser Schlussfolgerung der Vorsitzenden am ehesten fragwürdig?","scenario":"Ein Vorstand will Gruppendenken vermeiden. In jeder Sitzung muss reihum ein Mitglied die Rolle des „Advocatus Diaboli“ spielen und gegen den Beschlussvorschlag argumentieren. Nach einem halben Jahr fällt auf: Die Beschlüsse fallen weiterhin sehr schnell und fast immer einstimmig. Der Teufelsanwalt bringt regelmäßig Einwände vor, die nach kurzer Diskussion allen als „bekannt“ gelten. Die Vorsitzende deutet das als Beweis, dass die Gruppe gründlich prüft.","options":["Dass die Einwände bei einer zugewiesenen Rolle womöglich nur gespielt sind und deshalb leicht abgehakt werden, ohne dass ein Mitglied tatsächlich widerspricht.","Dass ein Gremium überhaupt Einwände sammelt, weil jede Kritik den Entscheidungsprozess verlangsamt und die Gruppe handlungsunfähig macht.","Dass die Rolle reihum vergeben wird, weil nur Mitglieder mit ausgeprägtem Fachwissen glaubwürdige Gegenargumente liefern können.","Dass einstimmige Beschlüsse zustande kommen, weil Einstimmigkeit in einer Gruppe grundsätzlich auf mangelnde Sorgfalt hindeutet."],"correctIndex":0,"explanation":"Ein Einwand, den jemand pflichtgemäß vorbringt, weil er an der Reihe ist, zeigt noch nicht, dass die Gruppe Widerspruch ernst nimmt. Das Ritual kann den Eindruck gründlicher Prüfung erwecken, ohne dass echter Widerspruch stattfindet. Dass jeder Einwand schnell als „bekannt“ gilt und die Beschlüsse einstimmig bleiben, ist eher ein Warnsignal. Echter, selbst geäußerter Widerspruch ist dagegen nicht an eine Rolle gebunden und wird eher als ernsthafte Alternative geprüft. Laut Experimenten war von sich aus geäußerter Widerspruch jeder geprüften Form des bestellten Teufelsanwalts überlegen. Das heißt nicht, dass die Rolle wertlos wäre, wohl aber, dass sie echten Widerspruch nicht ersetzt. Einstimmigkeit allein beweist weder Sorgfalt noch Nachlässigkeit; entscheidend ist, ob abweichende Meinungen real geäußert und ernsthaft geprüft werden können.","coreRule":"⚡ Ein bestellter Widerspruch ersetzt nicht die Kultur, in der echter Widerspruch erwünscht ist.","beleg":"Werkstück B.18 (Verbindungen: Advocatus Diaboli)","status":"entwurf","kurz":"Ein Einwand, den jemand nur vorbringt, weil er an der Reihe ist, zeigt nicht, dass Widerspruch ernst genommen wird. Dass jeder Einwand schnell als „bekannt“ gilt und alles einstimmig bleibt, ist eher ein Warnsignal als ein Beleg für Gründlichkeit.","prueffrage":"Wie oft hat in diesem halben Jahr ein Einwand einen Beschluss verändert, und wie lange wurde jeweils darüber gesprochen?","rueckmeldung":[{"option":1,"text":"Einwände kosten tatsächlich Zeit, deshalb wirkt das plausibel. Fragwürdig ist aber nicht, dass Einwände gesammelt werden, sondern wie die Vorsitzende deren Auftreten deutet. Kritik muss ein Gremium nicht lähmen."},{"option":2,"text":"Fachwissen hilft, überzeugende Gegenargumente zu finden. Um die Qualität der Argumente oder die Reihenfolge geht es hier aber nicht. Fragwürdig ist, dass ein pflichtgemäß vorgebrachter Einwand als Beleg für echte Prüfung gilt."},{"option":3,"text":"Anhaltende Einstimmigkeit kann tatsächlich ein Warnsignal sein. Daraus folgt aber keine Regel: Einstimmigkeit beweist weder Sorgfalt noch Nachlässigkeit. Fragwürdig ist, dass ein Einwand aus der zugewiesenen Rolle als echter Widerspruch gilt."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Nemeth, C.; Brown, K.; Rogers, J. (2001): Devil's advocate versus authentic dissent: stimulating quantity and quality. European Journal of Social Psychology 31(6), 707–720","oeffentlich":false,"doi":"10.1002/ejsp.58","seite":"S. 707, 713–717"},{"typ":"url","kurz":"Behavioral Scientist (2018): Stop Playing Devil's Advocate, and Other Advice for Better Decision Making (Interview mit Charlan Nemeth)","oeffentlich":true,"url":"https://behavioralscientist.org/stop-playing-devils-advocate-and-other-advice-for-better-decision-making/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-009","clusterId":"B","werkstueckRef":"B.19","stufe":2,"question":"Welche Frage prüft die Werbebehauptung am besten?","scenario":"Eine Broschüre für ein Nahrungsergänzungsmittel wirbt: „Studie belegt – zwei Gesundheitswerte verbessert!“ Im Kleingedruckten steht, dass die Studie insgesamt 50 verschiedene Gesundheitswerte erfasst hat. Über die übrigen 48 Werte schweigt die Broschüre.","options":["Wurde vor der Studie festgelegt, welche Werte als Erfolgskriterium gelten sollten, und wie sahen die übrigen gemessenen Werte aus?","Wie bekannt und etabliert ist das Unternehmen, das die Studie in Auftrag gegeben und bezahlt hat?","Wie viele Teilnehmer haben das Mittel subjektiv als angenehm und wirksam empfunden, als sie es einnahmen?","Wie groß war die Verbesserung der beiden genannten Werte im Vergleich zum Durchschnitt der Branche?"],"correctIndex":0,"explanation":"Wer 50 Werte misst, bekommt allein durch Zufall bei einigen davon eine scheinbar „signifikante“ Veränderung, ganz ohne jede Wirkung des Mittels. Entscheidend ist deshalb, ob die zwei Werte schon vor der Messung als Ziel festgelegt waren oder ob man sie erst im Nachhinein aus den Ergebnissen herausgepickt hat. Das ist, als würde man erst auf die Scheunenwand schießen und dann die Zielscheibe um die dichtesten Einschusslöcher malen. Und nur wenn man die übrigen 48 Werte kennt, lässt sich einschätzen, ob die zwei Treffer ein Volltreffer oder ein Zufallscluster sind. Die Bekanntheit des Auftraggebers, das subjektive Empfinden oder die Größe der Verbesserung sagen darüber nichts: Auch ein zufälliger Treffer kann groß ausfallen und glaubwürdig präsentiert werden.","coreRule":"⚡ Frag nie nur nach dem Treffer, sondern nach allen Schüssen und nach dem Zeitpunkt der Zielscheibe.","beleg":"Werkstück B.19 (Anwendung: Pseudomedizin und Nahrungsergänzungsmittel; Red Flags)","status":"entwurf","kurz":"Bei 50 gemessenen Werten treten allein durch Zufall bei einigen scheinbare Verbesserungen auf. Entscheidend ist deshalb, ob die zwei Werte vorab als Ziel feststanden und wie die übrigen 48 aussahen. Sonst malt man die Zielscheibe um die Einschusslöcher.","prueffrage":"Was würdest du bei 50 gemessenen Werten erwarten, wenn das Mittel überhaupt nichts bewirkt?","rueckmeldung":[{"option":1,"text":"Wer eine Studie bezahlt hat, spielt für die Einordnung eine Rolle, und ein bekannter Name klingt solide. Er sagt aber nicht, ob die zwei Werte vorab als Ziel feststanden oder aus 50 herausgepickt wurden, und genau darauf kommt es an."},{"option":2,"text":"Das Empfinden der Teilnehmer ist leicht zu erheben und wirkt nah an der Praxis. Es sagt aber nichts über die Auswahl der zwei Werte und lässt sich zudem von Erwartung und Gewohnheit färben. So lässt sich ein Zufallstreffer nicht erkennen."},{"option":3,"text":"Eine große Verbesserung klingt nach einem starken Beleg. Auch ein Zufallstreffer unter 50 Werten kann aber groß ausfallen und überzeugend präsentiert werden. Die Größe sagt nicht, ob man die zwei Werte erst nachträglich ausgewählt hat."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 21–22","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nosek, B. A. u. a. (2018): The preregistration revolution. PNAS 115(11) (frei über PMC5856500)","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-b2-010","clusterId":"B","werkstueckRef":"B.19","stufe":3,"question":"Ein Team wertet die Daten einer großen Befragung ohne vorab festgelegte Hypothese aus und stößt auf eine auffällige Häufung. Was darf es mit diesem Ergebnis redlicherweise tun?","options":["Die Häufung als vorläufige Hypothese festhalten und an einer neuen, unabhängigen Stichprobe gezielt prüfen, bevor sie als Befund gilt.","Auf die Auswertung verzichten und die Häufung nicht weiterverfolgen, da Muster ohne vorab festgelegte Hypothese nicht aussagekräftig sind.","Die Häufung als belegten Zusammenhang veröffentlichen, weil sie in einem so großen Datensatz klar zu erkennen war und deutlich auffällt.","Die Häufung als belegt ansehen, sobald sie einmal einen statistischen Signifikanztest bestanden hat, und sie dann als Befund weitergeben."],"correctIndex":0,"explanation":"Das Suchen nach Mustern ist legitim, denn so entstehen Hypothesen. Ein Arzt, der aus vielen unspezifischen Symptomen eine seltene Krankheit vermutet, tut genau das. Kritisch wird es erst, wenn der Fund als Beweis ausgegeben wird. In jeder ausreichend großen, zufälligen Datenmenge entstehen zwangsläufig Cluster, daher kann der erste Fund nur eine Hypothese sein. Erst die Prüfung an einem neuen, unabhängigen Datensatz zeigt, ob das Muster mehr ist als Rauschen. Pauschales Verwerfen wäre ebenso falsch, weil es die Quelle neuer Hypothesen abschneidet. Auch die Größe des Datensatzes ersetzt keine unabhängige Prüfung, denn die Hypothese muss vor der Datenerhebung aufgestellt oder anschließend fair getestet werden.","coreRule":"⚡ Ein gefundenes Muster ist der Anfang der Prüfung, nicht ihr Ergebnis.","beleg":"Werkstück B.19 (Adaptives Talent; Kipppunkt)","status":"entwurf","scenario":"Eine Forschungsgruppe hat 40 Merkmale von 3.000 Personen erhoben. Beim Durchsehen fällt auf, dass Menschen, die gern Rosenkohl essen, auffällig oft im Frühjahr Geburtstag haben. Die Gruppe überlegt, wie sie damit umgehen soll.","kurz":"Der erste Fund kann nur eine Hypothese sein, denn in vielen Daten entstehen zwangsläufig Zufallsmuster. Ob mehr dahintersteckt als Rauschen, zeigt erst die Prüfung an neuen, unabhängigen Daten. Als Befund wäre der Fund zu früh behauptet.","prueffrage":"Wie viele Merkmalspaare lassen sich bei 40 Merkmalen überhaupt miteinander vergleichen, und wie viele davon fallen zufällig auf?","rueckmeldung":[{"option":1,"text":"Dass ein Fund ohne vorab festgelegte Hypothese keinen Beleg liefert, stimmt. Wertlos ist er deshalb nicht: Aus solchen Auffälligkeiten entstehen Hypothesen, und die lassen sich anschließend prüfen. Wer ihn verwirft, schneidet diese Quelle ab."},{"option":2,"text":"Ein großer Datensatz wirkt gewichtig, und die Häufung fällt klar ins Auge. Wer aber viele Merkmale durchsucht, findet fast immer irgendwo ein Muster, auch wenn nichts dahintersteckt. Auffälligkeit ersetzt keine unabhängige Prüfung."},{"option":3,"text":"Ein bestandener Test wirkt wie ein Beleg. Hier entstand die Hypothese aber erst beim Blick auf dieselben Daten, und bei vielen möglichen Mustern besteht fast immer eines zufällig einen Test. Das sagt dann wenig über echte Zusammenhänge."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Nosek, B. A. u. a. (2018): The preregistration revolution. PNAS 115(11) (frei über PMC5856500)","oeffentlich":true,"doi":"10.1073/pnas.1708274114","abruf":"2026-10-12"},{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 22","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-b2-011","clusterId":"B","werkstueckRef":"B.19","stufe":4,"question":"Was müsste geprüft werden, bevor man der Meldung einen ursächlichen Zusammenhang abnimmt?","scenario":"Eine Zeitung berichtet über auffällig viele Krankheitsfälle in einer Straße. Die Fälle seien erst aufgefallen, nachdem Anwohner begonnen hatten, Erkrankte zu zählen. Die Zeitung führt die Häufung auf einen nahen Mobilfunkmast zurück und zeigt dazu eine Karte mit den Wohnorten der Betroffenen.","options":["Ob der Zufall die Häufung erklären kann, denn auch ohne jede Ursache bilden sich in einer Region gelegentlich Gruppen von Fällen.","Ob noch weitere Einzelschicksale aus derselben Straße gefunden werden können, denn mehr Fälle machen den Zusammenhang zwingender.","Ob der Betreiber des Mobilfunkmasts dazu Stellung nimmt, denn erst der Widerspruch der Gegenseite gilt als Prüfung.","Ob sich die Fälle auf einer Karte neben dem Mast einzeichnen lassen, denn räumliche Nähe macht den Zusammenhang sichtbar."],"correctIndex":0,"explanation":"In einer ausreichend großen, zufälligen Datenmenge entstehen zwangsläufig Cluster und scheinbar unwahrscheinliche Muster, auch wenn nichts dahintersteckt. Hier kommt hinzu, dass die Häufung erst beim Zählen aufgefallen ist. Ein solches nachträglich gefundenes Muster ist nur eine Hypothese. Bevor man ihm eine Bedeutung beimisst, muss geklärt werden, ob schon der Zufall genügt, um die Häufung zu erklären, und der Zusammenhang muss an einem neuen, unabhängigen Datensatz getestet werden. Weitere Einzelfälle, eine Karte oder eine Stellungnahme verstärken nur den Eindruck, prüfen aber nicht, ob das Muster mehr ist als Zufall.","coreRule":"⚡ Bevor ein Cluster eine Ursache bekommt, muss der Zufall als Erklärung ausgeschlossen sein.","beleg":"Werkstück B.19 (Red Flags: Cluster in geografischen Daten; Kontext & Tiefe; Das Adaptive Talent; Anti-Denkmuster)","status":"entwurf","kurz":"Eine Häufung, die erst beim Zählen aufgefallen ist, ist zunächst nur eine Hypothese. Zufällige Daten bilden von selbst Cluster, deshalb muss zuerst geklärt werden, ob der Zufall genügt, und danach ein unabhängiger Datensatz das Muster bestätigen.","prueffrage":"Wie viele Erkrankte gibt es im Durchschnitt in Straßen dieser Größe, auch weit weg von jedem Mast?","rueckmeldung":[{"option":1,"text":"Mehr Fälle aus derselben Straße wirken wie zusätzliche Belege. Sie stammen aber aus derselben nachträglichen Zählung und verstärken nur den Eindruck. Erst neue, unabhängige Daten würden das Muster tatsächlich testen."},{"option":2,"text":"Die Stellungnahme des Betreibers gehört zu einer fairen Berichterstattung. Sie sagt aber nichts darüber, ob die Häufung über den Zufall hinausgeht. Ein Widerspruch ersetzt keine Prüfung der Daten."},{"option":3,"text":"Die Karte macht die Nähe zum Mast anschaulich, und genau darin liegt ihre Wirkung. Ein nachträglich gesuchtes Muster lässt sich fast immer mit etwas in der Nähe verknüpfen. Nähe zeigt noch keine Ursache und prüft nicht, ob der Zufall genügt."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"CDC/CSTE (2013): Investigating Suspected Cancer Clusters and Responding to Community Concerns. MMWR 62(8)","oeffentlich":true,"url":"https://www.cdc.gov/mmwr/pdf/rr/rr6208.pdf","seite":"S. 3, 22","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-b2-012","clusterId":"B","werkstueckRef":"B.19","stufe":1,"question":"Welche Einordnung ist am besten begründet?","options":["Nach sieben Mal Kopf ist Zahl nun überfällig, weil sich Zufallsfolgen ausgleichen und das Gleichgewicht bald wiederherstellen.","Sieben Mal Kopf ist so unwahrscheinlich, dass die Münze mit hoher Wahrscheinlichkeit manipuliert worden sein muss.","Die Reihe beweist nichts, deshalb sollte man gar nicht weiter darauf achten und keine Hypothese dazu prüfen.","Solche Klumpen sind in langen Zufallsreihen gar nicht selten; eine Ursache wäre erst eine Vermutung, die an neuen Würfen zu prüfen wäre."],"correctIndex":3,"explanation":"Bei 100 Würfen gibt es viele Stellen, an denen eine solche Reihe beginnen könnte: Mindestens sieben Mal Kopf in Folge kommt bei einer fairen Münze in etwa jeder dritten Hunderterreihe vor, sieben gleiche Ergebnisse in Folge sogar in etwa jeder zweiten. Dein Freund hat erst die Daten angesehen und dann eine Erklärung um den Klumpen gebaut, wie jemand, der erst auf die Scheunenwand schießt und die Zielscheibe danach um die dichteste Stelle malt. Eine gezinkte Münze ist deshalb nur eine Hypothese, die an neuen, unabhängigen Würfen geprüft werden muss, bevor man ihr glaubt. Dass Zahl nun „überfällig“ sei, liest ebenfalls Bedeutung in den Zufall hinein, denn die Münze hat kein Gedächtnis. Die Reihe einfach abzutun, ohne die Vermutung fair zu testen, wäre der andere Fehler.","coreRule":"⚡ Wo Zufall wirkt, entstehen Klumpen, ohne dass jemand sie verursacht hat.","quote":"Der Fehler liegt darin, diesen Zufallsclustern eine Bedeutung beizumessen, nachdem man sie gefunden hat.","quoteLabel":"Merksatz:","beleg":"Werkstück B.19 (Werkbank-Frage; Analyse)","status":"entwurf","scenario":"Ein Freund wirft 100-mal eine Münze und schreibt jedes Ergebnis auf. In der Reihe findet er sieben Mal hintereinander Kopf. Er ist sicher: „Das kann kein Zufall sein. Entweder ist die Münze gezinkt, oder irgendetwas hat das Ergebnis beeinflusst.“","kurz":"Bei 100 Würfen gibt es viele Stellen, an denen eine solche Reihe beginnen könnte, deshalb sind solche Klumpen in Zufallsdaten nicht ungewöhnlich. Wer die Erklärung erst nach dem Blick auf die Daten sucht, hat nur eine Vermutung, die neue Würfe prüfen müssen.","prueffrage":"In wie vielen von zehn Hunderterreihen einer fairen Münze würdest du irgendwo sieben Mal Kopf hintereinander erwarten?","rueckmeldung":[{"option":0,"text":"Dass sich die Anteile auf lange Sicht annähern, stimmt sogar. Das geschieht aber durch die Masse neuer Würfe, nicht durch Ausgleich: Die Münze hat kein Gedächtnis, und nach sieben Mal Kopf ist Zahl nicht fälliger als vorher."},{"option":1,"text":"Sieben Mal Kopf an einer vorher festgelegten Stelle wäre selten. Bei 100 Würfen gibt es aber viele mögliche Startstellen, und die Reihe wurde erst nachträglich herausgepickt. Manipulation bleibt so eine Vermutung, die neue Würfe prüfen müssten."},{"option":2,"text":"Richtig ist, dass diese eine Reihe nichts beweist. Daraus folgt aber nicht, dass man die Vermutung gar nicht prüfen sollte: Sie lässt sich an neuen, unabhängigen Würfen fair testen, und genau das fehlt hier."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie auf einer Kursseite der University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1125","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","seite":"S. 1125"}],"thema":"Geld und Zahlen"},{"id":"qx-b2-013","clusterId":"B","werkstueckRef":"B.20","stufe":1,"question":"Ein Schätzexperiment: Menschen sehen ein Glücksrad, das zufällig bei 10 oder 65 stehen bleibt. Danach sagen sie, ob der Anteil afrikanischer Länder in der UNO über oder unter dieser Zahl liegt, und schätzen ihn. Wer die 10 sah, schätzt im Median 25 %, wer die 65 sah, 45 %. Wie lässt sich das am besten deuten?","options":["Nur Zahlen mit erkennbarem Bezug zur Frage beeinflussen Schätzungen; der Unterschied zwischen den Gruppen ist reiner Zufall.","Die Gruppe mit der hohen Zahl wusste vermutlich mehr über die Vereinten Nationen und schätzte deshalb höher.","Die Schätzungen blieben im Kern unverändert, die Teilnehmer wurden bei hoher Zahl nur insgesamt unsicherer.","Auch eine zufällige, völlig unpassende Zahl zieht Schätzungen in ihre Richtung."],"correctIndex":3,"explanation":"Die zufällige, bedeutungslose Zahl des Glücksrads wirkte als mentaler Anker: Die Schätzungen wurden in Richtung dieser ersten Zahl gezogen. Bei Schätzungen wirkt eine solche erste Zahl selbst dann, wenn sie erkennbar willkürlich ist. Mit anderem Vorwissen oder bloßer Unsicherheit lässt sich das nicht erklären, denn beide Gruppen schätzen jeweils zur gezeigten Zahl hin, also gerichtet verschoben. Auch ein Zufallsergebnis erklärt es nicht, weil sich der Unterschied von 25 % zu 45 % im Median auf die gezeigte Zahl zurückführen lässt (Tversky und Kahneman, 1974).","coreRule":"⚡ Die erste Zahl zieht dein Urteil zu sich, auch wenn sie nichts mit der Frage zu tun hat.","beleg":"Werkstück B.20; Fn. gl-b-anchoring (Tversky/Kahneman 1974, Science 185, S. 1128; Rad-Detail nach Kahneman 2012, Kap. 11)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Eine zufällig gezeigte, bedeutungslose Zahl hat die Schätzungen in ihre Richtung gezogen: 25 % nach der 10, 45 % nach der 65. Der naheliegende Fehler ist, hinter solchen Unterschieden Vorwissen oder Zufall zu vermuten, obwohl die Verschiebung gerichtet ist.","prueffrage":"Wie wurde entschieden, wer die 10 und wer die 65 zu sehen bekam, und welche Gruppe schätzte höher?","rueckmeldung":[{"option":0,"text":"Dass nur passende Zahlen etwas bewirken, wirkt einleuchtend. Der Unterschied von 25 % zu 45 % folgt aber der gezeigten Zahl: Wer die 65 sah, schätzte höher, obwohl die Zahl erkennbar willkürlich war."},{"option":1,"text":"Unterschiedliches Vorwissen könnte Gruppenunterschiede erklären. Das Glücksrad teilte die Zahlen aber zufällig zu, es gibt also keinen Grund für systematisch verschiedenes Wissen, und beide Gruppen schätzen jeweils zur gezeigten Zahl hin."},{"option":2,"text":"Eine ungewohnte Zahl kann durchaus verunsichern. Unsicherheit würde die Schätzungen aber eher streuen lassen, statt sie gerichtet zu verschieben: niedriger nach der 10, höher nach der 65."}],"familie":"anker-erkennen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie, Kursseite University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1128","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124","seite":"S. 1128"},{"typ":"literatur","kurz":"Kahneman, D. (2012): Schnelles Denken, langsames Denken. München: Siedler, Kap. 11","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-b2-014","clusterId":"B","werkstueckRef":"B.20","stufe":2,"question":"Wie wirkt der durchgestrichene Preis auf dein Urteil, und welche Frage prüft das Angebot am besten?","scenario":"Im Onlineshop steht neben einer Jacke: „UVP 199 €, jetzt nur 99 €!“ Du hattest vorher keine Vorstellung davon, was eine solche Jacke kosten sollte.","options":["Die 199 € wirkt vor allem auf Menschen ohne Preiswissen, denn Erfahrene rechnen sie heraus; frag dich, ob du den üblichen Preis aus Erfahrung schon kennst.","Die 199 € zieht dein Urteil in ihre Richtung, denn die hohe erste Zahl lässt 99 € billig erscheinen; frag dich, wie du den Preis ohne die 199 ganz neu bewerten würdest.","Die 199 € informiert dich zuverlässig über den Wert, denn sie zeigt den echten Vergleichspreis; frag dich, ob du mit den 99 € wirklich 100 € sparst.","Die 199 € bleibt wirkungslos, wenn dir die Jacke gefällt, denn dann zählt nur das Bedürfnis; frag dich, ob du die Jacke wirklich haben willst."],"correctIndex":1,"explanation":"Die durchgestrichene Zahl ist ein klassischer Anker: Die erste genannte Zahl setzt den Rahmen, in dem du die zweite beurteilst, und 99 € wirken günstig, weil sie neben 199 € stehen, nicht weil du den Wert der Jacke kennst. Gegen die Wirkung hilft die Frage, wie du den Preis bewerten würdest, wenn es die erste Zahl nie gegeben hätte. Preiswissen schützt nicht zuverlässig: In einem Versuch ließen sich auch erfahrene Immobilienmakler bei der Schätzung eines Hauswerts vom vorgegebenen Angebotspreis beeinflussen (Northcraft und Neale 1987). Der Streichpreis ist außerdem kein verlässlicher Beleg für den Wert, sondern ein hoher Anker, der den tatsächlichen Preis als Schnäppchen erscheinen lässt. Und ob dir die Jacke gefällt, sagt nichts darüber, ob der Preis angemessen ist; der Anker wirkt auf die Preisbewertung, nicht auf deinen Wunsch.","coreRule":"⚡ Bewerte jeden Preis so, als hättest du den ersten genannten nie gesehen.","quote":"Wenn diese erste Zahl/diese erste Information nie existiert hätte, wie würde ich diese Situation dann völlig neu und von Grund auf bewerten?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.20 (Anwendung: Preisgestaltung; Anti-Denkmuster)","status":"entwurf","kurz":"Die erste Zahl setzt den Rahmen: 99 € wirken günstig, weil 199 € daneben stehen, nicht weil du den Wert der Jacke kennst. Dieser Sog wirkt auch, wenn du dem Streichpreis nicht traust; dagegen hilft, den Preis ohne die 199 € neu zu bewerten.","prueffrage":"Was kosten vergleichbare Jacken bei anderen Händlern, und steht dort ebenfalls ein Streichpreis daneben?","rueckmeldung":[{"option":0,"text":"Preiswissen kann helfen, einen überhöhten Streichpreis zu durchschauen. Ankerzahlen beeinflussen aber auch das Urteil von Fachleuten, und dir fehlt hier ohnehin jede Vorstellung vom üblichen Preis."},{"option":2,"text":"Eine Preisempfehlung klingt nach Orientierung, ist aber nicht unbedingt der Wert der Jacke. Die 100 € Ersparnis gibt es nur gegenüber der durchgestrichenen Zahl, und gerade sie lässt den Preis wie ein Schnäppchen wirken."},{"option":3,"text":"Ob dir die Jacke gefällt, ist eine eigene Frage, die über die Angemessenheit des Preises nichts sagt. Der Anker wirkt auf die Preisbewertung, nicht auf deinen Wunsch, und beeinflusst sie deshalb auch dann, wenn du die Jacke unbedingt willst."}],"familie":"anker-erkennen","fertigkeit":"F4","quellen":[{"typ":"literatur","kurz":"Northcraft, G. B.; Neale, M. A. (1987): Experts, amateurs, and real estate: An anchoring-and-adjustment perspective on property pricing decisions. Organizational Behavior and Human Decision Processes 39(1), 84–97","oeffentlich":false},{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie, Kursseite University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1128","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-b2-015","clusterId":"B","werkstueckRef":"B.20","stufe":3,"question":"Welche Schlussfolgerung ist am besten begründet?","options":["Dieser Preisbefund ist weniger gesichert als gedacht. Dass Anker Schätzungen beeinflussen, ist davon unabhängig gut belegt.","Weil die Wiederholungen schwächere Effekte fanden, ist der Ankereffekt insgesamt widerlegt, auch bei Schätzungen und anderen Urteilen.","Ein einmal veröffentlichter Befund bleibt gültig, solange er nicht in allen Wiederholungen vollständig widerlegt wurde. Die schwächeren Effekte sind deshalb unerheblich.","Weil mehrere Wiederholungen etwas gefunden haben, wenn auch weniger, ist der ursprüngliche Befund in voller Stärke bestätigt."],"correctIndex":0,"explanation":"Misslingt die Wiederholung eines Versuchs oder fällt der Effekt viel schwächer aus, ist der ursprüngliche Befund weniger sicher, aber nicht automatisch widerlegt. Und er sagt nur etwas über genau diese Versuchsanordnung: Dass ein zufälliger Zahlenanker die Zahlungsbereitschaft stark lenkt, ist unsicher. Dass Anker Schätzungen verzerren, ist davon getrennt gut belegt, etwa durch das Glücksrad-Experiment von Tversky und Kahneman, in dem eine erkennbar zufällige Zahl die Schätzung des Anteils afrikanischer UN-Mitglieder verschob (Median 25 % gegenüber 45 %). Selbst Maniadis und Kollegen, die deutlich kleinere Effekte fanden als Ariely und seine Kollegen, halten Ankereffekte bei Bewertungen für real und bezweifeln nur deren Größe. Ein schwacher Befund ist also nicht gleich widerlegt.","coreRule":"⚡ Wird ein Befund schlechter bestätigt, ist er weniger sicher, nicht automatisch falsch. Prüfe, was genau wackelt, und wie stark.","beleg":"Werkstück B.20 (Analyse); Fn. gl-b-anker-preis (Ariely/Loewenstein/Prelec 2003, S. 75–77; Maniadis/Tufano/List 2014, AER 104(1), S. 277–290, dort: andere Studien fanden „(if any) much smaller effects“; Ankereffekte bei Bewertungen gelten dennoch als real, offen ist ihre Größe)","status":"entwurf","scenario":"Eine Kollegin sagt: „Ein Experiment hat gezeigt, dass Menschen mehr für einen Wein zahlen, wenn sie vorher die letzten Ziffern ihrer Sozialversicherungsnummer als Dollarbetrag notiert haben. Ein Zufallswert steuert also, was wir bereit sind zu zahlen.“ Später liest du, dass spätere Studien meist deutlich schwächere Effekte fanden, manche gar keine.","kurz":"Schwächere Wiederholungen machen den Preisbefund unsicherer, widerlegen ihn aber nicht automatisch. Er betrifft nur diese Anordnung; dass Anker Schätzungen verzerren, ist getrennt gut belegt. Wer „schwach“ mit „widerlegt“ gleichsetzt, schließt zu weit.","prueffrage":"Was genau fanden die späteren Studien im Vergleich zum ersten Versuch, und was wurde dort überhaupt gemessen?","rueckmeldung":[{"option":1,"text":"Die schwächeren Wiederholungen schwächen den Preisbefund tatsächlich. Eine Widerlegung des Ankereffekts insgesamt folgt daraus nicht: Bei Schätzungen ist er getrennt gut belegt, und die meisten Wiederholungen fanden noch einen kleineren Effekt."},{"option":2,"text":"Dass ein einzelner Befund nicht schon bei jedem Zweifel ungültig wird, stimmt. Deutlich schwächere oder ausbleibende Effekte in Wiederholungen machen ihn aber weniger sicher, sie sind also keineswegs unerheblich."},{"option":3,"text":"Ein schwacher Effekt in Wiederholungen kann in dieselbe Richtung zeigen und sieht deshalb nach Bestätigung aus. Fällt er aber deutlich kleiner aus, ist die ursprüngliche Stärke gerade nicht bestätigt, sondern unsicher."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Maniadis, Z.; Tufano, F.; List, J. A. (2013): One Swallow Doesn't Make a Summer: New Evidence on Anchoring Effects. CeDEx Discussion Paper 2013-07 (später AER 104(1), 277–290)","oeffentlich":true,"url":"https://www.nottingham.ac.uk/cedex/documents/papers/cedex-discussion-paper-2013-07.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185 (inoffizielle Kopie, Kursseite University of Washington)","oeffentlich":true,"url":"https://sites.stat.washington.edu/peter/498.Sp16/Tversky.pdf","seite":"S. 1128","abruf":"2026-10-12"},{"typ":"doi","kurz":"Ariely, D.; Loewenstein, G.; Prelec, D. (2003): „Coherent Arbitrariness“: Stable Demand Curves Without Stable Preferences. Quarterly Journal of Economics 118(1), 73–106","oeffentlich":false,"doi":"10.1162/00335530360535153"}],"thema":"Psychologie"},{"id":"qx-b2-016","clusterId":"B","werkstueckRef":"B.20","stufe":4,"question":"Welche Erklärung passt am besten dazu, dass die Zufallszahl die Schätzungen trotzdem verschiebt?","scenario":"In einem Versuch sollen Menschen schätzen, wie viel Prozent der Mitgliedstaaten der Vereinten Nationen afrikanische Länder sind. Vorher dreht die Versuchsleitung ein Glücksrad (Ergebnis: 65) und fragt: „Liegt der Anteil über oder unter dieser Zahl?“ Danach liegen die Schätzungen deutlich höher als bei einer Vergleichsgruppe, die ohne Rad schätzt. Du weißt: Das Rad war reiner Zufall, und niemand hielt die Zahl für eine Expertenauskunft.","options":["Die Zahl wirkt, weil Menschen sich Zahlen nur einmal merken können und auch bei neuen Informationen nicht mehr umdenken.","Die Zahl wirkt, weil die Schätzenden sie für eine Expertenauskunft halten und sie dann ungeprüft übernehmen.","Die Frage nach „darüber oder darunter“ ruft bevorzugt Wissen wach, das zur Zahl passt, und färbt so die anschließende Schätzung.","Die Schätzenden starten bei der Zahl und passen von dort aus immer zu wenig an, genau wie bei selbst gewählten Ausgangswerten."],"correctIndex":2,"explanation":"Das Rad war erkennbar zufällig, und niemand hielt die Zahl für eine Expertenauskunft; ungeprüftes Vertrauen erklärt den Effekt also nicht. Die klassische Erklärung „Anpassung und Verankerung“ (Start beim Anker, zu wenig Korrektur) gilt nach späteren Versuchen vor allem für selbst gewählte Ausgangswerte, hier aber war die Zahl vorgegeben. Bei vorgegebenen Ankern wirkt offenbar ein anderer Mechanismus: Schon die Frage, ob die Antwort über oder unter der Zahl liegt, ruft bevorzugt Wissen wach, das zu ihr passt. Dass Menschen sich Zahlen nur einmal merken und nie mehr umdenken könnten, ist eine Übertreibung, die das Beispiel nicht stützt. Wer die Erklärung eines Effekts prüft, sollte fragen, ob sie zu den Rahmenbedingungen passt; ob beide Mechanismen nebeneinander wirken, ist in der Forschung umstritten.","coreRule":"⚡ Anker wirken auf mehr als einem Weg: Prüfe bei einer Erklärung, ob sie zu den Umständen passt (vorgegebener oder selbst gewählter Anker), und ersetze die erste Zahl bewusst durch eine eigene Ausgangsschätzung.","beleg":"Werkstück B.20 (Analyse: Anpassung und Verankerung); Fn. gl-b-anker-mechanismus (Epley/Gilovich 2006, Psychological Science 17(4), S. 312, 317; Gegenposition Simmons/LeBoeuf/Nelson 2010)","status":"entwurf","kernregel":"⚡ Auch eine erkennbar zufällige Zahl kann Schätzungen verschieben, schon die Frage „darüber oder darunter?“ ruft passendes Wissen wach. Schätze deshalb zuerst eigenständig, bevor du eine vorgegebene Zahl beachtest.","kurz":"Bei einer vorgegebenen Zahl erklärt vermutlich schon die Frage „über oder unter dieser Zahl?“ den Effekt, weil sie passendes Wissen wachruft. Vertrauen in eine Auskunft scheidet aus, und Start mit zu wenig Korrektur passt eher zu selbst gewählten Werten.","prueffrage":"Was unterscheidet diese Zahl von einem Startwert, den die Schätzenden selbst gewählt hätten, und woher kam sie?","rueckmeldung":[{"option":0,"text":"Dass die Schätzungen an der Zahl hängen, ist tatsächlich zu beobachten. Daraus folgt aber nicht, dass Menschen sich Zahlen nur einmal merken und nie umdenken: Das ist überzogen, und das Beispiel stützt es nicht."},{"option":1,"text":"Ungeprüftes Vertrauen in eine Auskunft ist ein möglicher Grund, warum Zahlen wirken. Hier passt er nicht: Das Rad war erkennbar Zufall, und niemand hielt die Zahl für eine Expertenauskunft."},{"option":3,"text":"Start beim Anker und zu wenig Korrektur ist die bekannte Erklärung und gilt vor allem für selbst gewählte Ausgangswerte. Hier wurde die Zahl vorgegeben, deshalb erklärt sie den Effekt nicht am besten."}],"familie":"anker-erkennen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Association for Psychological Science: Abstract zu Epley, N.; Gilovich, T. (2006): The Anchoring-and-Adjustment Heuristic: Why the Adjustments Are Insufficient","oeffentlich":true,"url":"https://www.psychologicalscience.org/journals/psychological-science/j.1467-9280.2006.01704.x/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Epley, N.; Gilovich, T. (2006): The Anchoring-and-Adjustment Heuristic: Why the Adjustments Are Insufficient. Psychological Science 17(4), 311–318","oeffentlich":false,"doi":"10.1111/j.1467-9280.2006.01704.x","seite":"S. 312, 317"},{"typ":"literatur","kurz":"Simmons, J. P.; LeBoeuf, R. A.; Nelson, L. D. (2010): The effect of accuracy motivation on anchoring and adjustment: Do people adjust from provided anchors? Journal of Personality and Social Psychology 99(6)","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-b2-017","clusterId":"B","werkstueckRef":"B.21","stufe":1,"question":"Welche Erwiderung auf den Einwand des Ingenieurs prüft die Behauptung am besten, ohne die Ebenen von Werten und Fakten zu vermischen?","options":["Das Ziel steht fest. Offen ist nur der Weg, und ob er trägt, lässt sich mit den Berechnungen des Ingenieurs prüfen.","Der Ingenieur teilt das Ziel der Aktivistin, also stimmen auch seine Berechnungen, und sie sollte ihren Plan aufgeben.","Ziele zählen in solchen Debatten nicht. Nur wer die besseren Zahlen hat, darf über Energiepolitik mitreden.","Beide Seiten wollen das Richtige, also lässt sich nicht klären, wer sachlich recht hat. Es bleibt Geschmackssache."],"correctIndex":0,"explanation":"Die Aktivistin schließt von der guten Absicht auf die Richtigkeit ihrer Tatsachenannahmen und wehrt die Gegenzahlen mit einem Angriff auf Motive ab. Das vermischt zwei Ebenen: was erstrebenswert ist (Werte) und was tatsächlich funktioniert (Fakten). Das Ziel kann geklärt sein, während der Weg offen bleibt und sich anhand von Fakten und Daten klären lässt. Ob der Ingenieur recht hat, ist damit noch nicht entschieden. Das zeigt sich erst, wenn man seine Berechnungen prüft, nicht durch den Verweis auf moralische Überlegenheit. Falsch wäre es, aus dem geteilten Ziel auf die Richtigkeit der Berechnungen zu schließen, Ziele für irrelevant zu erklären oder die Tatsachenfrage für unentscheidbar zu halten. Gute Absichten sind kein Schutz vor schlechten Ergebnissen.","coreRule":"⚡ Eine gute Absicht macht die Tatsachenbehauptung nicht wahr.","beleg":"Werkstück B.21 (Kernidee; Anti-Denkmuster; Beispiel Aktivistin und Ingenieur)","status":"entwurf","scenario":"In einer Debatte über Energiepolitik sagt eine Aktivistin: „Wir kämpfen für die Rettung des Planeten, also stimmt auch unser Plan: Jede Kernenergie ist abzulehnen, und eine Versorgung allein aus Erneuerbaren ist machbar. Wer das bezweifelt, dem ist der Planet egal.“ Ein Ingenieur entgegnet: „Ich teile dein Ziel, aber meine Berechnungen zeigen, dass wir ohne Kernenergie keine stabile Versorgung gewährleisten können.“ Die Aktivistin antwortet: „Deine Zahlen sind nur Ablenkung. Wir haben die moralische Überlegenheit, und die zählt am Ende.“","kurz":"Das Ziel kann geklärt sein, während der Weg offen bleibt: Ob der Plan trägt, zeigt sich erst an den Berechnungen. Der Fehler wäre, von guter Absicht auf richtige Tatsachen zu schließen oder Gegenzahlen als Ablenkung abzutun.","prueffrage":"Was genau wirft die Aktivistin dem Ingenieur vor, und was sagt sie zu seinen Berechnungen selbst?","rueckmeldung":[{"option":1,"text":"Dass der Ingenieur das Ziel teilt, wirkt wie ein Argument für seine Seite. Doch auch bei ihm sagt die Absicht nichts über die Richtigkeit seiner Zahlen. Sie müssen genauso geprüft werden wie der Plan der Aktivistin."},{"option":2,"text":"Zahlen sind für die Wirksamkeit eines Plans wichtig, aber das Ziel bleibt dennoch eine Wertfrage, über die man sich verständigen kann. Es ist sogar die Grundlage, auf der man überhaupt von „funktioniert“ oder „funktioniert nicht“ spricht."},{"option":3,"text":"Dass beide das Richtige wollen, macht die Tatsachenfrage nicht zur Geschmackssache. Ob eine Versorgung ohne Kernenergie stabil läuft, lässt sich mit Daten und Berechnungen klären, unabhängig von den Absichten beider Seiten."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Ad Hominem“, „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Liu, B. S.; Ditto, P. H. (2013): What Dilemma? Moral Evaluation Shapes Factual Belief. Social Psychological and Personality Science 4(3), 316–323","oeffentlich":false,"doi":"10.1177/1948550612456045"}],"thema":"Zusammenleben"},{"id":"qx-b2-018","clusterId":"B","werkstueckRef":"B.21","stufe":2,"question":"Was lässt sich aus dieser Antwort über die Richtigkeit der Berechnungen schließen?","scenario":"In einer Debatte zur Energieversorgung legt ein Ingenieur Berechnungen vor, wonach sich eine stabile Stromversorgung mit der heutigen Technik und Speicherlösung nicht allein mit erneuerbaren Quellen sichern lässt. Die Gegenseite antwortet: „Sie arbeiten für eine moralisch korrupte Industrie. Unsere Sache ist gerecht, und das zählt am Ende.“","options":["Sie zeigt, dass die Sachfrage hinter der Moral zurücktreten muss, weil moralische Gründe am Ende den Ausschlag geben.","Sie zeigt, dass seine Zahlen falsch sein müssen, weil Branchenvertreter grundsätzlich nicht verlässlich sind.","Sie zeigt, dass beide Seiten recht haben, weil Zahlen und Moral nebeneinander gelten.","Sie zeigt nichts darüber, weil sich die Richtigkeit der Berechnungen nur an den Zahlen selbst klären lässt."],"correctIndex":3,"explanation":"Die Antwort greift das Motiv des Gegners an („moralisch korrupte Industrie“) und beruft sich auf die eigene gerechte Sache. Beides sind Aussagen über Absichten und Werte, keine über die Berechnungen. Ob eine Rechnung stimmt, hängt nicht davon ab, wer sie vorlegt oder wie gut die Ziele des Gegenübers sind. Auch wer ein moralisch hehres Ziel verfolgt, kann sich über die Fakten irren, und auch ein Gegner mit zweifelhaften Motiven kann richtig rechnen. Der Einwand wäre nur dann ein Argument, wenn er die Zahlen selbst prüft, etwa Annahmen, Rechenweg oder Datenquellen. Solange das nicht geschieht, bleibt die Sachfrage offen und muss mit den Zahlen geklärt werden.","coreRule":"⚡ Wer die Motive des Gegners angreift oder die eigene Moral betont, hat seine Zahlen noch nicht widerlegt.","beleg":"Werkstück B.21 (Eingangsszene; Analyse: Selbst-Immunisierung, Ad hominem)","status":"entwurf","kurz":"Der Einwand betrifft Motive und Werte, nicht die Zahlen, und sagt deshalb nichts darüber, ob sie stimmen. Der naheliegende Fehler ist, vom Absender oder von der guten Sache auf die Richtigkeit zu schließen. Geklärt wird die Frage nur an Annahmen, Rechenweg und Daten.","prueffrage":"Würde sich an den Berechnungen etwas ändern, wenn derselbe Ingenieur für einen Umweltverband arbeitete?","rueckmeldung":[{"option":0,"text":"Moral kann politische Entscheidungen mitprägen. Hier geht es aber um die Frage, ob die Berechnungen stimmen, und die entscheidet kein Werturteil. Auch wer ein gutes Ziel verfolgt, kann sich bei Fakten irren, die Sachfrage bleibt offen."},{"option":1,"text":"Wer in einer Branche arbeitet, kann Eigeninteressen haben, und das ist ein Grund, genauer hinzusehen. „Grundsätzlich unverlässlich“ trägt aber nicht: Auch mit zweifelhaften Motiven kann man richtig rechnen. Das zeigt sich erst an den Zahlen."},{"option":2,"text":"Zahlen und Moral sind verschiedene Ebenen, und beide haben ihre Berechtigung. Gefragt ist aber, ob die Berechnungen stimmen, und dazu sagt die Antwort der Gegenseite nichts; ein Recht beider Seiten folgt daraus nicht."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Ad Hominem“, „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-019","clusterId":"B","werkstueckRef":"B.21","stufe":3,"question":"In einer Debatte über Energiepolitik sagt eine Aktivistin: „Wir kämpfen für die Rettung des Planeten. Die Zahlen des Ingenieurs sind nur Ablenkung, er arbeitet für eine moralisch korrupte Industrie. Wir sind moralisch im Recht, und das zählt.“ Was ist an diesem Vorgehen der Kern des Fehlers?","options":["Sie schließt von der guten Absicht ihres Ziels auf die Richtigkeit ihrer Annahmen über den Weg dorthin und prüft die Zahlen deshalb nicht.","Sie beruft sich auf eine moralische Position, und das macht ihre Aussagen über die Fakten von vornherein unglaubwürdig.","Sie verlangt von ihren Mitstreitern Opfer, und das ersetzt bei ihnen die Prüfung der sachlichen Argumente durch Gruppenbindung.","Sie antwortet auf Zahlen mit einem Werturteil, und das beendet die Debatte über die Sache."],"correctIndex":0,"explanation":"Ob ein Ziel gut ist (Werte) und ob ein bestimmter Weg es erreicht (Fakten), sind zwei verschiedene Fragen. Die Aktivistin schließt von der guten Absicht auf die Richtigkeit ihrer Annahmen und wehrt Gegenargumente ab, indem sie die Motive des Ingenieurs angreift, statt seine Zahlen zu prüfen. Ob er recht hat, ist damit nicht entschieden, das ließe sich nur mit den Daten klären. Eine moralische Überzeugung ist dabei nicht das Problem, sie treibt oft Reformen an. Zum Fehler wird sie, wenn sie zur Lizenz wird, die Realität nicht mehr zu prüfen, und Fakten dann als moralisch minderwertig gelten.","coreRule":"⚡ Moral gibt das Ziel vor, aber den Weg dorthin entscheiden die Fakten.","beleg":"Werkstück B.21 (Adaptives Talent; Kipppunkt)","status":"entwurf","scenario":"","kurz":"Ob ein Ziel gut ist und ob ein bestimmter Weg es erreicht, sind zwei getrennte Fragen. Die Aktivistin macht aus der guten Absicht einen Beleg für ihre Annahmen und wehrt die Zahlen ab, statt sie zu prüfen.","prueffrage":"Womit begegnet die Aktivistin den Zahlen des Ingenieurs, und was davon betrifft die Zahlen selbst?","rueckmeldung":[{"option":1,"text":"Eine moralische Position sagt noch nichts über die Qualität der Fakten, die jemand vorbringt. Sie treibt oft Reformen an; problematisch wird sie erst, wenn sie als Grund dient, die Wirklichkeit nicht mehr zu prüfen."},{"option":2,"text":"Opfer und Gruppenbindung können Debatten tatsächlich prägen. Die Aktivistin verlangt hier aber von niemandem Opfer; ihr Fehler liegt darin, wie sie mit den Zahlen des Ingenieurs umgeht."},{"option":3,"text":"Ein Werturteil als Antwort auf Zahlen stört die Debatte tatsächlich. Es ist aber nur das Symptom: Der Kern liegt darin, dass sie vom guten Ziel auf die Richtigkeit ihrer Annahmen schließt."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Liu, B. S.; Ditto, P. H. (2013): What Dilemma? Moral Evaluation Shapes Factual Belief. Social Psychological and Personality Science 4(3), 316–323","oeffentlich":false,"doi":"10.1177/1948550612456045"},{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-020","clusterId":"B","werkstueckRef":"B.21","stufe":4,"question":"Was ist ein produktiver erster Zug in dieser Debatte?","scenario":"In deinem Verein streiten zwei Lager über die Methoden eines Tierschutz-Protests. Lager A sagt: „Wir blockieren Schlachthof-Zufahrten, denn das ist der einzige Weg, der der Sache gerecht wird.“ Lager B meint: „Die Blockaden schaden uns eher, weil sie Spenden und Unterstützung kosten.“ Beide wollen weniger Tierleid und halten sich für moralisch im Recht.","options":["Beide Lager erklären lassen, was sie antreibt, weil sich so zeigt, wessen Absichten reiner sind und wer deshalb eher recht hat.","Das Lager entscheiden lassen, das den stärkeren moralischen Anspruch vertritt, weil gute Absichten das verlässlichste Kriterium sind.","Das gemeinsame Ziel festhalten und getrennt davon prüfen, welcher Weg es nach den Daten am ehesten erreicht.","Sich auf einen Mittelweg einigen, weil beide Lager dann Zugeständnisse machen und der Streit schnell beendet ist."],"correctIndex":2,"explanation":"Hier streiten zwei Lager nicht über Werte, sondern über eine Tatsachenfrage: Welcher Weg führt tatsächlich zum gemeinsamen Ziel? Gute Absichten sagen nichts darüber, ob eine Methode wirkt. Wer die Debatte auf die Reinheit der Motive oder die Stärke des moralischen Anspruchs lenkt, ersetzt die Faktenprüfung durch Selbstvergewisserung: Man kann das Richtige wollen und sich trotzdem über den Weg irren. Auch ein Kompromiss ist keine Prüfung. Er fragt nicht, welcher Weg das Ziel tatsächlich erreicht, sondern nur, wie sich beide Lager treffen. Sinnvoll ist deshalb, das Ziel als geklärt zu betrachten und die Wege an Fakten und Daten zu messen: Wie haben ähnliche Aktionen auf Spenden, Mitglieder und öffentliche Meinung gewirkt? Erst dann lässt sich begründet entscheiden.","coreRule":"⚡ Erst das Ziel klären, dann die Wege an den Fakten messen.","beleg":"Werkstück B.21 (Anti-Denkmuster; Verbindungen: Stahlmann-Argument)","status":"entwurf","kurz":"Beide wollen weniger Tierleid; offen ist nur, welcher Weg das erreicht, und das ist eine Tatsachenfrage. Gute Absichten sagen nichts über Wirkung, deshalb zählen Daten zu ähnlichen Aktionen mehr als Selbstvergewisserung.","prueffrage":"Wenn sich herausstellte, dass Blockaden tatsächlich Spenden kosten, würde das etwas an den Absichten von Lager A ändern?","rueckmeldung":[{"option":0,"text":"Die Beweggründe zu hören schafft Verständnis, sagt aber nichts über Wirkung. Beide Lager wollen ohnehin weniger Tierleid, und selbst reine Motive garantieren nicht, dass eine Methode ihr Ziel erreicht."},{"option":1,"text":"Der moralische Anspruch wirkt wie ein klares Kriterium. Beide Lager halten sich aber für im Recht, und ein starker Anspruch zeigt nicht, ob Blockaden das Ziel erreichen. Man kann das Richtige wollen und sich über den Weg irren."},{"option":3,"text":"Ein Mittelweg beendet den Streit womöglich schnell. Er fragt aber nur, wie sich beide Lager treffen, nicht, welcher Weg das Ziel erreicht. Die Mitte zwischen zwei Positionen muss nicht die wirksamste sein."}],"familie":"absicht-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Liu, B. S.; Ditto, P. H. (2013): What Dilemma? Moral Evaluation Shapes Factual Belief. Social Psychological and Personality Science 4(3), 316–323","oeffentlich":false,"doi":"10.1177/1948550612456045"},{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Faulty Motives“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-021","clusterId":"B","werkstueckRef":"B.22","stufe":1,"question":"Was erklärt am besten, warum so viele Menschen nicht erkennen können, ob das Posting ernst gemeint ist?","options":["Ohne erkennbaren Hinweis auf die Absicht kann eine Parodie auf Extremes nicht von echtem Extremismus unterschieden werden, weil dieser oft ebenso absurd klingt.","Wer so etwas schreibt, glaubt es mit Sicherheit selbst nicht, weil jede derart extreme Aussage nur der Provokation dient und nie aufrichtig gemeint sein kann.","Im Internet wird jeder Text grundsätzlich als ernst gemeint gelesen, deshalb kann Satire dort nie als Satire erkannt werden, ganz gleich, wie sie gebaut ist.","Echte Extremisten erkennen Parodien auf sich selbst immer sofort, deshalb muss die Uneinigkeit bedeuten, dass beide Lager aus echten Anhängern bestehen."],"correctIndex":0,"explanation":"Ohne Tonfall, Mimik und Körpersprache fehlen im Netz die Signale, an denen man im Gespräch Satire von Ernst unterscheidet. Hinzu kommt: Die Wirklichkeit des Extremismus ist oft so bizarr, dass eine Parodie davon kaum noch abweicht. Deshalb kann dieselbe Aussage für den einen ein Witz und für den anderen aufrichtig sein, und echter Extremismus wird umgekehrt manchmal für Satire gehalten. Ein Beispiel: Die Bewegung „Birds Aren’t Real“ war von Anfang an Satire, wurde aber von Fremden häufig für echte Verschwörungsgläubigkeit gehalten. Die Unsicherheit liegt also im fehlenden Kontext, nicht in einer erkennbaren Gesinnung des Verfassers. Sinnvoll ist deshalb, Kontext und Absicht zu prüfen, statt vorschnell nach dem eigenen Eindruck zu urteilen.","coreRule":"⚡ Ohne klaren Hinweis auf die Absicht lässt sich Satire über Extremes nicht verlässlich von echtem Extremismus unterscheiden: Prüfe Kontext und Absicht, statt nur nach deinem Eindruck zu urteilen.","beleg":"Werkstück B.22 (Kernidee; Analyse); Fn. gl-b-poe (Nathan Poe 2005; Aikin 2013)","status":"entwurf","scenario":"Auf einer Social-Media-Plattform erscheint der Beitrag: „Alle Tauben sind Überwachungsdrohnen der Regierung. Wer das noch bezweifelt, ist naiv.“ Kein Emoji, kein Hinweis auf Ironie, keine Angabe zum Autor. Unter dem Beitrag streiten sich die Leute: Ein Teil stimmt empört zu, ein anderer Teil lacht über den vermeintlichen Witz. Eine Person fragt: „Ist das ernst gemeint oder Satire?“ Niemand kann es sicher sagen.","kurz":"Im Netz fehlen Tonfall und Mimik, und echter Extremismus klingt oft so absurd wie eine Parodie darauf. Der naheliegende Fehler ist, von der Aussage selbst auf die Absicht zu schließen; ohne Kontext lässt sich das nicht entscheiden.","prueffrage":"Was an diesem Beitrag, außerhalb seines Wortlauts, würde etwas über die Absicht des Verfassers verraten?","rueckmeldung":[{"option":1,"text":"Extreme Aussagen dienen tatsächlich manchmal nur der Provokation. Von der Aussage allein lässt sich aber nicht sicher auf die Absicht schließen, denn echter Extremismus klingt oft ebenso bizarr. Hier fehlt der Kontext, um das zu entscheiden."},{"option":2,"text":"Dass im Netz Tonfall und Mimik fehlen, erschwert das Erkennen von Satire wirklich. Daraus folgt aber nicht, dass es nie gelingt: Kennzeichnung, Kontext und Autor können die Absicht klären. Hier fehlen genau diese Hinweise."},{"option":3,"text":"Eine feste Regel über Extremisten verspricht eine schnelle Erklärung, ist aber unbelegt; selbst wenn sie gälte, folgte daraus nicht, dass beide Lager aus Anhängern bestehen. Die Uneinigkeit zeigt eher, dass der Beitrag ohne Kontext mehrdeutig ist."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Poe's law","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Poe%27s_law","abruf":"2026-10-12"},{"typ":"url","kurz":"TED (2023): How to Be a Better Human – Do we have something to learn from conspiracy theories? (w/ Peter McIndoe), Transkript","oeffentlich":true,"url":"https://www.ted.com/podcasts/how-to-be-a-better-human/do-we-have-something-to-learn-from-conspiracy-theories-w-peter-mcindoe-transcript","abruf":"2026-10-12"},{"typ":"doi","kurz":"Aikin, S. F. (2013): Poe's Law, group polarization, and argumentative failure in religious and political discourse. Social Semiotics 23(3), 301–317","oeffentlich":false,"doi":"10.1080/10350330.2012.719728"}],"thema":"Netz und Medien"},{"id":"qx-b2-022","clusterId":"B","werkstueckRef":"B.22","stufe":2,"question":"Was ist an dieser Schlussfolgerung fehlerhaft?","options":["Aus der Größe der Menge folgt nicht, dass die Menschen glauben, was sie auf den Schildern zeigen; sie könnten mitspielen, und der Auftritt allein erlaubt keinen sicheren Schluss.","Aus der Größe der Menge folgt zu wenig, denn erst bei einigen Tausend Teilnehmern ließe sich sagen, dass tatsächlich viele Menschen an diese Behauptung glauben.","Der Schluss ist fehlerhaft, weil eine Kundgebung nie etwas über die Überzeugungen der Teilnehmer aussagt, sondern nur über die Motive der Organisatoren.","Der Schluss ist richtig, denn wer öffentlich für eine Behauptung demonstriert, vertritt sie auch ernsthaft, sonst würde er nicht an der Kundgebung teilnehmen."],"correctIndex":0,"explanation":"Von außen sehen Ernst und Spiel gleich aus: Wer ein Schild hochhält, kann glauben, was darauf steht, oder die Rolle des Gläubigen bewusst spielen. Genau so war es bei der Bewegung „Birds Aren’t Real“: Ihr Gründer Peter McIndoe gab 2021 öffentlich zu, dass sie von Anfang an Satire war, und viele der jungen Leute auf den Kundgebungen kannten den Witz und spielten die Gläubigen nur. Wer allein aus Auftritt und Menge auf aufrichtigen Glauben schließt, behandelt eine Möglichkeit als Tatsache. Solange keine Hinweise auf die Absicht vorliegen, ist die ehrliche Antwort Unsicherheit und der nächste Schritt eine Prüfung des Kontexts.","coreRule":"⚡ Wo Satire und Ernst gleich klingen, entscheidet nur der Kontext der Absicht.","beleg":"Werkstück B.22 (Eingangsszene); Fn. gl-b-birds (Lorenz 2021, New York Times, 9.12.2021; McIndoe im TED-Podcast 24.07.2023; NPR 08.12.2023)","status":"entwurf","scenario":"Eine Bewegung behauptet auf Schildern, alle Vögel seien von der Regierung durch Überwachungsdrohnen ersetzt worden. Zu ihren Kundgebungen kommen Hunderte junge Leute. Eine Zeitung schreibt: „Hunderte Menschen glauben ernsthaft, dass es keine echten Vögel gibt. So weit ist der Verschwörungswahn gekommen.“","quote":"","quoteLabel":"","kurz":"Ein Schild und eine große Menge sehen bei Ernst und Spiel gleich aus. Wer daraus aufrichtigen Glauben ableitet, macht aus einer Möglichkeit eine Tatsache; ohne Hinweise auf die Absicht bleibt nur Unsicherheit.","prueffrage":"Was genau hat die Zeitung gesehen, und was davon verrät, was in den Köpfen der Teilnehmenden vorgeht?","rueckmeldung":[{"option":1,"text":"Eine höhere Teilnehmerzahl wirkt wie ein stärkerer Beleg. Zahl und Aufrichtigkeit sind aber verschiedene Dinge: Auch Tausende könnten mitspielen. Eine Mindestmenge, ab der Glauben bewiesen wäre, gibt es nicht."},{"option":2,"text":"Dass der Auftritt allein nichts sicher zeigt, stimmt. „Nie“ und „nur“ gehen aber zu weit: Eine Kundgebung kann durchaus etwas über Überzeugungen verraten, nur reicht sie allein nicht, um Ernst von Spiel zu unterscheiden."},{"option":3,"text":"Öffentliches Eintreten für eine Behauptung wirkt wie ein Bekenntnis. Wer ein Schild hochhält, kann aber auch nur eine Rolle spielen. Teilnahme beweist daher keinen Glauben, und der Schluss der Zeitung steht auf unsicherem Boden."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Birds Aren't Real","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Birds_Aren%27t_Real","abruf":"2026-10-12"},{"typ":"url","kurz":"TED (2023): How to Be a Better Human – Peter McIndoe, Transkript","oeffentlich":true,"url":"https://www.ted.com/podcasts/how-to-be-a-better-human/do-we-have-something-to-learn-from-conspiracy-theories-w-peter-mcindoe-transcript","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Lorenz, T. (2021): Birds Aren't Real, or Are They? Inside a Gen Z Conspiracy Theory. The New York Times, 9.12.2021","oeffentlich":false}],"thema":"Netz und Medien"},{"id":"qx-b2-023","clusterId":"B","werkstueckRef":"B.22","stufe":3,"question":"Ein Mitglied der Gruppe sagt: „Das war doch nur ein Witz, versteht ihr keinen Spaß?“ Was ist an dieser Verteidigung als Beweis dafür, dass die Memes harmlos sind, fehlerhaft?","scenario":"In einer Online-Gruppe kursieren hasserfüllte Memes. Wird die Gruppe dafür kritisiert, heißt es regelmäßig: „Das war doch nur ein Witz, versteht ihr keinen Spaß?“ Weitere Hinweise auf Ironie, etwa Übertreibung gegen die eigene Position oder eine erkennbare Pointe, gibt es nicht.","options":["Die Selbstauskunft „nur ein Witz“ lässt sich nicht prüfen und ändert nichts an der Wirkung: Die Botschaft verbreitet sich, die Verantwortung wird abgelehnt.","Die Verteidigung ist fehlerhaft, weil Witze über Hass grundsätzlich unmöglich sind und jede Ironie über solche Themen ernst gemeint ist.","Die Verteidigung ist fehlerhaft, weil die Kritiker mit ihrer Empörung selbst zeigen, dass die Memes eine ernste Botschaft transportieren.","Die Verteidigung ist fehlerhaft, weil sie nur von Gruppenmitgliedern vorgebracht wird und Aussagen von Beteiligten deshalb nie etwas belegen."],"correctIndex":0,"explanation":"Ob etwas Satire ist, entscheidet nicht die nachträgliche Behauptung des Absenders, sondern der Kontext und die erkennbare Absicht des Autors. Online fehlen Tonfall, Mimik und Körpersprache, deshalb sind Ironie und Ernst oft nicht zu trennen (Poe’s Law). Genau das lässt sich ausnutzen: Wer hasserfüllte Memes verbreitet und sich bei Kritik auf „nur ein Witz“ zurückzieht, normalisiert seine Ideologie und lehnt zugleich jede Verantwortung dafür ab. Satire ist ein gesundes Ventil und ein hochentwickeltes soziales Werkzeug, aber der Hinweis „nur ein Witz“ ersetzt weder Kontext noch erkennbare Absicht. Nützliche Prüffragen sind: Gibt es erkennbare Ironiesignale, etwa Emojis oder ein „/s“? Gibt es eine etablierte Gruppe von Menschen, die genau das aufrichtig glaubt? Und was verrät der Kontext über die Absicht des Autors?","coreRule":"⚡ „War nur Spaß“ ist kein Beweis für Satire, sondern oft der Rückzugsraum für Ernst.","beleg":"Werkstück B.22 (Anwendung: politischer Extremismus & Trolle; Kipppunkt)","status":"entwurf","kurz":"„Nur ein Witz“ ersetzt weder Kontext noch erkennbare Absicht, und Ironie lässt sich online oft nicht von Ernst trennen. Wer Hass verbreitet und sich bei Kritik darauf zurückzieht, normalisiert ihn und lehnt zugleich die Verantwortung ab.","prueffrage":"Welche erkennbaren Signale im Meme selbst zeigen, dass der Autor die Aussage nicht ernst meint?","rueckmeldung":[{"option":1,"text":"Die Sorge ist verständlich, denn Hass wird tatsächlich oft als Scherz getarnt. Daraus folgt aber nicht, dass Ironie über solche Themen unmöglich wäre: Satire kann ein sinnvolles Ventil sein. Entscheidend sind Kontext und erkennbare Absicht."},{"option":2,"text":"Die Kritik kann berechtigt sein, aber die Empörung der Kritiker beweist die Absicht des Autors nicht. Der Fehler liegt woanders: Die Gruppe ersetzt Kontext und erkennbare Absicht durch eine nachträgliche Behauptung."},{"option":3,"text":"Eine Selbstauskunft entscheidet tatsächlich nicht darüber, ob etwas Satire ist. Dass Aussagen von Beteiligten „nie“ etwas belegen, geht aber zu weit. Der Mangel ist, dass „nur ein Witz“ an die Stelle von Kontext und Ironiesignalen tritt."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Poe's law","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Poe%27s_law","abruf":"2026-10-12"},{"typ":"doi","kurz":"Aikin, S. F. (2013): Poe's Law, group polarization, and argumentative failure in religious and political discourse. Social Semiotics 23(3), 301–317","oeffentlich":false,"doi":"10.1080/10350330.2012.719728"}],"thema":"Netz und Medien"},{"id":"qx-b2-024","clusterId":"B","werkstueckRef":"B.22","stufe":4,"question":"Welches Vorgehen ist hier am sinnvollsten?","scenario":"Eine Kollegin teilt eine unglaubliche Schlagzeile: „Bericht: Bundesregierung will Schulpflicht durch freiwilliges Lernen per App ersetzen“. Du hältst es für einen Scherz, bist dir aber nicht sicher. Auf Nachfrage sagt sie nur: „Klingt doch total plausibel, oder?“","options":["Du entscheidest sofort, dass es Satire ist, weil die Meldung so abwegig klingt und die Wirklichkeit niemals so absurd sein kann.","Du prüfst Quelle, Kontext und mögliche Absicht und fragst dich, ob jemand das wirklich ernsthaft vertritt, bevor du dich festlegst.","Du schließt aus dem fehlenden Ironiezeichen, dass die Meldung ernst gemeint ist, weil Scherze sonst deutlich als solche markiert wären.","Du liest die Kommentare darunter und folgst der Mehrheit, weil viele Leser die Absicht eines Textes besser erkennen als eine Einzelne."],"correctIndex":1,"explanation":"Ob ein Text ernst oder ironisch gemeint ist, lässt sich aus dem Inhalt allein oft nicht ablesen. Die Wirklichkeit des Extremismus und des Verschwörungsglaubens ist mitunter bizarrer als jede Parodie, und Satire-Seiten werden regelmäßig für echte Nachrichten gehalten. „Zu absurd, um ernst zu sein“ ist deshalb kein sicherer Schluss. Ebenso wenig beweist ein fehlendes Ironiezeichen Ernsthaftigkeit: Im Netz fehlen Tonfall und Mimik ohnehin, und Satire arbeitet oft bewusst mit Mehrdeutigkeit. Auch die Mehrheit in der Kommentarspalte hilft kaum, denn dort streiten sich häufig beide Lager, die Empörten und die Lachenden. Verlässlich ist der Blick auf Quelle, Kontext und Absicht und die Frage, ob eine reale Gruppe genau das aufrichtig glaubt.","coreRule":"⚡ Absurdität allein entscheidet nicht über Satire; Kontext und Quelle tun es.","quote":"Unabhängig davon, ob ich das persönlich für einen Witz halte: Gibt es eine etablierte Gruppe von Menschen, die genau das aufrichtig glaubt? Bevor ich reagiere, sollte ich den Kontext und die Absicht des Autors prüfen.","quoteLabel":"Beispielgedanke:","beleg":"Werkstück B.22 (Anti-Denkmuster; Red Flags; Anwendung: Fake News & Satire)","status":"entwurf","kurz":"Ob ein Text ernst oder ironisch gemeint ist, verrät der Inhalt allein oft nicht. Wer Quelle, Kontext und Absicht prüft, fragt nach etwas Überprüfbarem, statt vom bloßen Eindruck „zu absurd“ oder „klingt plausibel“ auf die Wahrheit zu schließen.","prueffrage":"Woran hast du bisher festgemacht, dass es ein Scherz sein könnte, und wie sicher ist dieses Zeichen?","rueckmeldung":[{"option":0,"text":"Die Meldung wirkt tatsächlich abwegig, und Satire ist gut möglich. „Zu absurd“ ist aber kein sicherer Maßstab: Die Wirklichkeit ist mitunter bizarrer als jede Parodie, und Satire-Seiten werden regelmäßig für echte Nachrichten gehalten."},{"option":2,"text":"Ein fehlendes Ironiezeichen wirkt wie ein Hinweis auf Ernst. Es beweist aber nichts: Im Netz fehlen Tonfall und Mimik ohnehin, und Satire arbeitet oft bewusst mit Mehrdeutigkeit, ohne sich zu kennzeichnen."},{"option":3,"text":"Viele Stimmen wirken verlässlicher als eine einzelne. Unter solchen Meldungen streiten sich aber häufig beide Lager, die Empörten und die Lachenden, und eine Mehrheit dort sagt kaum etwas über die Absicht."}],"familie":"satire-oder-ernst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Wikipedia: Poe's law","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Poe%27s_law","abruf":"2026-10-12"},{"typ":"doi","kurz":"Aikin, S. F. (2013): Poe's Law, group polarization, and argumentative failure in religious and political discourse. Social Semiotics 23(3), 301–317","oeffentlich":false,"doi":"10.1080/10350330.2012.719728"}],"thema":"Netz und Medien"},{"id":"qx-b2-025","clusterId":"B","werkstueckRef":"B.23","stufe":1,"question":"Welcher Denkfehler steckt im Schluss des Moderators?","options":["Er nimmt an, die Wahrheit liege in der Mitte, obwohl die Seiten unterschiedlich gut belegt sind.","Er nimmt an, die Wahrheit liege bei der extremeren Position, weil sie dem Widerspruch am deutlichsten Ausdruck verleiht.","Er nimmt an, beide Seiten verfolgten dasselbe Ziel und stritten nur über die Mittel, es zu erreichen.","Er nimmt an, ein Kompromiss sei nicht möglich, sobald sich zwei Positionen in ihren Aussagen widersprechen."],"correctIndex":0,"explanation":"Die Ozeanografin stützt sich auf Messdaten, der Gast nur auf Internetrecherchen ohne belastbare Fakten. Der Moderator wendet eine Kompromiss-Heuristik an, die bei Geschmacksfragen oft taugt (Kino oder Theater? Dann eben ein gemeinsames Abendessen), und überträgt sie auf eine Tatsachenfrage. Die Realität ist aber nicht verpflichtet, zwischen einer belegten und einer unbelegten Aussage zu liegen. Wenn eine Seite erdrückende Belege hat und die andere keine, liegt die Wahrheit bei den Belegen, nicht in der Mitte.","coreRule":"⚡ Die Wahrheit liegt bei den Beweisen, nicht automatisch in der Mitte.","beleg":"Werkstück B.23 (Eingangsszene Ozean/Gin; Kernidee; Analyse; Fußnoten: keine). Frage vom Definitionsabruf zur Fehlererkennung am konkreten Fall umgebaut.","status":"entwurf","scenario":"In einer Podiumsdiskussion sagt eine Ozeanografin: „Nach allen verfügbaren Messdaten ist der Ozean mit Wasser gefüllt.“ Ein Gast widerspricht: „Nach meinen Recherchen im Internet ist der Ozean mit reinem Gin gefüllt.“ Der Moderator fasst zusammen: „Zwei extreme Positionen. Die Wahrheit liegt wohl in der Mitte. Der Ozean ist also eine Art verdünnter Martini.“","kurz":"Der Moderator behandelt eine Tatsachenfrage wie eine Geschmacksfrage, bei der man sich in der Mitte trifft. Die Wahrheit liegt aber nicht automatisch zwischen zwei Aussagen: Eine stützt sich auf Messdaten, die andere auf nichts Belastbares.","prueffrage":"Worauf stützt sich jede der beiden Aussagen, und wie gut lässt sich das jeweils nachprüfen?","rueckmeldung":[{"option":1,"text":"Der Moderator spricht zwar von „extremen Positionen“, schlägt sich aber auf keine Seite, sondern sucht die Mitte. Sein Fehler ist, den Mittelweg für die Wahrheit zu halten, obwohl nur eine Seite Belege hat."},{"option":2,"text":"Im Gespräch geht es nicht um Ziele oder Mittel, sondern um eine Sachfrage: Was ist im Ozean? Von gemeinsamen Zielen ist nirgends die Rede, und der Moderator unterstellt sie auch nicht. Sein Schluss hängt an der Mitte zwischen zwei Aussagen."},{"option":3,"text":"Der Moderator schlägt ja gerade einen Kompromiss vor, er hält ihn also nicht für unmöglich. Bei Geschmacksfragen taugt ein Mittelweg oft, bei einer Tatsachenfrage mit einer belegten und einer unbelegten Seite gibt er nicht die Wirklichkeit wieder."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Wikipedia: Argument to moderation","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Argument_to_moderation","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „False Balance“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Harker, D. (2015): Creating Scientific Controversies: Uncertainty and Bias in Science and Society. Cambridge University Press","oeffentlich":false}],"thema":"Netz und Medien"},{"id":"qx-b2-026","clusterId":"B","werkstueckRef":"B.23","stufe":2,"question":"Zwei Menschen streiten und sollen sich einigen. In welchem der folgenden Fälle ist ein Mittelweg eine vernünftige, pragmatische Lösung?","options":["Zwei Gutachten kommen zu entgegengesetzten Ergebnissen: Das eine hält eine Brücke für standsicher, das andere nicht. Als Ergebnis wird ein Mittelwert beider Aussagen festgelegt.","Bei einer Verhandlung will die eine Seite ein Feuer löschen, die andere es anfachen. Als Kompromiss lässt man das halbe Haus abbrennen.","Beim Streit darüber, ob ein Impfstoff wirkt, wird ein Teil der Daten übernommen und ein Teil verworfen, bis beide Seiten zufrieden sind.","Eine Freundin will ins Kino, ein Freund ins Theater. Sie verbringen den Abend mit einem gemeinsamen Essen, das beiden recht ist."],"correctIndex":3,"explanation":"Ein Mittelweg taugt dort, wo es um Vorlieben geht und beide Seiten ein gemeinsames Ziel haben, nämlich einen schönen gemeinsamen Abend. Dann ist ein Kompromiss tatsächlich eine gute, pragmatische Lösung. Bei den anderen Fällen geht es um Tatsachen oder um grundsätzlich entgegengesetzte Ziele. Ob eine Brücke hält oder ein Impfstoff wirkt, lässt sich nicht aushandeln, das entscheiden Messungen und Daten. Der Wert zwischen „sicher“ und „unsicher“ ist kein Ergebnis, sondern ein Unsinn. Und wer das Feuer löschen will und wer es legen will, hat kein gemeinsames Ziel: Das halbe Haus abbrennen zu lassen, wäre ein voller Sieg für den Brandstifter. Die Mitte zwischen einer gut belegten Aussage und einer unbelegten ist nicht automatisch wahr; die Wahrheit liegt dort, wo die Belege liegen.","coreRule":"⚡ Kompromisse gehören in die Welt der Präferenzen, nicht in die Welt der Tatsachen.","beleg":"Werkstück B.23 (Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Ein Mittelweg trägt, wenn es um Vorlieben geht und beide dasselbe Ziel haben, hier einen guten gemeinsamen Abend. Bei Tatsachen oder gegensätzlichen Zielen taugt die Mitte nicht automatisch: Dort zählen Belege, nicht der Kompromiss.","prueffrage":"Was hätte jede Seite in den einzelnen Fällen nach der Einigung, und wäre danach etwas falsch oder gefährlich?","rueckmeldung":[{"option":0,"text":"Wenn Gutachten sich widersprechen, braucht es eine Entscheidung, und ein Mittelwert wirkt wie ein Ausgleich. Ob eine Brücke hält, entscheiden aber Berechnung und Messung, und ein Wert zwischen „sicher“ und „unsicher“ bedeutet nichts."},{"option":1,"text":"Dass jede Seite etwas bekommt, klingt nach fairem Kompromiss. Beide verfolgen hier aber entgegengesetzte Ziele, und das halbe Haus abbrennen zu lassen, wäre ein voller Erfolg für den, der das Feuer anfachen will."},{"option":2,"text":"Wenn beide Seiten zufrieden sind, scheint der Streit gelöst. Ob ein Impfstoff wirkt, ist aber eine Tatsachenfrage, die die Daten entscheiden, und ein Ergebnis nach Zufriedenheit der Streitenden sagt darüber nichts aus."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Wikipedia: Argument to moderation","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Argument_to_moderation","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-027","clusterId":"B","werkstueckRef":"B.23","stufe":3,"question":"In einer Schlichtung schlägt jemand vor: „Der Brandstifter will, dass das Haus brennt, die Feuerwehr will es löschen – einigen wir uns darauf, dass nur das halbe Haus abbrennt.“ Was ist an diesem Vorschlag das Kernproblem?","options":["Der Vorschlag macht schon das Verhandeln mit dem Brandstifter zum Fehler, weil jedes Gespräch mit ihm sein Vorgehen ermutigt und rechtfertigt.","Der Vorschlag tut so, als lägen beide Ziele auf derselben Waage, obwohl sie gegensätzlich sind: Das halbe Haus zu opfern wäre für eine Seite ein voller Sieg.","Der Vorschlag übersieht, dass der Brandstifter in der Faktenfrage lügt, während die Feuerwehr die Wahrheit sagt und das mit Belegen untermauern kann.","Der Vorschlag lässt außer Acht, dass beide Seiten dasselbe Ziel haben und nur über die Methode streiten, weshalb ein Mittelweg beiden Seiten nützen würde."],"correctIndex":1,"explanation":"Ein Kompromiss ist nur sinnvoll, wenn die Positionen symmetrisch genug sind. Hier sind die Ziele grundlegend asymmetrisch: Das eine Ziel ist, dass nichts brennt, das andere, dass es brennt. „Das halbe Haus“ klingt nach Mitte, wäre aber ein kompletter Sieg für den Brandstifter und eine komplette Niederlage für die Feuerwehr. Die Mitte zwischen zwei Positionen ist also nicht automatisch die vernünftigste Lösung, sondern kann ein Ergebnis sein, das nur einer Seite nützt. Man kann drei Arten von Asymmetrie unterscheiden: Fakten, Ziele und Macht. Vor einem Kompromiss lohnt die Prüfung, ob die Positionen symmetrisch genug sind.","coreRule":"⚡ Prüfe vor jedem Kompromiss, ob die Ziele überhaupt auf derselben Waage liegen.","beleg":"Werkstück B.23 (Das Problem der Asymmetrie; Kipppunkt)","status":"entwurf","scenario":"","kurz":"Eine Mitte ist nur sinnvoll, wenn die Positionen einigermaßen symmetrisch sind. Hier will die eine Seite, dass es brennt, die andere, dass nichts brennt. Das halbe Haus klingt nach Mitte, wäre aber ein voller Sieg für den Brandstifter.","prueffrage":"Was genau will die Feuerwehr erreichen, und was genau der Brandstifter?","rueckmeldung":[{"option":0,"text":"Ob man mit einem Brandstifter reden sollte, ist eine andere Frage und hier gar nicht gestellt. Das Problem liegt im Inhalt des Vorschlags: Er erklärt das halbe Haus zur Mitte, obwohl es für eine Seite ein voller Erfolg wäre."},{"option":2,"text":"Ungleiche Faktenlage kann einen Kompromiss tatsächlich schief machen. Im Vorschlag geht es aber nicht um Fakten, von einer Lüge ist keine Rede. Die Schieflage liegt in den Zielen: Eine Seite will, dass es brennt, die andere, dass es nicht brennt."},{"option":3,"text":"Beide Seiten wollen hier gerade nicht dasselbe: Die eine will das Feuer, die andere will es verhindern. Deshalb nützt die Mitte nicht beiden. Das halbe Haus wäre für den Brandstifter ein voller Sieg und für die Feuerwehr eine volle Niederlage."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Wikipedia: Argument to moderation","oeffentlich":true,"url":"https://en.wikipedia.org/wiki/Argument_to_moderation","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-028","clusterId":"B","werkstueckRef":"B.23","stufe":4,"question":"Was ist an dem Schluss der Zuschauerin fehlerhaft, und was hat die Sendung damit zu tun?","scenario":"Eine Talkshow lädt zur Klimafrage eine Klimawissenschaftlerin und einen Leugner ein, beide mit exakt gleichen Redeanteilen. Eine Zuschauerin sagt danach: „Dann liegt die Wahrheit wohl irgendwo dazwischen. Ganz so schlimm wird es nicht, aber ein bisschen was ist vielleicht dran.“","options":["Die Sendung bleibt neutral, und der Fehler liegt allein bei der Zuschauerin, die den Stand der Fachwelt nicht beachtet.","Die Sendung erzeugt den Anschein gleichwertiger Seiten, und die Zuschauerin löst die ungleiche Beweislage als Mittelweg auf.","Die Sendung zeigt zwei Seiten, und die Zuschauerin irrt, weil ein Mittelweg zwischen Positionen in der Wissenschaft nie zulässig ist.","Die Sendung handelt richtig, und die Zuschauerin urteilt korrekt, weil eine Redaktion Positionen nie nach ihrer Beweislage gewichten darf."],"correctIndex":1,"explanation":"Die gleichwertige Darstellung beider Seiten erzeugt den Eindruck, beide Positionen stünden auf gleich festem Boden. Wer diesen Eindruck übernimmt, rechnet die Positionen zu einem „vernünftigen“ Kompromiss zusammen. Bei Tatsachenfragen gibt es aber keine Pflicht der Wirklichkeit, zwischen einer gut belegten Aussage und einer durch gar keine Beweise gestützten zu liegen. Der Schluss auf die Mitte ist hier ein Trugschluss, weil er die ungleiche Beweislage ignoriert. Und die Sendung hängt damit zusammen, weil die Darstellung als gleichwertig diesen Schluss nahelegt. Zugleich bleibt der Mittelweg bei Geschmacks- und Interessenfragen oft vernünftig. Entscheidend ist, die Positionen vorher nach Belegen zu gewichten, statt sie als gleichwertig zu behandeln.","coreRule":"⚡ Gleich viel Redezeit heißt nicht gleich viel Belege.","beleg":"Werkstück B.23 (Anwendung: Journalismus; Verbindungen: Falsche Ausgewogenheit)","status":"entwurf","kurz":"Gleiche Redeanteile lassen beide Seiten gleich gut belegt wirken, und daraus rechnet sich leicht ein Kompromiss. Bei Tatsachenfragen liegt die Wahrheit aber nicht von selbst in der Mitte, wenn eine Seite gut belegt ist und die andere kaum.","prueffrage":"Wie viel Redezeit bekam jede Seite, und entspricht das dem Anteil der Fachleute, die jeweils so urteilen?","rueckmeldung":[{"option":0,"text":"Die Zuschauerin zieht tatsächlich einen Fehlschluss, doch die Sendung ist daran beteiligt. Wer beiden Seiten exakt gleich viel Raum gibt, erweckt den Eindruck, sie stünden auf gleich festem Boden, und ebnet so dem Schluss auf die Mitte den Weg."},{"option":2,"text":"Der Schluss der Zuschauerin trägt nicht, aber nicht, weil ein Mittelweg grundsätzlich verboten wäre. Bei Geschmacks- und Interessenfragen ist er oft vernünftig; problematisch ist er bei ungleicher Beweislage wie in dieser Tatsachenfrage."},{"option":3,"text":"Gleiche Behandlung wirkt fair und unparteiisch. Bei Tatsachenfragen verdeckt sie aber, dass die Positionen unterschiedlich gut belegt sind. Eine Gewichtung nach Belegen ist deshalb kein Verstoß, sondern notwendig."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „False Balance“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Northwestern University, SESP Magazine (Sommer 2022): The Perils of Bothsidesism","oeffentlich":true,"url":"https://sesp.northwestern.edu/magazine/summer-2022/the-perils-of-bothsidesism.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Imundo, M. N.; Rapp, D. N. (2022): When Fairness is Flawed: Effects of False Balance Reporting and Weight-of-Evidence Statements on Beliefs and Perceptions of Climate Change. Journal of Applied Research in Memory and Cognition","oeffentlich":false}],"thema":"Netz und Medien"},{"id":"qx-b2-029","clusterId":"B","werkstueckRef":"B.24","stufe":1,"question":"Was ist an dieser Erklärung der Reporterin am ehesten fehlerhaft?","options":["Sie führt ein Geschehen mit vielen zusammenwirkenden Ursachen auf einen einzigen Schuldigen zurück und lässt die übrigen Faktoren unbeachtet.","Sie hält zwei Ereignisse, die zeitgleich auftreten, für ursächlich verbunden, ohne den Zusammenhang zwischen beiden zu prüfen.","Sie lässt die Ursachen im Dunkeln, weil sie zu viele mögliche Erklärungen für gültig hält und sich auf keine einzelne festlegt.","Sie erklärt den Bauleiter für bedeutungslos, weil er das Unglück allein nicht erklären kann, ohne seinen Beitrag näher zu prüfen."],"correctIndex":0,"explanation":"Ein Unglück wie dieses entsteht in der Regel aus dem Zusammenspiel vieler Faktoren: Materialermüdung, Belastung, Wartung und Wetter greifen ineinander. Die Reporterin reduziert das auf einen einzigen Bösewicht. Das ist leicht zu erzählen und emotional befriedigend, blendet aber alle übrigen Beiträge aus und führt zu einer scheinbar einfachen Lösung, nämlich den Bauleiter auszutauschen. Bleiben Materialermüdung und mangelnde Wartung bestehen, kann die nächste Brücke genauso versagen. Dass der Bauleiter einen Anteil gehabt haben kann, ist damit nicht ausgeschlossen. Der Fehler liegt darin, ihn zur alleinigen Ursache zu erklären. Eine bloße zeitliche Koinzidenz, ein Überangebot an Erklärungen oder die Abwertung eines einzelnen Beitrags beschreiben den Mangel dieser Aussage nicht.","coreRule":"⚡ Wo viele Faktoren zusammenwirken, ist die Erklärung mit einem einzigen Schuldigen verdächtig. Frag dich: Welche weiteren Faktoren könnten beigetragen haben?","beleg":"Werkstück B.24 (Kernidee; Analyse)","status":"entwurf","scenario":"Nach dem Einsturz einer Brücke sagt eine Reporterin im Fernsehen: „Die Wahrheit ist ganz einfach: Der Bauleiter hat geschlampt, er ist an allem schuld.“ Ein Gutachten nennt zugleich mehrere Faktoren: ein Baumaterial, das über Jahre ermüdet ist, eine Überlastung durch Schwerverkehr, aufgeschobene Wartungsarbeiten und ungewöhnlich starke Regenfälle.","kurz":"Die Reporterin macht aus dem Zusammenspiel von Materialermüdung, Überlastung, aufgeschobener Wartung und Starkregen eine Geschichte mit einem einzigen Schuldigen. Das ist leicht erzählt, blendet aber die übrigen Ursachen aus, auch wenn der Bauleiter beteiligt gewesen sein kann.","prueffrage":"Wie viele Faktoren nennt das Gutachten, und wie viele davon kommen in der Erklärung der Reporterin vor?","rueckmeldung":[{"option":1,"text":"Vorschnelle Schlüsse auf Ursachen sind ein häufiger Fehler, deshalb passt diese Beschreibung scheinbar. Die Reporterin verbindet aber keine zwei gleichzeitigen Ereignisse, sie macht aus vielen Ursachen eine einzige."},{"option":2,"text":"Eine Aussage, die sich nicht festlegt, wäre tatsächlich unbefriedigend. Die Reporterin legt sich aber eindeutig fest, und zwar auf nur eine Ursache. Sie lässt nicht zu viele Erklärungen gelten, sondern zu wenige."},{"option":3,"text":"Dass ein Einzelner das Unglück nicht allein erklärt, trifft zu. Die Reporterin wertet den Bauleiter aber nicht ab, sie macht ihn zum alleinigen Schuldigen. Sein Anteil kann real gewesen sein, nur reicht er allein nicht als Erklärung."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Reason, J. (2000): Human error: models and management. BMJ 320(7237), 768–770","oeffentlich":true,"doi":"10.1136/bmj.320.7237.768","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1117770/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Oversimplification“, „Scapegoating“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-030","clusterId":"B","werkstueckRef":"B.24","stufe":2,"question":"Welches Merkmal des Prospekts ist das deutlichste Warnzeichen für eine unzulässige Vereinfachung?","scenario":"Ein Prospekt erklärt: „Fast alle Krankheiten haben eine Wurzel: Schlacken im Darm. Unsere Detox-Kur beseitigt sie.“","options":["Das Wort „Schlacken“ ist kein medizinischer Fachbegriff, und unfachliche Wörter dieser Art deuten grundsätzlich auf Unseriosität hin.","Ein konkretes Produkt wird zum Kauf angeboten, und Gesundheitsaussagen im Zusammenhang mit einem Verkauf sind grundsätzlich verdächtig.","Sehr verschiedene Krankheiten werden auf eine einzige Wurzelursache zurückgeführt, und dafür wird eine ebenso einfache Lösung verkauft.","Es geht um „Detox“, und weil Leber und Nieren den Körper ohnehin entgiften, ist jede Entgiftungskur von vornherein unseriös."],"correctIndex":2,"explanation":"Krankheiten haben sehr verschiedene, oft mehrere zusammenwirkende Ursachen. Dass eine einzige „Wurzelursache“ fast alle erklären soll, ist ein typischer monokausaler Fehlschluss. Verdächtig wird es zusätzlich, wenn die Lösung genauso einfach ist wie die Ursache und genau das Produkt ist, das der Prospekt verkauft. Die Reduktion eines vielfältigen Problems auf ein einfaches Ziel ist ein Muster, das man bei komplexen Themen immer prüfen sollte. Dass ein Produkt verkauft wird oder ungewohnte Wörter vorkommen, ist dagegen nicht das Muster des Denkfehlers, um den es hier geht.","coreRule":"⚡ Eine Ursache und eine Lösung, beide ganz einfach: bei komplexen Problemen ein Warnsignal.","beleg":"Werkstück B.24 (Anwendung: Pseudomedizin; Red Flags)","status":"entwurf","kurz":"Wenn „fast alle Krankheiten“ eine einzige Wurzel haben sollen und die Lösung ebenso einfach ist, wird ein vielfältiges Problem auf eine Ursache verkürzt. Krankheiten haben verschiedene, oft mehrere zusammenwirkende Ursachen, und das verkaufte Produkt passt verdächtig genau.","prueffrage":"Welche Aussage des Prospekts müsste am stärksten belegt sein, damit die Kur hält, was sie verspricht?","rueckmeldung":[{"option":0,"text":"Unfachliche Wörter wie „Schlacken“ wirken unseriös, und ein Fachbegriff ist „Schlacken“ tatsächlich nicht. Auch Seriöses kann aber in Laiensprache stehen; das Warnzeichen liegt im Bau der Aussage, nicht in der Wortwahl."},{"option":1,"text":"Ein Verkaufsinteresse ist ein guter Anlass, genauer hinzuschauen. „Grundsätzlich verdächtig“ geht aber zu weit: Auch seriöse Produkte haben Preise und Gesundheitsversprechen. Entscheidend ist, ob die Aussage selbst trägt."},{"option":3,"text":"Leber und Nieren übernehmen tatsächlich die Entgiftung, und manche Kur verspricht mehr, als sie hält. „Jede“ geht aber zu weit; das Warnzeichen liegt in der einen Ursache für fast alle Krankheiten und der ebenso einfachen Lösung."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Oversimplification“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"NCCIH (National Center for Complementary and Integrative Health): Detoxes and Cleanses: What You Need To Know","oeffentlich":true,"url":"https://www.nccih.nih.gov/health/detoxes-and-cleanses-what-you-need-to-know","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-b2-031","clusterId":"B","werkstueckRef":"B.24","stufe":3,"question":"Nach einem Schiffsunglück zeigt eine Untersuchung mehrere zusammenwirkende Ursachen: einen starken Sturm, einen unentdeckten Haarriss im Rumpf, eine Fehlentscheidung des Kapitäns unter Druck, eine unzureichend geschulte Crew und veraltete Rettungsboote. Ein Reeder kündigt an, nur den Kapitän zu entlassen, und erklärt: „Damit ist das Problem gelöst.“ Warum ist dieser Schluss riskant?","options":["Weil die übrigen Ursachen bestehen bleiben und auch das nächste Schiff gefährden.","Weil Stürme grundsätzlich nicht beherrschbar sind und jedes Schiff deshalb untergehen kann.","Weil ein Kapitän in keinem Fall für ein Schiffsunglück mitverantwortlich sein kann.","Weil eine Entlassung nur eine symbolische Handlung ist und nie Einfluss auf die Sicherheit hat."],"correctIndex":0,"explanation":"Der Reeder greift aus mehreren zusammenwirkenden Ursachen eine einzige heraus und behandelt sie als die Lösung. Wer nur dieses einfache Ziel bekämpft, lässt die übrigen Ursachen unangetastet: den Haarriss im Rumpf, die schlecht geschulte Crew, die veralteten Rettungsboote. Das nächste Schiff trägt dann dieselben Risiken. Bei einfachen, technischen Problemen wie einem Wackelkontakt ist die Suche nach der einen Ursache dagegen oft richtig; bei komplexen Systemen mit vielen zusammenwirkenden Faktoren führt sie in die Irre. Eine gute Prüffrage lautet: Welche fünf weiteren, vielleicht weniger offensichtlichen Faktoren könnten ebenfalls zu diesem Ergebnis beigetragen haben?","coreRule":"⚡ Wer nur den Sündenbock behandelt, lässt die Ursachen des Problems unangetastet.","beleg":"Werkstück B.24 (Das Geheimnis des Schiffsunglücks; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Die Entlassung beseitigt nur eine von mehreren zusammenwirkenden Ursachen. Haarriss, Crew und Rettungsboote bleiben, und das nächste Schiff trägt dieselben Risiken. Der naheliegende Fehler ist, die Beseitigung einer einzigen Ursache schon für die ganze Lösung zu halten.","prueffrage":"Welche Faktoren, die nichts mit dem Kapitän zu tun haben, tauchen im Untersuchungsbericht noch auf?","rueckmeldung":[{"option":1,"text":"Einen Sturm kann niemand verhindern, deshalb wirkt er wie das eigentliche Problem. Ob ein Schiff ihn übersteht, hängt aber auch von Rumpf, Crew und Ausrüstung ab, und genau diese Faktoren lässt der Reeder unangetastet."},{"option":2,"text":"Wer den Reeder kritisiert, schiebt die Schuld leicht ganz von der Person weg. Laut Untersuchung war die Fehlentscheidung des Kapitäns aber eine der Ursachen. Das Problem ist, dass sie als einzige behandelt wird, nicht dass sie überhaupt genannt wird."},{"option":3,"text":"Dass eine Entlassung allein nicht genügt, ist richtig. Daraus folgt aber nicht, dass sie nie etwas bewirkt: Eine einzelne Maßnahme kann sinnvoll sein, solange sie nicht als die ganze Lösung gilt. Hier fehlen die Maßnahmen gegen die übrigen Ursachen."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Reason, J. (2000): Human error: models and management. BMJ 320(7237), 768–770","oeffentlich":true,"doi":"10.1136/bmj.320.7237.768","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1117770/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Oversimplification“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-032","clusterId":"B","werkstueckRef":"B.24","stufe":4,"question":"Welche Prüfung wendest du auf diese Slogans an?","scenario":"Im Wahlkampf heißt es: „Warum geht es uns schlecht? Wegen der Milliardäre!“ Das gegnerische Lager antwortet mit ebenso einfachen Parolen über eine andere Gruppe.","options":["Beide Parolen machen einen klar benennbaren Schuldigen für ein vielschichtiges Problem verantwortlich; prüfe zuerst, ob du der politischen Seite traust, die sie ruft, und urteile danach.","Beide Parolen führen ein vielschichtiges Problem auf eine einzige einfache Ursache zurück und kommen bei vielen an; prüfe vor allem, wie beliebt sie sind, denn Beliebtheit zeigt ihre Richtigkeit.","Beide Parolen führen ein vielschichtiges Problem auf eine einzige Gruppe zurück; lehne darum jede Ursachenerklärung ab und verzichte ganz auf eine Analyse der Gründe.","Beide Parolen verkürzen ein vielschichtiges Problem auf eine leicht benennbare Gruppe; frag nach weiteren, weniger offensichtlichen Faktoren, die ebenfalls dazu beigetragen haben könnten."],"correctIndex":3,"explanation":"Beide Slogans haben denselben Fehler: Ein vielschichtiges Problem wie wirtschaftliche Not hat selten eine einzige Ursache, sondern entsteht aus dem Zusammenspiel vieler Faktoren. Eine Parole, die eine einzige Gruppe als Schuldige benennt, ist eingängig und emotional befriedigend, aber gerade deshalb verdächtig. Die richtige Prüfung fragt unabhängig von der politischen Richtung, welche weiteren, weniger offensichtlichen Faktoren mitgewirkt haben könnten. Ob du der Seite traust, ist dafür kein Maßstab, denn eine Erklärung wird nicht dadurch richtig, dass sie von „den Richtigen“ kommt. Auch Beliebtheit beweist nichts: Einfache Schuldzuweisungen kommen oft gerade deshalb gut an, weil sie einfach sind. Und jede Erklärung mit einer Gruppe pauschal abzulehnen, ersetzt die Prüfung durch ein Reflexurteil: Manchmal tragen einzelne Akteure tatsächlich zu einem Problem bei, nur eben nie allein.","coreRule":"⚡ Eine Erklärung wird nicht dadurch besser, dass sie einen klaren Schuldigen anbietet.","beleg":"Werkstück B.24 (Anwendung: In der Politik; Anti-Denkmuster: Aktivierungs-Frage), keine Fußnoten","status":"entwurf","kurz":"Wirtschaftliche Not hat selten nur eine Ursache. Statt einer Parole zu folgen, weil sie eingängig ist oder von der eigenen Seite kommt, lohnt die Frage, welche weniger offensichtlichen Faktoren ebenfalls mitgewirkt haben könnten.","prueffrage":"Was wäre in den Slogans eigentlich zu erklären, und wie viele Ursachen kommen darin vor?","rueckmeldung":[{"option":0,"text":"Das Vertrauen in eine Seite wirkt wie eine Abkürzung, wenn man Parolen schnell einordnen will. Ob eine Erklärung stimmt, hängt aber nicht davon ab, wer sie ausruft, und deshalb muss die Prüfung unabhängig von der politischen Richtung erfolgen."},{"option":1,"text":"Einfache Schuldzuweisungen kommen oft gut an, gerade weil sie einfach sind. Daraus folgt aber nicht, dass sie stimmen: Beliebtheit sagt etwas über die Wirkung einer Parole, nichts über ihre Richtigkeit."},{"option":2,"text":"Die pauschale Ablehnung wirkt gründlich, ersetzt die Prüfung aber durch ein Reflexurteil. Einzelne Akteure können durchaus zu einem Problem beitragen, nur eben nicht allein, und genau das lässt sich nur durch den Blick auf weitere Faktoren klären."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Oversimplification“, „Scapegoating“, „Bandwagon“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-033","clusterId":"B","werkstueckRef":"B.25","stufe":1,"question":"Welche Frage hilft dir am besten zu erkennen, ob du deine Denkwerkzeuge gerade als Späher oder als Soldat einsetzt?","options":["Welche Denkfehler hat mein Gegenüber bisher gemacht, und wie kann ich sie am wirkungsvollsten aufzeigen?","Welche Argumente habe ich bisher vorgebracht, die mein Gegenüber noch nicht entkräften konnte?","Welche Beobachtung würde mich dazu bringen, meine eigene Einschätzung zu ändern, und habe ich danach gesucht?","Wie bleibe ich in der Diskussion ruhig und sachlich, damit mein Gegenüber meine Fachkenntnis respektiert?"],"correctIndex":2,"explanation":"Dieselben Werkzeuge (Recherche, Logik, Befragung) können der Wahrheitssuche dienen oder dem Gewinnen um jeden Preis. Zwei Anwälte mit identischem Handwerk zeigen das: Anwalt A sammelt auch die Fakten, die seinem Mandanten schaden, baut den stärksten Fall der Gegenseite, um Schwachstellen zu finden, und ist bereit, seine Strategie bei widersprüchlichen Beweisen anzupassen. Anwalt B sucht nur Munition für seine vorgefasste Schlussfolgerung. Wer prüft, welche Beobachtung ihn umstimmen würde und ob er danach gesucht hat, testet genau diese Offenheit für Gegenbeweise; das ist die Haltung des Spähers. Die Frage nach dem wirkungsvollen Aufzeigen fremder Denkfehler und die nach den noch unwiderlegten eigenen Argumenten zielen dagegen auf das Gewinnen, also auf die Haltung des Soldaten. Die Frage nach Ruhe und Respekt für deine Fachkenntnis betrifft Wirkung und Status, nicht die Suche nach der Wahrheit. Dass du Denkfehler kennst, macht dich noch nicht zum Wahrheitssucher. Entscheidend ist, wofür du die Werkzeuge einsetzt und ob du sie auch auf dich selbst anwendest.","coreRule":"⚡ Werkzeuge des Denkens sind neutral: Entscheidend ist, ob du sie auch gegen deine eigene Position richtest.","beleg":"Werkstück B.25 (Eingangsszene; Kernidee); Fn. gl-b-galef (Galef, TEDxPSU 2016; The Scout Mindset 2021)","status":"entwurf","scenario":"Du hast dich intensiv mit logischen Fehlschlüssen beschäftigt. In einer Diskussion über ein Gesundheitsthema fällt dir auf, dass du vor allem darauf achtest, wo dein Gegenüber einen Denkfehler macht. Dein Ziel ist es, die Diskussion zu gewinnen.","kurz":"Wer fragt, welche Beobachtung ihn umstimmen würde, und danach sucht, wendet die Werkzeuge auch auf sich selbst an und sucht Wahrheit. Wer nur eigene Treffer zählt oder fremde Fehler sammelt, nutzt dieselben Werkzeuge als Munition.","prueffrage":"Worauf achtest du in dieser Diskussion bisher vor allem, und was soll am Ende dabei herauskommen?","rueckmeldung":[{"option":0,"text":"Fremde Denkfehler zu erkennen, ist ein nützliches Handwerk. Die Frage nach dem wirkungsvollsten Aufzeigen richtet es aber auf das Gewinnen aus und lässt offen, ob du es auch auf deine eigenen Schlüsse anwendest."},{"option":1,"text":"Das Zählen unwiderlegter Argumente misst, wie gut du dich behauptest, nicht, wie nah du der Wahrheit bist. Dass dein Gegenüber etwas nicht entkräften konnte, macht es noch nicht richtig, und nach den Schwächen deiner Sicht fragt das gar nicht."},{"option":3,"text":"Ruhe und Sachlichkeit tun jeder Diskussion gut. Gefragt ist hier aber nur nach dem Eindruck, den du machst, und der sagt nichts darüber, ob du nach Wahrheit suchst oder nur gewinnen willst; beides geht auch gelassen."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Galef, J. (2016): Why you think you're right -- even if you're wrong. TEDxPSU, Februar 2016 (TED-Seite mit Transkript)","oeffentlich":true,"url":"https://www.ted.com/talks/julia_galef_why_you_think_you_re_right_even_if_you_re_wrong/transcript","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Galef, J. (2021): The Scout Mindset. New York: Portfolio","oeffentlich":false}],"thema":"Psychologie"},{"id":"qx-b2-034","clusterId":"B","werkstueckRef":"B.25","stufe":2,"question":"Welche Haltung zeigt sich in dieser Selbstbeobachtung, und was folgt daraus?","scenario":"Du merkst: In Online-Debatten freust du dich vor allem, wenn du den Gegner „besiegt“ hast. Dein Wissen über Denkfehler nutzt du vor allem, um andere zu katalogisieren und abzuwerten. Deine wichtigen Meinungen hast du trotz ständigen Debattierens lange nicht mehr geändert.","options":["Du verteidigst eine feste Position: Das Wissen dient dem Gewinnen und dem Status, und die Gefahr, selbstgerecht zu werden, ist bereits nahe.","Du kartierst die Wirklichkeit sorgfältig: Dass du deine Meinung lange nicht geändert hast, zeigt, dass deine Sicht offenbar stimmt.","Du suchst nach der Wahrheit: Indem du die Fehler anderer sammelst, bleibst du in deinem eigenen Urteil beweglich.","Du schützt dich zu Recht vor Desinformation: Das Abwerten anderer ist eine gesunde Strategie, um klar zu denken."],"correctIndex":0,"explanation":"Wer sich über das Besiegen anderer freut, sein Wissen über Denkfehler vor allem zum Abwerten nutzt und trotz ständiger Debatten nie umdenkt, setzt Werkzeuge des kritischen Denkens als Waffen ein, nicht als Instrumente der Selbstkorrektur. Dass man trotz ständigen Debattierens lange keine wichtige Meinung aufgrund neuer Beweise geändert hat, ist ein Warnzeichen für die Soldaten-Mentalität. Eine lange unveränderte Meinung ist also kein Beleg dafür, dass die eigene Sicht stimmt. Kippt die Liebe zum Recht-Haben über die Liebe zur Wahrheit, wird aus dem Skeptiker ein Dogmatiker mit schärferem Schwert.","coreRule":"⚡ Frag dich bei jedem Denkwerkzeug: Setze ich es ein, um die Wahrheit zu finden, oder um recht zu behalten?","quote":"Benutze ich dieses Werkzeug wie ein Späher oder wie ein Soldat?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.25 (Red Flags; Kipppunkt; Anti-Denkmuster)","status":"entwurf","kurz":"Wer sich über Siege freut, Denkfehler vor allem bei anderen sucht und sich selbst nie korrigiert, nutzt Wissen als Waffe statt als Werkzeug. Dass die eigene Meinung lange gleich blieb, beweist nicht, dass sie stimmt.","prueffrage":"Wie oft hat eine deiner vielen Debatten in letzter Zeit eine deiner wichtigen Meinungen tatsächlich verändert?","rueckmeldung":[{"option":1,"text":"Eine Sicht kann stimmen, ohne dass man sie je ändern musste. Dass sie sich trotz ständigen Debattierens lange nicht verschoben hat, ist aber kein Beleg dafür, sondern passt eher zu einem Verteidigen als zu einem sorgfältigen Prüfen."},{"option":2,"text":"Das Ideal der Wahrheitssuche ist richtig. Fehler anderer zu sammeln zeigt aber nur auf andere und hält das eigene Urteil nicht beweglich; Beweglichkeit zeigt sich darin, dass man tatsächlich umdenkt, und genau das fehlt hier seit Langem."},{"option":3,"text":"Sich vor Desinformation zu schützen ist ein legitimes Ziel. Hier geht es aber um Freude am Besiegen und um Abwerten, und das dient dem Status, nicht dem klaren Denken, das beim Prüfen der eigenen Urteile beginnt."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Galef, J. (2016): Why you think you're right -- even if you're wrong. TEDxPSU, Februar 2016 (TED-Seite mit Transkript)","oeffentlich":true,"url":"https://www.ted.com/talks/julia_galef_why_you_think_you_re_right_even_if_you_re_wrong/transcript","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Galef, J. (2021): The Scout Mindset. New York: Portfolio","oeffentlich":false}],"thema":"Netz und Medien"},{"id":"qx-b2-035","clusterId":"B","werkstueckRef":"B.25","stufe":4,"question":"Wie gehst du mit diesem Gesprächspartner am besten um?","scenario":"In einem Forum fordert jemand eine „offene Debatte“ zu einer Behauptung, die längst nach allen Regeln der Wissenschaft widerlegt wurde. Er lügt dabei systematisch, stellt deine Argumente verzerrt als Strohmänner dar und besteht darauf, du müsstest als Skeptiker offen bleiben.","options":["Du führst die Debatte so lange weiter, bis er seinen Irrtum öffentlich einräumt und dir in der Sache recht gibt.","Du prüfst die Behauptung immer wieder neu und offen, weil Skepsis verlangt, jede Idee ständig zu hinterfragen.","Du stellst fest, dass er sich nicht an die Bedingungen einer ehrlichen Auseinandersetzung hält, und steigst aus der Debatte aus.","Du bietest einen Mittelweg an, bei dem beide Seiten gleich viel nachgeben und sich in der Mitte treffen."],"correctIndex":2,"explanation":"Offenheit heißt, Behauptungen anhand von Belegen zu prüfen, nicht, jede Idee gleich zu behandeln. Eine Behauptung, die längst nach allen Regeln der Wissenschaft widerlegt wurde, verdient keine erneute offene Prüfung: Eine erneute „offene“ Debatte darüber verschwendet Zeit und ist eine Form der falschen Ausgewogenheit. Wer zudem systematisch lügt und Strohmänner baut, will nicht herausfinden, was stimmt, sondern gewinnen. Hier ist die „offene“ Fortführung der Debatte keine Tugend, sondern Selbstschädigung; darum greift die Ausstiegs-Strategie. Auch ein Mittelweg löst das Problem nicht, denn dein Gegenüber sucht gar nicht die Wahrheit. Der Ausstieg ist daher kein Akt der Engstirnigkeit, sondern eine begründete Entscheidung, die deine Energie schützt.","coreRule":"⚡ Offenheit heißt, Behauptungen ernsthaft zu prüfen, nicht, jedem Debattenpartner unbegrenzt Zeit und Aufmerksamkeit zu schenken.","beleg":"Werkstück B.25 (Die Grenzen der Offenheit; Anti-Denkmuster)","status":"entwurf","kurz":"Eine längst widerlegte Behauptung verdient keine erneute „offene“ Prüfung, und wer systematisch lügt und Strohmänner baut, will gewinnen statt klären. Offenheit heißt nicht, um jeden Preis weiterzudiskutieren; der Ausstieg ist begründet.","prueffrage":"Was ist über die Behauptung selbst längst geklärt, und was hat er bisher mit deinen Argumenten gemacht?","rueckmeldung":[{"option":0,"text":"Hartnäckigkeit klingt nach Standhaftigkeit. Wer aber systematisch lügt und Strohmänner baut, will nicht herausfinden, was stimmt, und wird kaum einlenken. Du würdest nur Zeit und Kraft in eine Debatte stecken, die nicht auf Klärung zielt."},{"option":1,"text":"Skepsis heißt, Behauptungen anhand von Belegen zu prüfen, nicht, jede Idee gleich zu behandeln. Eine längst widerlegte Behauptung immer wieder neu zu öffnen, wäre falsche Ausgewogenheit und keine Offenheit."},{"option":3,"text":"Ein Mittelweg ist oft ein guter Ausgleich, wenn Interessen gegeneinanderstehen. Bei einer Tatsachenfrage gibt es aber keine Mitte zwischen widerlegt und nicht widerlegt. Außerdem sucht dein Gegenüber gar keine Lösung, sondern will gewinnen."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3","quellen":[{"typ":"doi","kurz":"Grimes, D. R. (2019): A dangerous balancing act. EMBO Reports 20(8), e48706","oeffentlich":true,"doi":"10.15252/embr.201948706","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6680130/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Schmid, P.; Schwarzer, M.; Betsch, C. (2020): Weight-of-Evidence Strategies to Mitigate the Influence of Messages of Science Denialism in Public Discussions. Journal of Cognition 3(1), 36","oeffentlich":true,"doi":"10.5334/joc.125","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7528676/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-b2-036","clusterId":"B","werkstueckRef":"B.25","stufe":3,"question":"Was erklärt dieses Verhalten am besten?","scenario":"Jemand wirft in Online-Diskussionen ständig anderen „Strohmann“ und „Zirkelschluss“ vor und kennt viele Fachbegriffe für Denkfehler. Wird aber seine eigene Lieblingsthese kritisiert, tauchen dieselben Fehler in seinen Antworten auf. Er hat seine Ansicht seit Jahren nicht korrigiert, obwohl er täglich debattiert.","options":["Er setzt sein Wissen über Denkfehler als Waffe gegen andere ein, um seine vorgefasste Meinung zu verteidigen, statt es zur Selbstkorrektur zu nutzen.","Er kennt die Denkfehler nicht gut genug, denn wer sie wirklich beherrscht, bemerkt sie bei sich selbst verlässlich und vermeidet sie von allein.","Er handelt folgerichtig, denn Kritik an der Gegenseite ist der eigentliche Zweck dieser Denkwerkzeuge, und Selbstkritik gehört nicht dazu.","Er wendet die Begriffe falsch an, denn Denkfehler kommen nur in wissenschaftlichen Fachdebatten vor und nicht in Alltagsgesprächen."],"correctIndex":0,"explanation":"Der bloße Besitz von Denkwerkzeugen macht niemanden zum wahrheitssuchenden Denker. Die Julia Galef zugeschriebene Unterscheidung beschreibt es so: Wer in der Soldaten-Mentalität denkt, will eine Position verteidigen und nutzt sein Wissen als Waffe. Wer in der Späher-Mentalität denkt, will herausfinden, was tatsächlich stimmt, und prüft zuerst sich selbst. Hier zeigen drei Signale die Soldaten-Haltung: Die Fehlerjagd richtet sich nur nach außen, die eigene These bleibt unangetastet, und trotz täglicher Debatten hat sich über Jahre nichts geändert. Auch kluge Verschwörungsgläubige sind ein typisches Beispiel: Sie werfen anderen Fehlschlüsse vor und begehen dieselben selbst. Das Ziel entscheidet, ob die Werkzeuge der Wahrheit oder der Verteidigung dienen. Die Werkzeuge kippen damit von Instrumenten der Selbstkorrektur zu Instrumenten der Selbstgerechtigkeit.","coreRule":"⚡ Wissen über Denkfehler schützt nicht vor ihnen; es verpflichtet zur Selbstprüfung.","beleg":"Werkstück B.25 (Anwendung: Verschwörungs-„Forscher“; Kipppunkt)","status":"entwurf","kurz":"Wissen über Denkfehler macht noch niemanden zum Wahrheitssucher. Entscheidend ist das Ziel: Wer seine Position verteidigen will, richtet die Werkzeuge nur nach außen und lässt die eigene These unangetastet, statt sich damit selbst zu korrigieren.","prueffrage":"Gegen wen richtet er seine Fehlervorwürfe, und was hat sich nach Jahren täglicher Debatten an seiner eigenen Ansicht verändert?","rueckmeldung":[{"option":1,"text":"Wissen und Anwendung scheinen eng zusammenzuhängen. Doch auch wer Denkfehler gut beherrscht, bemerkt sie bei sich nicht verlässlich: Gerade bei der eigenen Lieblingsthese begehen auch kluge Menschen die Fehlschlüsse, die sie anderen vorwerfen."},{"option":2,"text":"Dass seine Kritik nur nach außen zielt, beschreibt das Verhalten richtig. Die Werkzeuge sind aber nicht auf Fremdkritik beschränkt, sie sollen auch die eigene Ansicht prüfen; wer sie nur gegen andere richtet, verfehlt ihren Zweck."},{"option":3,"text":"Denkfehler stecken auch in Alltagsgesprächen und Online-Debatten; in seinen eigenen Antworten tauchen sie ja dort auf. Ob er die Begriffe treffend anwendet, ist nicht der Punkt: Auffällig ist, dass er sie nur auf andere anwendet und nie auf sich."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Galef, J. (2016): Why you think you're right -- even if you're wrong. TEDxPSU, Februar 2016 (TED-Seite mit Transkript)","oeffentlich":true,"url":"https://www.ted.com/talks/julia_galef_why_you_think_you_re_right_even_if_you_re_wrong/transcript","abruf":"2026-10-12"},{"typ":"doi","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3), 506–519","oeffentlich":false,"doi":"10.1037/a0028857"}],"thema":"Netz und Medien"},{"id":"qx-b2-037","clusterId":"B","werkstueckRef":"B.26","stufe":1,"question":"Was ist die sinnvollste Reaktion auf diesen Impuls?","scenario":"Beim Kauf von Konzerttickets blinkt ein roter Balken: „Nur noch 17 Tickets verfügbar! 250 Leute sehen sich dieses Angebot gerade an!“ Du wolltest eigentlich noch ein paar Tage überlegen, ob du hingehst. Jetzt schlägt dein Herz schneller, und du spürst den Impuls, sofort zu bestellen.","options":["Sofort kaufen, denn dass so viele Leute zuschauen, zeigt, dass das Angebot sein Geld wert ist.","Innehalten und prüfen, ob dich der Balken oder der Wert des Konzerts antreibt, bevor du kaufst.","Sofort kaufen, denn wenn nur noch 17 Tickets übrig sind, ist der Preis bestimmt fair.","Den Balken ignorieren und ohne weitere Überlegung auf keinen Fall kaufen, damit du dich nicht beeinflussen lässt."],"correctIndex":1,"explanation":"„Nur noch 17“ (Knappheit) und „250 Leute sehen sich das gerade an“ (sozialer Beweis) sagen nichts darüber, ob das Konzert dir das Geld wert ist. Sie erzeugen Zeitdruck und sollen die ruhige Abwägung umgehen. Seltenes wirkt automatisch wertvoller, und was viele wollen, wirkt automatisch richtig, auch wenn beides über den eigentlichen Wert nichts verrät. Der Impuls ist ein Warnsignal, kein Argument. Sinnvoll ist, ihn zu bemerken und gezielt zu fragen: Will ich das, weil ich den Wert verstanden habe, oder nur, weil ich Angst habe, es zu verpassen? Pauschal nicht zu kaufen wäre ebenso wenig durchdacht wie blindes Kaufen: Auch dann bestimmt der Balken deine Entscheidung, nur in die Gegenrichtung.","coreRule":"⚡ „Nur noch wenige“ und „viele schauen gerade“ sind Druckmittel, keine Informationen über den Wert. Prüfe, was dich antreibt, bevor du entscheidest.","beleg":"Werkstück B.26 (Eingangsszene Situation B; Analyse: drei Heuristiken; Anwendung: Alltag & Konsum)","status":"entwurf","kurz":"Der Balken erzeugt Druck, sagt aber nichts darüber, ob das Konzert dir sein Geld wert ist. Der Impuls ist ein Warnsignal, kein Argument: Erst fragen, ob du den Wert siehst oder nur Angst hast, etwas zu verpassen.","prueffrage":"Was verraten dir die beiden Zahlen im roten Balken über das Konzert selbst?","rueckmeldung":[{"option":0,"text":"Was viele ansehen, wirkt schnell richtig. Aber wie viele zuschauen, verrät nichts darüber, ob das Konzert dir den Preis wert ist, und ob diese 250 überhaupt kaufen wollen, steht nirgends."},{"option":2,"text":"Knappe Ware wirkt automatisch wertvoller. Ob ein Preis fair ist, verrät die Restmenge aber nicht: Auch ein überteuertes Ticket kann knapp sein, und die Knappheit kann sogar nur inszeniert sein."},{"option":3,"text":"Sich nicht lenken lassen zu wollen, ist berechtigt. Ein pauschales „Nein“ ohne Abwägung wird aber ebenfalls vom Balken bestimmt, nur in die Gegenrichtung, und ob das Konzert dir den Preis wert ist, bleibt ungeprüft."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Federal Trade Commission (2022): Bringing Dark Patterns to Light. Staff Report, September 2022","oeffentlich":true,"url":"https://www.ftc.gov/system/files/ftc_gov/pdf/P214800%20Dark%20Patterns%20Report%209.14.2022%20-%20FINAL.pdf","seite":"21–22, 37","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-b2-038","clusterId":"B","werkstueckRef":"B.26","stufe":3,"question":"Ein Kollege schwärmt von einem Vermögenswert, dessen Preis sich in sechs Monaten vervielfacht hat. Du fragst ihn, warum er gerade jetzt kauft. Welche Antwort deutet am stärksten darauf hin, dass er sich in einer Spekulationsblase bewegt?","options":["„Die Preise sind höher als vor einem Jahr, und auch große Anleger kaufen deutlich mehr dazu als früher.“","„Ich habe mir Gewinne, Umsätze und Kennzahlen angesehen, und sie tragen den Anstieg aus meiner Sicht weiterhin.“","„Seit sich die ersten Kritiker gemeldet haben, hat sich der Anstieg verlangsamt, ich warte, ob er wieder anzieht.“","„Ob er etwas wert ist, weiß ich nicht genau, aber morgen ist er teurer, und ich will nicht als Einziger draußen bleiben.“"],"correctIndex":3,"explanation":"Typisch für eine Blase ist, dass sich die Begründung vom Wert auf die Erwartung weiterer Preissteigerungen verlagert und die Angst, nicht dabei zu sein, den Kauf antreibt. Dann kauft man, weil der Preis steigt, nicht weil man verstanden hat, was der Vermögenswert wert ist. Ein höherer Preis oder zusätzliche Käufe allein sind noch kein Beleg, auch ein kräftiger Anstieg kann durch Gewinne und Umsätze gedeckt sein. Entscheidend ist, woher die Rechtfertigung stammt: aus dem Wert der Sache oder aus der Hoffnung auf den nächsten Käufer.","coreRule":"⚡ Prüfe die Begründung: Kaufst du wegen des Wertes oder weil der Preis gestern gestiegen ist?","quote":"","quoteLabel":"","beleg":"Werkstück B.26 (Red Flags: eine Spekulationsblase; Anti-Denkmuster)","status":"entwurf","scenario":"","kurz":"Wer kauft, weil der Preis morgen höher sein wird, und aus Angst, draußen zu bleiben, stützt sich nicht mehr auf den Wert der Sache. Der naheliegende Fehler ist, schon den Preisanstieg selbst als Zeichen einer Blase zu lesen.","prueffrage":"Was müsste dein Kollege über den Vermögenswert selbst wissen, um beurteilen zu können, ob der heutige Preis angemessen ist?","rueckmeldung":[{"option":0,"text":"Gestiegene Preise und mehr Käufe großer Anleger wirken wie ein Warnsignal. Beides gibt es aber auch bei einem Anstieg, den Gewinne und Umsätze decken, und dass er den Wert nicht kennt oder nur aus Angst kauft, draußen zu bleiben, sagt er nicht."},{"option":1,"text":"Wer Gewinne, Umsätze und Kennzahlen prüft, begründet seinen Kauf mit dem Wert der Sache. Das ist das Gegenteil einer Blasenlogik, auch wenn sich im Einzelfall streiten lässt, ob die Zahlen den Anstieg wirklich tragen."},{"option":2,"text":"Das Abwarten nach der Kritik zeigt, dass er auf den Kursverlauf schaut. Er kauft aber gerade nicht überstürzt, und weder Unwissen über den Wert noch die Angst, draußen zu bleiben, ist darin zu erkennen."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Shiller, R. J. (2014): Speculative Asset Prices (Nobel Prize Lecture). Cowles Foundation Discussion Paper 1936","oeffentlich":true,"url":"https://cowles.yale.edu/sites/default/files/2022-08/d1936.pdf","seite":"2","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kindleberger, C. P.; Aliber, R. Z. (2005): Manias, Panics, and Crashes. 5. Aufl., Hoboken: Wiley","oeffentlich":false}],"thema":"Geld und Zahlen"},{"id":"qx-b2-039","clusterId":"B","werkstueckRef":"B.26","stufe":4,"question":"Welche Frage stellst du dir, bevor du auf das Angebot eingehst?","scenario":"Eine Freundin drängt: „Es gibt nur 20 Plätze beim Wochenend-Workshop mit dem berühmten Guru. Danach nimmt er drei Jahre lang keine neuen Schüler. Alle sagen, es hat ihr Leben verändert.“","options":["Gehört die Freundin zu meinem engeren Kreis, sodass ihre Aussage als Vertraute eine eigene Prüfung des Angebots überflüssig macht?","Würde ich den Workshop auch buchen, wenn es keine Platzbegrenzung und keine Frist gäbe, oder treibt mich vor allem die Angst, die Gelegenheit zu verpassen?","Wie viele Menschen berichten Positives, sodass eine große Zahl zufriedener Teilnehmer als bester Gütenachweis für den Workshop gelten kann?","Habe ich genug Geld und Zeit, sodass ich bei einer so knappen Gelegenheit auf weitere Prüfung verzichten sollte, um den Platz nicht zu verlieren?"],"correctIndex":1,"explanation":"Platzbegrenzung („nur 20 Plätze“), Frist („drei Jahre keine neuen Schüler“) und Erfolgsberichte („alle sagen, es hat ihr Leben verändert“) sagen nichts darüber, ob der Workshop hält, was er verspricht. Knappheit und Exklusivität lassen Dinge automatisch wertvoller erscheinen, und eine große Zahl von Begeisterten wirkt als sozialer Beweis: Popularität wird mit Wert verwechselt. Beides erzeugt Zeitdruck und den Wunsch, zu einer auserwählten Gruppe zu gehören. Die beste Prüffrage trennt deshalb den Wert der Sache von dem Druck, der um sie herum aufgebaut wird: Würde das Angebot auch ohne Verknappung überzeugen? Wenn nicht, bezahlst du für die Angst vor dem Verpassen und nicht für den Inhalt. Die Vertrautheit der Freundin ersetzt die eigene Prüfung ebenso wenig wie die Zahl der Zufriedenen: Auch sie kann dem Druck erlegen sein. Und der Zeitdruck ist gerade das Werkzeug, das die Prüfung verhindern soll, sie zu überspringen löst das Problem also nicht.","coreRule":"⚡ Wer wegen der Angst vor dem Verpassen kauft, bezahlt für das Gefühl, nicht für die Sache.","beleg":"Werkstück B.26 (Eingangsszene Situation C; Anwendung: Esoterik; Anti-Denkmuster)","status":"entwurf","kurz":"Entscheidend ist, ob der Workshop auch ohne Platzbegrenzung und Frist überzeugen würde. Der naheliegende Fehler ist, Knappheit und die Begeisterung anderer für einen Qualitätsbeleg zu halten, obwohl sie vor allem Druck erzeugen.","prueffrage":"Welche der drei Aussagen deiner Freundin sagt etwas darüber, was im Workshop tatsächlich geschieht?","rueckmeldung":[{"option":0,"text":"Einer Vertrauten zu glauben, ist nicht unvernünftig. Ob der Workshop hält, was er verspricht, zeigt ihre Empfehlung aber nicht: Auch sie kann dem Druck von Knappheit und Gruppe erlegen sein, und deine eigene Prüfung ersetzt sie nicht."},{"option":2,"text":"Viele zufriedene Stimmen lassen ein Angebot überzeugend wirken, und ein Hinweis können sie sein. Als bester Gütenachweis taugen sie nicht: Beliebtheit ist nicht Wert, und „alle sagen“ verrät nicht, wer spricht und was sich verändert hat."},{"option":3,"text":"Ob Geld und Zeit reichen, ist eine berechtigte praktische Frage, aber sie sagt nichts über die Qualität des Angebots. Wegen der knappen Gelegenheit auf Prüfung zu verzichten, gibt dem Zeitdruck nach, der genau dafür aufgebaut wurde."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Federal Trade Commission (2022): Bringing Dark Patterns to Light. Staff Report, September 2022","oeffentlich":true,"url":"https://www.ftc.gov/system/files/ftc_gov/pdf/P214800%20Dark%20Patterns%20Report%209.14.2022%20-%20FINAL.pdf","seite":"21–22","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-040","clusterId":"B","werkstueckRef":"B.26","stufe":2,"question":"Welche Beobachtung zeigt am deutlichsten, dass hier Angst vor dem Verpassen ausgenutzt wird, statt dass ein Angebot überzeugen soll?","scenario":"Eine Bekannte lädt dich zu einem „Business-Abend“ ein. „Wer jetzt Mitglieder anwirbt, sichert sich die beste Position und wird reich“, sagt sie. „Es gibt nur noch wenige Startplätze, und heute entscheiden sich schon die Ersten.“ Über das Produkt selbst spricht sie kaum.","options":["Der Vorteil wird über die Rekrutierung neuer Mitglieder und knappe Startplätze begründet, nicht über den Nutzen des Produkts.","Die Bekannte bietet an, dir bei einer Entscheidung drei Tage Bedenkzeit zu lassen, bevor du etwas unterschreiben musst.","Der Abend findet in angenehmer Atmosphäre statt, und die Gäste wirken freundlich und motiviert.","Das Unternehmen verkauft seine Produkte auch über das Internet, sodass man sie ohne Einladung bestellen kann."],"correctIndex":0,"explanation":"Bei Angeboten, die vor allem Reichtum durch Anwerben, Zeitdruck und Knappheit versprechen, wird nicht der Wert einer Sache verkauft, sondern die Sorge, eine einmalige Chance zu verpassen. Das Produkt tritt in den Hintergrund. Künstlich erzeugter Zeitdruck sowie Werbung mit Knappheit und Exklusivität sind typische Warnzeichen für FOMO-Manipulation. Freundliche Stimmung und zusätzliche Bestellwege sagen nichts darüber aus, ob der Vorteil tatsächlich aus dem Nutzen kommt. Entscheidend ist, woraus der versprochene Gewinn entsteht: Wird er mit dem Rekrutieren neuer Mitglieder statt mit dem Produkt begründet, ist das die FOMO-Mechanik von Multi-Level-Marketing und Schneeballsystemen.","coreRule":"⚡ Wer vor allem die Angst vor dem Verpassen verkauft, verkauft nicht den Wert der Sache.","beleg":"Werkstück B.26 (Anwendung: Multi-Level-Marketing & Schneeballsysteme; Red Flags: FOMO-Manipulation)","status":"entwurf","kurz":"Der versprochene Gewinn kommt hier aus dem Anwerben neuer Mitglieder und aus knappen Startplätzen, nicht aus dem Produkt. So wird die Sorge, etwas zu verpassen, verkauft, und der Nutzen der Sache tritt in den Hintergrund.","prueffrage":"Was müsste eine seriöse Einladung zu einem Verkaufsabend enthalten, das in ihren Worten fehlt?","rueckmeldung":[{"option":1,"text":"Drei Tage Bedenkzeit sprächen eher gegen Zeitdruck, und davon ist bei ihr keine Rede; sie drängt im Gegenteil mit knappen Startplätzen. Woraus der versprochene Gewinn entsteht, verriete eine Bedenkzeit ohnehin nicht."},{"option":2,"text":"Freundliche Gäste und gute Stimmung lassen sich schnell als Zeichen für Seriosität lesen. Über die Begründung des Gewinns sagen sie aber nichts, denn auch ein manipulativer Abend kann herzlich sein."},{"option":3,"text":"Ein zusätzlicher Bestellweg im Internet ist eine Randinformation zum Vertrieb, von der sie gar nicht spricht. Er zeigt weder, womit der Gewinn begründet wird, noch, ob Druck aufgebaut wird."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Federal Trade Commission, Consumer Advice: Multi-Level Marketing Businesses and Pyramid Schemes","oeffentlich":true,"url":"https://consumer.ftc.gov/articles/multi-level-marketing-businesses-and-pyramid-schemes","abruf":"2026-10-12"},{"typ":"url","kurz":"Federal Trade Commission (2022): Bringing Dark Patterns to Light. Staff Report, September 2022","oeffentlich":true,"url":"https://www.ftc.gov/system/files/ftc_gov/pdf/P214800%20Dark%20Patterns%20Report%209.14.2022%20-%20FINAL.pdf","seite":"21–22","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-b2-041","clusterId":"B","werkstueckRef":"B.27","stufe":1,"question":"Welche Erklärung für Lenas Meinungswechsel ist die sparsamste?","scenario":"Lena fand das Programm einer neuen Partei lange unausgegoren; im Freundeskreis hieß die Partei „Die Spinner“, die Umfragen lagen bei 3 %. Dann springt die Partei auf 15 %. In Lenas Feed erscheinen positive Artikel, und zwei Kollegen, die sie für klug hält, loben das Programm. Lena liest es noch einmal und findet es jetzt „erfrischend anders“. Nach der Wahl, bei der die Partei 25 % erreicht, sagt sie: „Ich habe mir das genau angesehen. Die haben einfach die besten Lösungen.“ Am Programm selbst wurde zwischen den Umfragen und der Wahl nichts geändert.","options":["Mit dem Umfrageplus stieg für sie die wahrgenommene Glaubwürdigkeit der Ideen; das Programm blieb gleich.","Mit dem Umfrageplus fiel ihr zum ersten Mal auf, wie gut das Programm schon immer gewesen ist.","Mit dem Umfrageplus bekam sie den entscheidenden Anstoß, die Ideen endlich vorurteilsfrei zu prüfen.","Mit dem Umfrageplus änderten sich ihre Grundwerte, sodass das Programm nun besser zu ihr passte."],"correctIndex":0,"explanation":"Verglichen werden muss, was sich zwischen den beiden Urteilen tatsächlich geändert hat. Das Programm blieb gleich; geändert haben sich nur die Umfragewerte und die Signale aus Lenas Umfeld, also positive Artikel und das Lob zweier geschätzter Kollegen. Die sparsamste Erklärung nimmt deshalb an, dass dieses gewachsene Ansehen ihr Urteil verschoben hat: Popularität dient als Ersatz für Qualität („Wenn so viele das gut finden, muss etwas dran sein“), das ist der Mitläufer-Effekt. Die anderen Erklärungen brauchen Zusatzannahmen, für die nichts spricht, etwa plötzlich gewandelte Grundwerte oder eine erst jetzt gelungene vorurteilsfreie Prüfung. Auch Lenas Satz, sie habe sich alles genau angesehen, ändert daran nichts, denn die Ideen selbst sind dieselben geblieben.","coreRule":"⚡ Ändert sich nur die Zahl der Anhänger und nicht die Idee, dann sagt der Meinungswechsel etwas über die Stimmung aus, nicht über die Idee.","beleg":"Werkstück B.27 (Eingangsszene; Kernidee)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Zwischen den beiden Urteilen hat sich nicht das Programm geändert, sondern nur sein Ansehen: Umfragewerte, Artikel im Feed, Lob geschätzter Kollegen. Sparsam ist deshalb die Annahme, dass Popularität als Ersatz für Qualität diente, der Mitläufer-Effekt.","prueffrage":"Was genau hat sich zwischen Lenas erstem und ihrem zweiten Urteil nachweislich geändert?","rueckmeldung":[{"option":1,"text":"Dass Lena das Programm jetzt gut findet, heißt nicht, dass es schon immer gut war. Zuvor hielt sie es für unausgegoren; geändert hat sich seither nur das Ansehen der Partei, und warum ihr gerade jetzt eine verborgene Qualität auffällt, bleibt offen."},{"option":2,"text":"Lenas Satz, sie habe es sich genau angesehen, wirkt wie ein Hinweis auf sorgfältige Prüfung, ist aber nur eine Selbstauskunft. Sie las das Programm erneut, nachdem die Partei populär geworden war; dass sie nun vorurteilsfrei prüfte, zeigt das nicht."},{"option":3,"text":"Ein Wertewandel würde erklären, warum ihr das Programm jetzt besser passt. Er müsste aber ausgerechnet mit dem Umfrageplus zusammenfallen, und nichts deutet auf ihn hin; die einfachere Erklärung braucht diese Zusatzannahme nicht."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Bandwagon“, „Appeal to the People“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-042","clusterId":"B","werkstueckRef":"B.27","stufe":2,"question":"Du suchst in einer fremden Stadt ein Restaurant für den Abend und siehst: Das eine Lokal ist voll, das Nachbarlokal fast leer. Bei welcher der folgenden Entscheidungen wäre der Rat „Mach, was die Mehrheit macht“ ähnlich vertretbar wie hier?","options":["Du suchst einen Film für den Abend aus und wählst den, den die meisten deiner Freunde gerade schauen, weil ein Fehlgriff dort kaum Folgen hat und sich leicht korrigieren lässt.","Du überlegst, deine Ersparnisse in einen Vermögenswert zu stecken, weil gerade viele andere damit Gewinne machen und davon erzählen.","Du entscheidest, ob ein Mittel für dein Kind geeignet ist, und orientierst dich daran, dass die meisten Eltern in deinem Umfeld es verwenden und empfehlen.","Du fragst dich, ob eine Behauptung stimmt, und hältst sie für belegt, weil sie in sozialen Netzwerken bereits millionenfach angesehen und geteilt wurde."],"correctIndex":0,"explanation":"Der Hinweis „Das volle Lokal ist wohl das bessere“ funktioniert als schnelle Faustregel, weil sich dahinter viele einzelne Erfahrungen bündeln, ein Fehlgriff wenig kostet und sich leicht korrigieren lässt. Genau diese Bedingungen (umkehrbar, geringes Risiko) treffen beim Film für den Abend zu. Bei den anderen Fällen fehlen sie: Wer Ersparnisse anlegt, weil andere gerade Gewinne machen, kauft nicht, weil der Wert unterbewertet wäre, sondern weil der Preis steigt; das treibt Blasen. Beim Mittel für das Kind steht möglicherweise die Gesundheit auf dem Spiel, und dass viele Eltern etwas verwenden, sagt wenig über Wirksamkeit und Verträglichkeit. Und dass eine Behauptung millionenfach geteilt wurde, ist keine Prüfung ihres Wahrheitsgehalts. Je höher der mögliche Schaden und je schwerer die Entscheidung zurückzunehmen ist, desto weniger darf Popularität die eigene Prüfung von Fakten, Logik und Ethik ersetzen.","coreRule":"⚡ Der Mehrheit zu folgen genügt für den Filmabend, aber nicht für Wahrheitsfragen oder riskante Entscheidungen.","beleg":"Werkstück B.27 (Adaptives Talent; Kipppunkt)","status":"entwurf","scenario":"","kurz":"Beim Restaurant bündeln sich viele Einzelerfahrungen, ein Fehlgriff kostet wenig und lässt sich korrigieren. Der Fehler wäre, das auf Fälle mit hohem Schaden zu übertragen: Je schwerer etwas rückgängig zu machen ist, desto weniger ersetzt Beliebtheit die eigene Prüfung.","prueffrage":"Welche Eigenschaften der Restaurantwahl machen es dort vertretbar, sich nach der Mehrheit zu richten?","rueckmeldung":[{"option":1,"text":"Sichtbare Gewinne anderer wirken wie ein Beweis, dass sich der Einstieg lohnt. Wer aber kauft, weil der Preis steigt, folgt der Stimmung statt dem Wert, und das treibt Blasen; bei Ersparnissen ist ein Verlust hoch und schwer rückgängig zu machen."},{"option":2,"text":"Dass viele Eltern ein Mittel verwenden, wirkt wie gesammelte Erfahrung. Es sagt aber wenig über Wirksamkeit und Verträglichkeit, und hier steht möglicherweise die Gesundheit deines Kindes auf dem Spiel; das verlangt eigene Prüfung."},{"option":3,"text":"Millionenfache Aufrufe zeigen, dass eine Behauptung Aufmerksamkeit bekommt, nicht dass sie stimmt. Ob etwas wahr ist, klärst du über Belege und Logik. Die Verbreitung ersetzt diese Prüfung nicht, auch nicht bei großer Reichweite."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Bandwagon“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Shiller, R. J. (2014): Speculative Asset Prices (Nobel Prize Lecture). Cowles Foundation Discussion Paper 1936","oeffentlich":true,"url":"https://cowles.yale.edu/sites/default/files/2022-08/d1936.pdf","seite":"2","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-b2-043","clusterId":"B","werkstueckRef":"B.27","stufe":3,"question":"Welche Rückfrage prüft diese Erklärung am besten?","options":["Woher kam das Geld, mit dem so viele Anleger kaufen konnten, und wie stark wuchs die Kreditvergabe in dieser Zeit?","Wie viele Leute haben in den sozialen Medien über die Aktie gesprochen, und wie begeistert waren sie?","Wie hoch war der Kurs genau am Tag der Verdreifachung, und wer hat an diesem Tag gekauft?","Welche bekannten Fondsmanager haben die Aktie öffentlich gelobt, und wie viele Anleger sind ihnen gefolgt?"],"correctIndex":0,"explanation":"Das Nachziehen hinter denen, die gerade Gewinne machen, ist real: Wer sieht, dass andere mit Spekulation verdienen, steigt ein. Das erklärt aber nur, warum Menschen kaufen wollen, nicht, womit sie kaufen. Bei einer einzelnen Aktie kann das Geld aus anderen Anlagen umgeschichtet werden; bei großen Manien sehen die Ökonomen Charles Kindleberger und Robert Aliber den eigentlichen Motor dagegen im Kredit, der in guten Zeiten rasch wächst, und das Mitlaufen ist bei ihnen ein Teil des Booms, nicht seine alleinige Ursache. Wer „der Herdentrieb allein“ behauptet, übersieht deshalb mindestens die Frage der Finanzierung. Die beste Rückfrage sucht diesen fehlenden Faktor; die anderen Fragen messen nur weitere Zeichen der Popularität und prüfen die Alleinursache gar nicht.","coreRule":"⚡ Der Herdentrieb heizt Blasen an, aber das Geld dafür kommt aus wachsendem Kredit: Wer eine einzige Ursache behauptet, sollte nach den fehlenden fragen.","beleg":"Werkstück B.27 (Anwendung: Finanzmärkte); Fn. gl-b-kredit (Kindleberger/Aliber 2005, S. 12 und 29)","status":"entwurf","scenario":"Ein Börsenkommentator erklärt den starken Kursanstieg einer Aktie: „Sie hat sich in einem Jahr verdreifacht, weil alle auf den Zug aufgesprungen sind. Der Herdentrieb allein hat diese Blase gemacht.“","kurz":"Das Mitlaufen erklärt, warum Menschen kaufen wollen, aber nicht, womit sie kaufen. Wer „allein“ sagt, übersieht die Finanzierung: Woher das Geld für so viele Käufe kam, etwa aus wachsendem Kredit, ist ein eigener Faktor, den die Erklärung auslässt.","prueffrage":"Welche Auskunft könnte zeigen, dass der Herdentrieb allein den Anstieg nicht erklärt?","rueckmeldung":[{"option":1,"text":"Viele Beiträge und große Begeisterung zeigen, dass die Aktie populär war, und Mitlaufen gehört tatsächlich zum Boom. Diese Frage misst aber nur mehr davon und prüft nicht, ob das Mitlaufen allein den Anstieg erklärt."},{"option":2,"text":"Der Kurs und die Käufer eines einzelnen Tages sind ein Detail. Die Behauptung betrifft aber den Anstieg über ein ganzes Jahr, und aus einem Tag lässt sich nicht ablesen, ob der Herdentrieb die einzige Ursache war."},{"option":3,"text":"Lob von bekannten Fondsmanagern und das Nachziehen von Anlegern gehören zum Mitlaufen. Diese Frage bleibt innerhalb der Erklärung des Kommentators und sucht nicht nach einem Faktor, der darin fehlt."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Kindleberger, C. P.; Aliber, R. Z. (2005): Manias, Panics, and Crashes: A History of Financial Crises. 5. Aufl., Hoboken: Wiley","oeffentlich":false},{"typ":"url","kurz":"Schularick, M.; Taylor, A. M. (2009/2011): Credit Booms Gone Bust: Monetary Policy, Leverage Cycles and Financial Crises, 1870–2008. NBER Working Paper 15512","oeffentlich":true,"url":"https://www.nber.org/papers/w15512","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-b2-044","clusterId":"B","werkstueckRef":"B.27","stufe":4,"question":"Welche Prüffrage hilft dir am besten, die Aussage zu beurteilen, ohne aus ihrer Größe auf ihre Wahrheit zu schließen?","scenario":"Ein Video behauptet etwas Spektakuläres. Darunter steht: „10 Millionen Aufrufe! Hunderttausende sind schon auf der Straße! Wir werden jeden Tag mehr!“ Dein Bekannter sagt: „Bei so vielen Leuten muss doch etwas dran sein.“","options":["Wie viele Menschen glauben das, denn unter so vielen Gläubigen finden sich sicher genug, denen ich fachlich vertrauen kann?","Wie schnell wächst die Bewegung, denn rasches Wachstum zeigt doch, dass die Aussage etwas Wahres trifft?","Wie würde ich die Behauptung beurteilen, wenn nur ich davon wüsste, denn dann zählten allein die Belege, nicht Klickzahlen?","Warum behaupten die Kritiker das Gegenteil, denn ihre Motive verraten mehr als die Inhalte ihrer Einwände?"],"correctIndex":2,"explanation":"Aufrufe, Demonstrationsgrößen und Wachstum sagen etwas darüber aus, wie viele Menschen eine Behauptung teilen, nicht darüber, ob sie stimmt. Das ist die Verwechslung von Popularität mit Richtigkeit. Zudem erzeugt Popularität weitere Popularität: Wer mitläuft, macht die Bewegung größer und scheinbar überzeugender, ohne dass ein einziger Beleg hinzukommt. Prüfen lässt sich die Aussage nur, wenn man die Menge gedanklich ausblendet und fragt, was die Belege allein hergeben. Die anderen Fragen bleiben bei der Menge (Zahl der Gläubigen, Wachstumstempo) oder prüfen statt der Aussage die Motive der Kritiker, was ebenfalls nichts über ihre Richtigkeit verrät.","coreRule":"⚡ Eine große Anhängerschaft ist ein Beleg für Beliebtheit, nicht für Wahrheit.","quote":"","quoteLabel":"","beleg":"Werkstück B.27 (Anwendung: Verschwörungsmythen & Kulte; Anti-Denkmuster)","status":"entwurf","kurz":"Aufrufe, Demonstrationsgrößen und Wachstum zeigen nur, wie viele Menschen eine Behauptung teilen, nicht, ob sie stimmt. Prüfen lässt sie sich erst, wenn du die Menge gedanklich ausblendest und fragst, was die Belege allein hergeben.","prueffrage":"Welche der Angaben unter dem Video sagt etwas darüber, ob das Behauptete tatsächlich zutrifft?","rueckmeldung":[{"option":0,"text":"Unter vielen Anhängern finden sich vermutlich auch kundige Leute, doch ihr Anteil ist unbekannt, und die Zahl allein sagt nichts darüber. Fachliche Vertrauenswürdigkeit lässt sich direkt prüfen, ohne die Menge zu zählen."},{"option":1,"text":"Rasches Wachstum belegt vor allem, dass sich viele anschließen. Wer mitläuft, vergrößert die Bewegung und lässt sie überzeugender wirken, ohne dass ein Beleg dazukommt. Wie schnell eine Aussage wächst, sagt also nichts darüber, ob sie stimmt."},{"option":3,"text":"Auch Kritiker können Eigeninteressen haben. Ob ihre Einwände stimmen, hängt aber nicht von ihren Motiven ab, sondern von dem, was sie vorbringen. So rückt die Aussage selbst aus dem Blick, statt dass ihre Belege geprüft werden."}],"familie":"mehrheit-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Appeal to the People“, „Bandwagon“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien"},{"id":"qx-b2-045","clusterId":"B","werkstueckRef":"B.28","stufe":1,"question":"Welche Erklärung passt am besten zu diesem Preisunterschied, und was spricht gegen den Einwand der Teilnehmerin?","scenario":"Bei einem Experiment bekommt die eine Hälfte einer Gruppe eine Kaffeetasse geschenkt, die andere Hälfte nicht. Wer eine Tasse hat, will sie im Schnitt erst ab einem deutlich höheren Preis verkaufen, als die Übrigen bereit sind, für dieselbe Tasse zu zahlen. Eine Teilnehmerin sagt: „Die Tassen sind ja alle gleich. Dann haben die Besitzer eben genauer geprüft, wie gut sie ist.“","options":["Der Unterschied entsteht erst durch das Besitzen: Wer die Tasse hat, empfindet das Abgeben als Verlust und gewichtet ihn stärker als den Erlös, obwohl die Tassen identisch sind.","Der Unterschied entsteht durch bessere Information: Wer die Tasse hat, kennt ihre Qualität genauer und verlangt deshalb einen höheren Preis, obwohl die Tassen identisch sind.","Der Unterschied entsteht durch Gruppendruck: Wer die Tasse hat, richtet sich nach den übrigen Besitzern und nennt einen ähnlich hohen Preis, obwohl die Tassen identisch sind.","Der Unterschied entsteht durch Gewinnstreben: Wer die Tasse hat, gewichtet einen möglichen Zugewinn stärker als einen Verlust und verlangt deshalb mehr, obwohl die Tassen identisch sind."],"correctIndex":0,"explanation":"Die Tassen sind identisch. Der einzige Unterschied zwischen den Gruppen ist der Besitz. Wer eine Tasse hat, für den wird sie Teil des Referenzpunkts. Sie herzugeben wird dann als Verlust erlebt, und ein Verlust wiegt meist schwerer als ein gleich hoher Gewinn. Deshalb verlangen die Besitzer mehr, als die anderen zahlen würden (Besitztumseffekt). Der Einwand der Teilnehmerin scheitert daran, dass identische Tassen keinen Qualitätsunterschied bieten, den die Besitzer genauer prüfen könnten. Dasselbe Muster steckt hinter „30 Tage kostenlos testen“: Was man schon hat, gibt man ungern zurück.","coreRule":"⚡ Wenn identische Dinge nur wegen des Besitzes unterschiedlich bewertet werden, steckt oft Verlustaversion dahinter: Was ich habe, wird Teil meines Referenzpunkts, und Hergeben zählt als Verlust.","beleg":"Werkstück B.28 (Analyse: Besitztumseffekt; Anwendung: Marketing)","status":"entwurf","kurz":"Der Besitz selbst macht den Unterschied: Wer die Tasse hat, erlebt das Hergeben als Verlust, und der wiegt meist schwerer als ein gleich hoher Gewinn. Bei identischen Tassen gibt es nichts, was Besitzer genauer prüfen könnten.","prueffrage":"Welche Information über die Tasse könnten die Besitzer haben, die den anderen fehlt, wenn alle Tassen gleich sind?","rueckmeldung":[{"option":1,"text":"Dass Besitzer mehr über ihre Tasse wissen, ist auf den ersten Blick plausibel. Bei identischen Tassen gibt es aber keinen Qualitätsunterschied, den man genauer prüfen könnte. Der Preisunterschied braucht eine andere Quelle."},{"option":2,"text":"Gegenseitiger Einfluss kann Preise angleichen. Dass sich die Besitzer abstimmen oder aneinander orientieren, wird aber nirgends erwähnt, und warum Besitzer mehr verlangen als Nichtbesitzer, erklärt Gruppendruck nicht."},{"option":3,"text":"Hier ist die Richtung vertauscht. Besitzer verlangen mehr, weil sie das Hergeben als Verlust erleben und der meist schwerer wiegt als ein gleich hoher Gewinn. Ein stärker gewichteter Zugewinn würde den Unterschied nicht erklären."}],"familie":"verlust-und-gewinn-abwaegen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1990): Experimental Tests of the Endowment Effect and the Coase Theorem. Journal of Political Economy 98(6), 1325–1348","oeffentlich":false,"doi":"10.1086/261737"}],"thema":"Psychologie"},{"id":"qx-b2-046","clusterId":"B","werkstueckRef":"B.28","stufe":3,"question":"Ein Artikel behauptet: „Wissenschaftlich bewiesen: Verluste wiegen genau doppelt so schwer wie Gewinne.“ Zur Prüfung liest du die zugrunde liegenden Messungen nach. Die klassische Studie kam auf einen Faktor von 2,25. Eine große Zusammenstellung vieler späterer Arbeiten ergab im Mittel etwa 1,96. Betrachtet man nur Entscheidungen zwischen riskanten Lotterien, liegt der Wert bei etwa 1,31. Was folgt daraus für die Behauptung?","options":["Der Artikel überzeichnet: Der Wert ist eine Faustregel und schwankt je nach Methode.","Der Artikel liegt richtig: Die Werte liegen alle in der Nähe von 2, also ist „genau doppelt“ eine feste Konstante.","Der Artikel liegt komplett falsch: Weil die Werte voneinander abweichen, spielen Verluste überhaupt keine Rolle.","Der Artikel ist nicht prüfbar: Solange die Studien keinen einzigen Wert nennen, lässt sich nichts sagen."],"correctIndex":0,"explanation":"Die Messwerte streuen je nach Methode erheblich: 2,25 in der klassischen Studie, etwa 1,96 im Mittel vieler späterer Arbeiten, nur etwa 1,31 bei riskanten Lotterien. Eine Größe, die so stark von der Messmethode abhängt, ist keine feste Konstante, sondern eine Faustregel. „Genau doppelt“ und „wissenschaftlich bewiesen“ verleihen der Zahl eine Präzision, die die Daten nicht hergeben. Die Gegenrichtung ist ebenso ein Fehlschluss: Schwankende Schätzwerte bedeuten nicht, dass der Effekt verschwindet. Die genannten Messungen liegen durchgehend über 1; wie stark der Effekt ausfällt, hängt von Methode und Kontext ab. Gal und Rucker (2018) bestreiten sogar, dass Verluste im Allgemeinen stärker wirken als gleich hohe Gewinne. Das „doppelt so stark“ ist also eine gerundete Faustregel, kein Naturgesetz.","coreRule":"⚡ Eine Zahl, die je nach Messmethode stark schwankt, ist eine Faustregel, keine Konstante.","beleg":"Werkstück B.28 (Kernidee; Analyse); Fn. gl-b-verlust (Tversky/Kahneman 1992, S. 311; Brown u. a. 2024, JEL 62(2); Walasek u. a. 2024, JEP 103; Gal/Rucker 2018)","status":"entwurf","scenario":"","kurz":"Der Wert schwankt je nach Methode zwischen etwa 1,3 und 2,25, ist also eine Faustregel und keine feste Konstante. Der Fehler liegt darin, einer Zahl durch „genau“ und „bewiesen“ eine Präzision zu geben, die die Daten nicht hergeben.","prueffrage":"Wie weit liegen die drei genannten Werte auseinander, und welcher davon ist genau 2?","rueckmeldung":[{"option":1,"text":"Zwei der drei Werte liegen tatsächlich dicht bei 2. Der dritte, etwa 1,31, weicht aber deutlich ab. Eine Größe, die so von der Messmethode abhängt, ist keine feste Konstante, und „genau doppelt“ täuscht eine Präzision vor."},{"option":2,"text":"Dass der Artikel übertreibt, stimmt. Schwankende Schätzwerte heißen aber nicht, dass der Effekt verschwindet: Alle genannten Messungen liegen über 1. Wie stark er ausfällt, hängt von Methode und Kontext ab."},{"option":3,"text":"Die Behauptung lässt sich sehr wohl prüfen, und genau das passiert hier: Es liegen drei konkrete Werte vor (2,25, etwa 1,96 und etwa 1,31). Sie sind nur nicht einheitlich genug, um „genau doppelt“ zu tragen."}],"familie":"zahl-zur-quelle","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Brown, A. L.; Imai, T.; Vieider, F. M.; Camerer, C. F. (2024): Meta-Analysis of Empirical Estimates of Loss Aversion (Preprint MetaArXiv; Zeitschriftenfassung JEL 62(2), 485–516)","oeffentlich":true,"doi":"10.31222/osf.io/hnefr","abruf":"2026-10-12"},{"typ":"doi","kurz":"Walasek, L.; Mullett, T. L.; Stewart, N. (2024): A meta-analysis of loss aversion in risky contexts. Journal of Economic Psychology 103, 102740","oeffentlich":false,"doi":"10.1016/j.joep.2024.102740"},{"typ":"doi","kurz":"Gal, D.; Rucker, D. D. (2018): The Loss of Loss Aversion: Will It Loom Larger Than Its Gain? Journal of Consumer Psychology 28(3), 497–516","oeffentlich":false,"doi":"10.1002/jcpy.1047"}],"thema":"Geschichte und Wissenschaft"},{"id":"qx-b2-047","clusterId":"B","werkstueckRef":"B.28","stufe":4,"question":"Welche Erklärung ihres Verhaltens ist am sparsamsten, wenn du nur ihre Lage betrachtest?","scenario":"Eine Bekannte ist seit Jahren in einer Gemeinschaft, die ihr viel bedeutet: Dort sind ihre engsten Freunde, ihre Rolle und das Gefühl, etwas Besonderes zu wissen. Sie hat investiert und gespendet. Nun hat ihr jemand die zentralen Behauptungen der Gruppe überzeugend widerlegt. Trotzdem sagt sie: „Du magst ja recht haben, aber ich bleibe.“","options":["Der erwartete Verlust durch einen Austritt wiegt für sie schwerer als der Gewinn, die Wahrheit zu erkennen.","Die Freude an der Gemeinschaft wiegt für sie so stark, dass sie widerlegte Behauptungen kaum noch als Kummer spürt.","Sie hält jede Widerlegung für Teil einer Verschwörung, sodass die Kosten eines Austritts für sie keine Rolle spielen.","Die lange Zeit in der Gemeinschaft hat ihr Urteilsvermögen dauerhaft zerstört, sodass sie Fakten nicht mehr verarbeiten kann."],"correctIndex":0,"explanation":"Wer aus einer Gemeinschaft austritt, verliert nicht nur eine Überzeugung, sondern auch Freunde, Identität, das Gefühl besonderen Wissens und die investierte Zeit und das Geld. Menschen gewichten Verluste meist stärker als gleich große Gewinne (Verlustaversion); wie stark, hängt von Methode und Lage ab. Deshalb kann der erwartete Verlust schwerer wiegen als der Gewinn, die Wahrheit zu erkennen, und diese Erklärung kommt mit ihrer geschilderten Lage aus. Die anderen Erklärungen brauchen zusätzliche, unbelegte Annahmen: eine Verschwörungsüberzeugung, ein zerstörtes Urteilsvermögen oder eine Freude, die Widerlegtes aufwiegt. Die Verlust-Erklärung beschreibt zudem einen Mechanismus, kein Urteil über die Intelligenz der Bekannten.","coreRule":"⚡ Wer fragt, warum jemand nicht geht, sollte zuerst fragen, was der Austritt ihn kosten würde, nicht nur, ob er recht hat.","beleg":"Werkstück B.28 (Anwendung: Verschwörungsmythen & Kulte)","status":"entwurf","kurz":"Aus ihrer Lage allein erklärt sich das Bleiben: Der Austritt kostet Freunde, Rolle, Identität und das Investierte, und Verluste wiegen meist schwerer als gleich große Gewinne. Eine zerstörte Urteilskraft oder eine Verschwörungsidee muss man dafür nicht annehmen.","prueffrage":"Was hängt für sie außer der Frage, ob die Behauptungen stimmen, noch an dieser Gemeinschaft?","rueckmeldung":[{"option":1,"text":"Dass die Gemeinschaft ihr viel bedeutet, stimmt: Freunde und Rolle hängen daran. Dass diese Freude Widerlegtes kaum noch spüren lässt, ist aber eine Zusatzannahme; sie räumt ja selbst ein, ihr Gegenüber könne recht haben."},{"option":2,"text":"Dass sie die Widerlegung als Angriff erlebt, wäre denkbar, doch ihre Worte deuten eher auf das Gegenteil: Sie räumt ein, ihr Gegenüber möge recht haben. Eine Verschwörungsüberzeugung müsste man erst hinzuerfinden."},{"option":3,"text":"Hier wird aus einem Verhalten gleich ein dauerhafter Schaden am Denken abgeleitet. Sie geht aber auf die Widerlegung ein und räumt ein, sie könne zutreffen; ein gewichtiger Verlust erklärt ihr Bleiben, ohne ihr das Urteilsvermögen abzusprechen."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brown, A. L.; Imai, T.; Vieider, F. M.; Camerer, C. F. (2024): Meta-Analysis of Empirical Estimates of Loss Aversion (Preprint MetaArXiv)","oeffentlich":true,"doi":"10.31222/osf.io/hnefr","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-048","clusterId":"B","werkstueckRef":"B.28","stufe":2,"question":"Welche Frage prüft am besten, ob du das Abo behalten solltest?","scenario":"Seit Jahren läuft von deinem Konto ein Abo ab, das du kaum noch nutzt. Eine Freundin sagt: „Kündige es doch einfach.“ Du antwortest: „Aber ich habe schon so viel dafür bezahlt, das kann ich jetzt nicht wegwerfen.“","options":["Wie viel habe ich bisher insgesamt eingezahlt, und darf dieser Betrag am Ende wirklich umsonst gewesen sein?","Wenn ich das Abo heute nicht hätte, würde ich es jetzt neu abschließen und dafür diesen Aufwand an Geld und Zeit betreiben?","Wie groß ist der mögliche Verlust, wenn ich kündige, verglichen mit dem möglichen Gewinn, wenn ich einfach weitermache wie bisher?","Wie viele andere Menschen haben das Abo behalten, und was wissen sie vielleicht, das ich bisher noch nicht gesehen habe?"],"correctIndex":1,"explanation":"Eine gute Entscheidung schaut nach vorn: Was bringt mir das Abo ab jetzt, und was kostet es mich ab jetzt? Am klarsten wird das, wenn man sich vorstellt, man besäße es nicht, und fragt, ob man heute Geld und Zeit dafür aufwenden würde. Das bereits Eingezahlte ist nicht mehr zurückzuholen, egal ob du kündigst oder nicht. Wer darauf schaut, wirft gutes Geld schlechtem hinterher (versunkene Kosten). Der Blick auf das, was andere tun, beantwortet nicht die Frage, was das Abo dir ab jetzt bringt. Und die Abwägung „Verlust bei Kündigung gegen Gewinn beim Weitermachen“ bleibt am aktuellen Besitz als Referenzpunkt hängen, sodass Kündigen als Verlust kodiert wird.","coreRule":"⚡ Frag nicht, was du schon investiert hast, sondern ob du heute neu einsteigen würdest.","quote":"würde ich mein Geld, meine Zeit oder meinen Verstand heute dafür aufwenden, um exakt hier einzusteigen?","quoteLabel":"Prüffrage für festgefahrene Entscheidungen:","beleg":"Werkstück B.28 (Anti-Denkmuster: Clean-Slate-Test; Werkbank-Frage)","status":"entwurf","kurz":"Entscheidend ist, was das Abo dir ab jetzt bringt und kostet. Stell dir vor, du hättest es nicht: Würdest du heute Geld und Zeit dafür aufwenden? Das bisher Gezahlte ist so oder so weg und darf die Entscheidung nicht lenken.","prueffrage":"Welcher Teil der Kosten hängt davon ab, ob du heute kündigst oder behältst, und welcher steht ohnehin fest?","rueckmeldung":[{"option":0,"text":"Verschwendung zu vermeiden ist ein verständliches Motiv. Das bisher Eingezahlte ist aber verloren, ob du kündigst oder nicht; wer darauf schaut, richtet die Entscheidung nach dem Vergangenen statt nach dem, was noch kommt."},{"option":2,"text":"Verlust und Gewinn abzuwägen ist zwar sinnvoll und schaut nach vorn. Dabei gilt aber der heutige Besitz als Ausgangspunkt, und Kündigen wirkt automatisch wie ein Verlust. Das verschiebt die Abwägung zugunsten des Behaltens, noch bevor du rechnest."},{"option":3,"text":"Was andere tun, kann Hinweise liefern, sagt aber wenig über deinen Fall. Ob das Abo dir ab jetzt etwas bringt, hängt davon ab, wie du es nutzt und was es dich kostet, nicht davon, wie viele es behalten haben."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Watzek, J.; Brosnan, S. F. (2020): Capuchin and rhesus monkeys show sunk cost effects in a psychomotor task. Scientific Reports 10, 20396","oeffentlich":true,"doi":"10.1038/s41598-020-77301-w","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7683735/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost. Organizational Behavior and Human Decision Processes 35(1), 124–140","oeffentlich":false,"doi":"10.1016/0749-5978(85)90049-4"},{"typ":"doi","kurz":"Kahneman, D.; Knetsch, J. L.; Thaler, R. H. (1991): Anomalies: The Endowment Effect, Loss Aversion, and Status Quo Bias. Journal of Economic Perspectives 5(1), 193–206","oeffentlich":true,"doi":"10.1257/jep.5.1.193","url":"https://www.aeaweb.org/articles?id=10.1257/jep.5.1.193","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-b2-049","clusterId":"B","werkstueckRef":"B.29","stufe":2,"question":"Was ist an Lenas Schlussfolgerung fehlerhaft?","options":["Sie schließt aus dem Nicht-Finden auf das Nicht-Vorhandensein, obwohl Verzerrungen meist unbewusst ablaufen und sich durch bloßes Nach-innen-Schauen gar nicht zeigen.","Sie schaut zu selten in sich hinein, denn wer sich oft genug selbst beobachtet, deckt auch unbewusste Verzerrungen zuverlässig auf.","Sie prüft sich zu kritisch, weil ein zu strenger Blick auf die eigenen Motive das Urteil über andere unzuverlässig macht.","Sie bewertet ihren Kollegen zu streng, denn dessen Verhalten lässt sich überhaupt nicht zuverlässig auf eine Verzerrung zurückführen."],"correctIndex":0,"explanation":"Lena beurteilt sich über ihre Gedanken und Absichten, den Kollegen aber über sein sichtbares Verhalten. In ihren Gedanken findet sie fast immer gute Absichten. Die meisten Verzerrungen laufen jedoch unbewusst ab und sind durch einfaches Nach-innen-Schauen grundsätzlich nicht auffindbar. Aus „ich finde nichts“ folgt deshalb nicht „da ist nichts“. Zuverlässiger ist ein Blick von außen: ihr eigenes Verhalten prüfen (Welche Gegenargumente ignoriere ich? Welche Quellen nutze ich?) oder jemanden bitten, die eigene Position auseinanderzunehmen.","coreRule":"⚡ Wer nur in sich hineinschaut, findet gute Absichten und übersieht die Verzerrung.","beleg":"Werkstück B.29 (Analyse: Der Introspektions-Trugschluss)","status":"entwurf","scenario":"Lena arbeitet sich durch eine Liste typischer Denkfehler. Bei ihrem Kollegen erkennt sie sofort, dass er nur Studien zitiert, die seine Meinung stützen. Danach prüft sie sich selbst: Sie geht in Gedanken durch, was sie bei ihrer eigenen Position antreibt, findet dort nur den Wunsch, die Wahrheit herauszufinden, und stellt fest: „Bei mir ist keine Voreingenommenheit im Spiel.“","kurz":"Lena findet beim Blick nach innen nur gute Absichten und schließt daraus, dass keine Verzerrung im Spiel ist. Aber „nichts gefunden“ heißt nicht „nichts da“: Verzerrungen laufen meist unbewusst ab und zeigen sich im eigenen Verhalten, nicht im Nachdenken.","prueffrage":"Woran würde man bei Lena und bei ihrem Kollegen jeweils erkennen, ob Voreingenommenheit im Spiel ist?","rueckmeldung":[{"option":1,"text":"Mehr Selbstbeobachtung wirkt wie die naheliegende Abhilfe. Unbewusste Verzerrungen bleiben beim Nach-innen-Schauen aber unsichtbar, egal wie oft man es tut; eher hilft ein Blick auf das eigene Verhalten oder von außen."},{"option":2,"text":"Lenas Prüfung war eher zu mild: Sie fragte nur nach ihren Absichten, und dort findet man meist Gutes. Eine strengere Selbstprüfung würde das Urteil über andere nicht entwerten. Entscheidend ist, was sie prüft, nämlich Gedanken statt Verhalten."},{"option":3,"text":"Dass der Kollege nur stützende Studien zitiert, ist sichtbares Verhalten und ein Hinweis auf Voreingenommenheit. Fehlerhaft ist Lenas Schluss über sich selbst: Weil sie beim Nach-innen-Schauen nichts findet, hält sie sich für unvoreingenommen."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Pronin, E.; Kugler, M. B. (2007): Valuing thoughts, ignoring behavior: The introspection illusion as a source of the bias blind spot. Journal of Experimental Social Psychology 43(4), 565–578","oeffentlich":false,"doi":"10.1016/j.jesp.2006.05.011"}],"thema":"Psychologie"},{"id":"qx-b2-050","clusterId":"B","werkstueckRef":"B.29","stufe":3,"question":"Was ist an Jonas' Schlussfolgerung am problematischsten?","options":["Er schließt aus seinem Wissen über Denkfehler, dass er selbst gegen sie immun ist, obwohl nach Befunden selbst höhere kognitive Fähigkeit den blinden Fleck nicht verkleinert.","Er schließt aus seiner Fähigkeit, Denkfehler zu erkennen, dass es nur wenige gibt, obwohl er dafür nur seine eigenen Eindrücke heranzieht.","Er schließt aus seinem Urteil über den Kollegen, dass dessen Argumente schwach sind, obwohl er sie vorschnell abgewertet haben könnte.","Er schließt aus seinem Studium, dass er Denkfehler sicher erkennt, obwohl er sie nur im Hörsaal und nie im Alltag geübt hat."],"correctIndex":0,"explanation":"Die meisten Verzerrungen wirken unbewusst. Wer nach innen schaut, findet meist gute Absichten und schließt daraus, dass keine Voreingenommenheit im Spiel ist. Auch Klugheit schützt nicht: In einer Studie von West, Meserve und Stanovich (2012) mit Studierenden verkleinerten weder höhere kognitive Fähigkeit noch einschlägige Denkstile den blinden Fleck, wenn überhaupt ging höhere Fähigkeit mit einem etwas größeren einher. Eine mögliche Erklärung: Klügere können ihre voreingenommenen Schlüsse geschickter rational begründen. Daraus folgt für Jonas: Sein Wissen macht ihn vor allem besser darin, Fehler bei anderen zu entdecken, nicht bei sich selbst. Sinnvoller wäre ein externer Check, etwa jemanden zu bitten, die eigene Position gezielt zu zerlegen.","coreRule":"⚡ Wissen über Denkfehler und hohe Intelligenz schützen nicht vor dem eigenen blinden Fleck; prüfe dich von außen, nicht nur durch Nach-innen-Schauen.","beleg":"Werkstück B.29 (Analyse: Intelligenz schützt nicht); Fn. gl-b-blindspot (West/Meserve/Stanovich 2012, JPSP 103(3), S. 511, 515)","status":"entwurf","scenario":"In einer Diskussion über einen Zeitungsartikel sagt Jonas: „Ich habe Statistik und Logik studiert und kenne die gängigen Denkfehler in- und auswendig. Von denen lasse ich mich nicht mehr täuschen. Bei meinem Kollegen erkenne ich sie sofort, bei mir selbst ist das kein Thema.“","kurz":"Wer Denkfehler gut kennt, entdeckt sie vor allem bei anderen, ist aber nicht gegen sie gefeit: Selbst höhere kognitive Fähigkeit verkleinert den blinden Fleck nach bisherigen Befunden nicht. Jonas schließt aus seinem Wissen auf eine Immunität, die es nicht gibt.","prueffrage":"Worauf stützt Jonas seine Aussage, bei ihm selbst seien Denkfehler kein Thema?","rueckmeldung":[{"option":1,"text":"Jonas behauptet gar nicht, dass es nur wenige Denkfehler gibt. Seine Aussage dreht sich darum, dass er selbst ihnen nicht unterliege, und genau dieser Schluss auf sich selbst trägt nicht."},{"option":2,"text":"Ein zu schnelles Urteil über den Kollegen wäre denkbar, doch darüber sagt Jonas nichts Genaueres. Problematisch ist sein Schluss über sich selbst: Weil er die Denkfehler kennt, hält er sich für immun gegen sie."},{"option":3,"text":"Dass Wissen allein noch keine geübte Anwendung ist, stimmt oft. Ob Jonas nur im Hörsaal geübt hat, ist aber gar nicht bekannt, und selbst Geschulte und Kluge übersehen eigene Verzerrungen, weil diese meist unbewusst wirken."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3), 506–519 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1037/a0028857","url":"https://pubmed.ncbi.nlm.nih.gov/22663351/","abruf":"2026-10-12"},{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-b2-051","clusterId":"B","werkstueckRef":"B.29","stufe":4,"question":"Was solltest du als Nächstes tun, um herauszufinden, ob du selbst voreingenommen bist?","scenario":"In einer hitzigen Diskussion über Ernährung bist du überzeugt, der Einzige am Tisch zu sein, der objektiv urteilt. Du hast viel über Denkfehler gelesen und erkennst bei deinem Gegenüber sofort Bestätigungsfehler und selektive Quellenwahl.","options":["Du bittest eine vertraute Person mit anderer Meinung, dein Argument nach Kräften auseinanderzunehmen, und hörst zunächst nur zu.","Du zählst dem Gegenüber seine Denkfehler Punkt für Punkt auf, damit die Debatte auf eine sachliche Grundlage kommt.","Du liest noch mehr Fachliteratur über kognitive Verzerrungen, damit du sie künftig auch bei dir selbst erkennst.","Du horchst noch genauer in dich hinein und schreibst deine Motive auf, damit du jede mögliche Voreingenommenheit bemerkst."],"correctIndex":0,"explanation":"Die meisten Verzerrungen wirken unbewusst. Wenn du in dich hineinhorchst und keine Voreingenommenheit findest, heißt das nicht, dass keine da ist: Du suchst mit demselben Gehirn, das den Fehler macht. Auch mehr Wissen über Denkfehler hilft nur begrenzt. Es macht dich vor allem besser darin, Fehler bei anderen zu entdecken, während der eigene blinde Fleck unangetastet bleibt. In einer Studie ging höhere kognitive Fähigkeit sogar eher mit einem größeren blinden Fleck einher, und kluge Menschen können voreingenommene Schlüsse oft geschickter rechtfertigen. Die Fehler anderer aufzuzählen ist genau das Verhalten, das den blinden Fleck nährt, statt ihn zu verkleinern. Was von innen unsichtbar bleibt, kann ein Blick von außen sichtbar machen: Jemand, der anderer Meinung ist und dein Argument ernsthaft angreift, findet Lücken, die du selbst nicht siehst. Dass du dann zunächst nur zuhörst, verhindert, dass du die Kritik sofort wegerklärst.","coreRule":"⚡ Was du von innen nicht siehst, zeigt dir nur ein Blick von außen.","beleg":"Werkstück B.29 (Anti-Denkmuster: Die wirksamste Taktik; Anwendung: Der intellektuelle Skeptiker)","status":"entwurf","kurz":"Verzerrungen wirken meist unbewusst und lassen sich von innen kaum erkennen, denn du prüfst mit demselben Gehirn, das den Fehler macht. Ein Blick von außen findet Lücken, die dir verborgen bleiben, vor allem, wenn du zunächst nur zuhörst.","prueffrage":"Wer hat dein eigenes Argument in dieser Diskussion bisher überhaupt auf Schwächen geprüft?","rueckmeldung":[{"option":1,"text":"Deine Beobachtungen beim Gegenüber können durchaus stimmen. Wer sie aber aufzählt, lässt das eigene Argument unangetastet und nährt so den blinden Fleck, statt ihn zu verkleinern."},{"option":2,"text":"Mehr Wissen über Denkfehler ist nicht wertlos, hilft bei der Selbstprüfung aber nur begrenzt. Es macht vor allem besser darin, Fehler bei anderen zu entdecken, und kluge Menschen rechtfertigen eigene Schlüsse oft geschickter."},{"option":3,"text":"Selbstbeobachtung schadet nicht, stößt aber an eine Grenze: Du suchst mit demselben Gehirn, das den Fehler macht. Findest du nichts, heißt das noch nicht, dass nichts da ist, denn die meisten Verzerrungen wirken unbewusst."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"West, R. F.; Meserve, R. J.; Stanovich, K. E. (2012): Cognitive Sophistication Does Not Attenuate the Bias Blind Spot. Journal of Personality and Social Psychology 103(3), 506–519 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1037/a0028857","url":"https://pubmed.ncbi.nlm.nih.gov/22663351/","abruf":"2026-10-12"},{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"}],"thema":"Gesundheit"},{"id":"qx-b2-052","clusterId":"B","werkstueckRef":"B.29","stufe":1,"question":"Wie lässt sich am besten erklären, was in dieser Situation passiert?","options":["Lena erkennt Verzerrungen grundsätzlich nicht, bei Tom ebenso wenig wie bei sich selbst, und urteilt daher beliebig.","Lena ist überzeugt, dass andere ihr jeden Denkfehler sofort ansehen und klar benennen würden, und hält sich deshalb zurück.","Lena hält ihr eigenes Denken für objektiver als das der anderen, weil sie in sich hineinhorcht und dort nur gute Absichten findet.","Lena gewichtet ihre eigenen Fehler stärker als die anderer, misstraut sich ständig selbst und zögert deshalb mit Urteilen."],"correctIndex":2,"explanation":"Lena misst Tom an seinem Verhalten, sich selbst aber an ihren Absichten: Sie horcht in sich hinein, findet dort nur den Wunsch nach Wahrheit und hält sich deshalb für objektiver. Viele Verzerrungen wirken jedoch unbewusst und zeigen sich beim Nach-innen-Schauen nicht; aus „nichts gefunden“ folgt nicht „nichts da“. Ihr eigener Schreibtisch zeigt dasselbe Muster, das sie Tom vorwirft. Dass sie Verzerrungen grundsätzlich nicht erkenne und beliebig urteile, passt nicht: Bei Tom achtet sie gezielt darauf, ihr Urteil ist einseitig, nicht zufällig. Furcht vor Entdeckung oder Selbstmisstrauen passen ebenso wenig, denn sie urteilt selbstsicher und sieht keinen Anlass, an sich zu zweifeln.","coreRule":"⚡ Was du bei anderen sofort siehst, übersiehst du bei dir selbst am leichtesten.","beleg":"Werkstück B.29 (Kernidee; Eingangsszene; Introspektions-Trugschluss)","status":"entwurf","scenario":"Lena erklärt in einer hitzigen Diskussion: „Mein Kollege Tom sieht nur die Quellen, die zu seiner Meinung passen, und ignoriert alles andere. Der ist komplett voreingenommen. Ich dagegen suche einfach die Wahrheit.“ Wenn man sich ihren Schreibtisch anschaut, stellt man fest: Auch sie hat fast nur Artikel gesammelt, die ihre eigene Position stützen. Auf Nachfrage sagt sie: „Ich habe nachgedacht und bei mir keine Voreingenommenheit gefunden.“","kurz":"Lena schaut nach innen, findet dort gute Absichten und hält sich deshalb für objektiver als Tom. Die meisten Verzerrungen wirken aber unbewusst: Wer sie durch Nach-innen-Schauen sucht und nichts findet, schließt fälschlich, es sei nichts da.","prueffrage":"Was liegt auf Lenas Schreibtisch, und wie passt das zu ihrem Urteil über sich selbst?","rueckmeldung":[{"option":0,"text":"Ganz ohne Blick für Verzerrungen urteilt sie nicht: Bei Tom achtet sie gezielt darauf und benennt sie. Ihr Urteil ist nicht beliebig, sondern einseitig, denn bei sich selbst findet sie nichts, obwohl ihr Schreibtisch dasselbe Muster zeigt."},{"option":1,"text":"Bei dieser Erklärung würde Lena sich zurückhalten, weil sie Entdeckung fürchtet. Sie urteilt aber offensiv und hält sich für objektiver als Tom. Dass andere ihre Fehler sehen könnten, kommt in ihrer Aussage gar nicht vor."},{"option":3,"text":"Selbstkritik wäre hier hilfreich, bei Lena fehlt sie aber gerade. Sie urteilt selbstsicher über Tom und sieht keinen Anlass, an sich zu zweifeln. Ständiges Selbstmisstrauen und Zögern passen also nicht zu ihr."}],"familie":"werkzeuge-gegen-sich-selbst","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Pronin, E.; Kugler, M. B. (2007): Valuing thoughts, ignoring behavior: The introspection illusion as a source of the bias blind spot. Journal of Experimental Social Psychology 43(4), 565–578","oeffentlich":false,"doi":"10.1016/j.jesp.2006.05.011"},{"typ":"url","kurz":"Pronin, E. (2007): Perception and misperception of bias in human judgment. Trends in Cognitive Sciences 11(1), 37–43 (Zusammenfassung frei auf PubMed)","oeffentlich":true,"doi":"10.1016/j.tics.2006.11.001","url":"https://pubmed.ncbi.nlm.nih.gov/17129749/","abruf":"2026-10-12"}],"thema":"Psychologie"},{"id":"qx-b2-053","clusterId":"B","werkstueckRef":"B.30","stufe":1,"question":"Warum ist Rot im nächsten Spiel nicht wahrscheinlicher als im ersten Spiel des Abends?","scenario":"Ein Freund erzählt dir: „Im Kasino ist die Roulettekugel gestern zwanzigmal hintereinander auf Schwarz gefallen. Ich setze jetzt alles auf Rot, nach so einer Serie muss Rot einfach kommen.“ Der Tisch ist unauffällig und funktioniert einwandfrei.","options":["Nach so langer Serie ist Rot sogar leicht wahrscheinlicher, aber der Vorteil ist viel zu klein, um ihn zu nutzen.","Der Tisch war vermutlich manipuliert; bei einem fairen Tisch hätte sich die Serie längst wieder ausgeglichen.","Zufall verlangt einen Ausgleich der Abweichungen, nur geschieht das erst nach sehr vielen weiteren Runden.","Die Kugel hat kein Gedächtnis: Bei unabhängigen Zufallsereignissen ist die Chance in jedem Spiel dieselbe, was zuvor auch fiel."],"correctIndex":3,"explanation":"Jedes Spiel ist ein neuer, unabhängiger Wurf. Die Kugel weiß nicht, was vorher gefallen ist, also bleibt die Chance auf Rot unverändert. Auch das Gesetz der großen Zahlen gleicht nichts aus, es verdünnt frühe Abweichungen nur: Über Tausende Spiele fällt eine frühe Serie immer weniger ins Gewicht, ohne dass der Zufall etwas nachholen müsste. Wer nach einer Serie auf die Gegenseite setzt, begeht den Spielerfehlschluss. Die Frage, die ihn entlarvt: Weiß das Ding, das hier „würfelt“, was vorher passiert ist? Wenn nicht, ist der nächste Wurf ein erster Wurf.","coreRule":"⚡ Zufall gleicht nichts aus: Münze, Kugel und Würfel haben kein Gedächtnis.","beleg":"Werkstück B.30 (Eingangsszene; Kernidee; Analyse); Fn. gl-b-montecarlo (Huff 1959; Zahl nicht durch Kasinoprotokolle belegt); Fn. gl-b-tversky (Tversky/Kahneman 1971, S. 105–106)","status":"entwurf","kurz":"Jedes Spiel ist ein neuer, unabhängiger Wurf, die Kugel „weiß“ nichts von der Serie. Der naheliegende Fehler ist, einen Ausgleich zu erwarten, obwohl der nächste Wurf wie ein erster Wurf ist.","prueffrage":"Wie viele rote und wie viele schwarze Fächer hat der Kessel vor dem ersten Spiel des Abends, und wie viele nach der Serie?","rueckmeldung":[{"option":0,"text":"Ein kleiner Rest von Ausgleich wirkt vorsichtiger als die volle Erwartung, Rot sei „fällig“. Doch die Kugel kennt die Serie nicht: Die Chance auf Rot ist genau so groß wie im ersten Spiel, es gibt nicht einmal einen kleinen Vorteil."},{"option":1,"text":"Eine so lange Serie wirkt auffällig und weckt schnell den Verdacht auf Manipulation. Der Tisch funktioniert aber einwandfrei, und gerade an einem fairen Tisch holt der Zufall nichts nach: Die Chance auf Rot bleibt in jedem Spiel gleich."},{"option":2,"text":"Auf lange Sicht nähert sich der Anteil von Rot tatsächlich dem erwarteten Wert. Das geschieht aber nicht, weil der Zufall etwas nachholt: Eine frühe Serie wird nur von immer mehr späteren Spielen verdünnt. Für das nächste Spiel ändert sich nichts."}],"familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Gambler’s“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1971): Belief in the law of small numbers. Psychological Bulletin 76(2), 105–110","oeffentlich":false,"doi":"10.1037/h0031322"}],"thema":"Geld und Zahlen"},{"id":"qx-b2-054","clusterId":"B","werkstueckRef":"B.30","stufe":2,"question":"Was ist an ihrem Vorgehen fehlerhaft?","scenario":"Eine Kreditprüferin hat drei Anträge hintereinander bewilligt. Beim vierten Antrag, der den anderen vom Risiko her gleicht, will sie ablehnen – „nur um nicht immer dasselbe zu entscheiden“.","options":["Sie behandelt die Reihe der Entscheidungen so, als müsse sie sich ausgleichen, obwohl jeder Antrag für sich zu beurteilen ist.","Sie behandelt jeden Antrag für sich, obwohl drei Bewilligungen in Folge die Chancen des nächsten Antrags tatsächlich verändern.","Sie folgt ihrer Routine, obwohl sie nach einer Serie gleichartiger Entscheidungen besser die Linie wechseln sollte.","Sie urteilt zu streng, weil ein Mensch mit Berufserfahrung von früheren Entscheidungen grundsätzlich nicht beeinflusst werden darf."],"correctIndex":0,"explanation":"Jeder Antrag ist für sich zu bewerten; die vorherigen Entscheidungen sagen nichts über den nächsten Fall. Wer nach einer Serie das Gegenteil wählt, damit sich die Reihe „ausgleicht“, unterliegt dem Spielerfehlschluss: Er unterstellt einem Ablauf ohne Gedächtnis einen Ausgleichsdrang. Das ist kein Randphänomen: Chen, Moskowitz und Shue (2016) werteten über 150.000 Asylentscheidungen, rund 1,5 Millionen Schiedsrichter-Entscheidungen und gut 9.000 Kreditprüfungen aus einem Feldexperiment aus. Asylrichter, Kreditprüfer und Baseball-Schiedsrichter schwenkten nach einer oder mehreren gleichartigen Entscheidungen um einige Prozentpunkte häufiger „um“, und zwar umso öfter, je länger die Serie war. Ein Antrag verdient eine eigene Prüfung. Die Entscheidungen davor sind kein Argument.","coreRule":"⚡ Jeder Fall beginnt neu: Die Entscheidung davor darf die Entscheidung jetzt nicht färben.","beleg":"Werkstück B.30 (Anwendung: Urteile unter Serien; Zahlen und Befund laut Buchtext); Fn. gl-b-chen (Chen/Moskowitz/Shue 2016, QJE 131(3), S. 1181–1242)","status":"entwurf","kurz":"Jeder Antrag ist für sich zu prüfen, denn die Bewilligungen davor sagen nichts über den nächsten Fall. Der Denkfehler ist, einem Ablauf ohne Gedächtnis einen Drang zum Ausgleich zu unterstellen.","prueffrage":"Worin unterscheidet sich der vierte Antrag vom Risiko her von den drei bereits bewilligten?","rueckmeldung":[{"option":1,"text":"Nach einer Serie scheint der nächste Fall „fällig“ zu sein. Doch die Prüferin beurteilt den Antrag gerade nicht für sich, und die drei Bewilligungen ändern nichts am vierten Antrag, der den anderen vom Risiko her gleicht."},{"option":2,"text":"Ein Wechsel der Linie wirkt wie Aufmerksamkeit statt Routine. Maßgeblich ist aber der einzelne Antrag, nicht die Länge der Serie. Wer wechselt, nur weil sich die Reihe ausgleichen soll, urteilt gerade nicht nach der Sache."},{"option":3,"text":"Dass frühere Entscheidungen auch Erfahrene beeinflussen können, stimmt; das Problem ist hier aber nicht Strenge an sich. Fehlerhaft ist, dass sie ablehnen will, damit sich die Reihe ausgleicht, statt den Antrag selbst zu prüfen."}],"familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Chen, D. L.; Moskowitz, T. J.; Shue, K. (2016): Decision-Making under the Gambler's Fallacy: Evidence from Asylum Judges, Loan Officers, and Baseball Umpires. NBER Working Paper 22026","oeffentlich":true,"url":"https://www.nber.org/papers/w22026","seite":"14, 27","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-b2-055","clusterId":"B","werkstueckRef":"B.30","stufe":3,"question":"Eine Basketballtrainerin sagt vor dem Spiel: „Wer drei Würfe in Folge getroffen hat, trifft mit höherer Wahrscheinlichkeit auch den vierten.“ Ein Kollege entgegnet: „Das ist derselbe Fehler wie beim Roulette, wo nach fünfmal Rot angeblich Schwarz ‚fällig‘ ist.“ Wie beurteilst du den Einwand des Kollegen?","options":["Der Einwand ist berechtigt, weil jeder Wurf zufällig ist und eine Trefferserie deshalb bei Spielern ebenso wenig etwas über den nächsten Wurf aussagt wie bei einer Kugel.","Der Einwand greift zu kurz, weil ein Spieler anders als eine Kugel ein Gedächtnis hat: Form und Konzentration können schwanken, sodass eine Serie tatsächlich etwas über den nächsten Wurf aussagen kann.","Der Einwand ist berechtigt, weil beim Basketball die größere Zahl der Würfe dafür sorgt, dass sich Serien im Lauf des Spiels zuverlässig ausgleichen.","Der Einwand greift zu kurz, weil eine Trefferserie im Sport immer eine Fortsetzung ankündigt, während Serien beim Roulette immer ein Ende ankündigen."],"correctIndex":1,"explanation":"Der Spielerfehlschluss gilt für unabhängige Zufallsereignisse: Eine Roulettekugel weiß nicht, was vorher geschah, also ist jeder Wurf ein erster Wurf. Ein Basketballspieler ist kein Zufallsgenerator, denn Menschen haben ein Gedächtnis, Münzen nicht. Der Glaube an die „heiße Hand“ (eine Serie setzt sich fort) galt nach Gilovich, Vallone und Tversky (1985) lange als reiner Denkfehler. Neuere Analysen zeigen allerdings, dass es bei Menschen echte, messbare Formschwankungen geben kann; Miller und Sanjurjo (2018) korrigierten einen statistischen Verzerrungseffekt der älteren Analyse. Dass sich Serien durch viele Würfe „ausgleichen“, trifft ebenfalls nicht zu: Das Gesetz der großen Zahlen verdünnt Abweichungen nur, es gleicht sie nicht aus. Wer beides in einen Topf wirft, übersieht die Frage, die entscheidet: Hat das Ding, das hier „würfelt“, ein Gedächtnis? Dass Serien sich immer ausgleichen oder immer fortsetzen, folgt dagegen weder für Kugeln noch für Spieler.","coreRule":"⚡ Prüfe zuerst, ob das, was die Serie erzeugt, ein Gedächtnis hat: Bei Roulettekugeln nie, bei Menschen kann eine Serie eine Ursache haben.","beleg":"Werkstück B.30 (Analyse); Fn. gl-b-hothand (Gilovich/Vallone/Tversky 1985, S. 295–314; Miller/Sanjurjo 2018, Econometrica 86(6), S. 2019–2047)","status":"entwurf","scenario":"","kurz":"Eine Roulettekugel hat kein Gedächtnis, ein Spieler schon: Form und Konzentration schwanken, sodass eine Serie hier etwas über den nächsten Wurf verraten kann. Wer beide Fälle gleichsetzt, übersieht, dass „Serien sagen nichts“ nur für unabhängige Ereignisse gilt.","prueffrage":"Wovon hängt bei einer Spielerin ab, ob ihr Wurf trifft, und wovon beim Roulette, in welchem Fach die Kugel liegen bleibt?","rueckmeldung":[{"option":0,"text":"Beim Roulette stimmt der Vergleich: Die Kugel hat kein Gedächtnis. Ein Spieler ist aber kein Zufallsgenerator, seine Form kann schwanken. Dass Serien bei ihm nichts aussagen können, folgt deshalb nicht allein daraus, dass Würfe unsicher sind."},{"option":2,"text":"Dass sich Serien über viele Würfe ausgleichen, erinnert an das Gesetz der großen Zahlen. Das verdünnt Abweichungen aber nur und gleicht nichts aus; entscheidend ist, ob sich ein Spieler anders verhält als eine Kugel."},{"option":3,"text":"Dass eine Serie beim Sport etwas aussagen kann, ist denkbar. „Immer“ geht aber zu weit, denn weder bei Spielern noch bei Kugeln folgt, dass sich Serien zwingend fortsetzen oder beenden. Beim Roulette sagt die Serie gar nichts."}],"familie":"zufall-ohne-gedaechtnis","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Miller, J. B.; Sanjurjo, A.: Surprised by the Hot Hand Fallacy? A Truth in the Law of Small Numbers. arXiv:1902.01265 (Autorenfassung; Econometrica 86(6), 2018, 2019–2047)","oeffentlich":true,"url":"https://arxiv.org/abs/1902.01265","abruf":"2026-10-12"},{"typ":"doi","kurz":"Gilovich, T.; Vallone, R.; Tversky, A. (1985): The hot hand in basketball: On the misperception of random sequences. Cognitive Psychology 17(3), 295–314","oeffentlich":false,"doi":"10.1016/0010-0285(85)90010-6"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Gambler’s“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-b2-056","clusterId":"B","werkstueckRef":"B.30","stufe":4,"question":"Wie lässt sich die Beobachtung am besten erklären, ohne in den Spielerfehlschluss zu geraten?","scenario":"Nach einer ungewöhnlich schlechten Woche hat dein Fitnessarmband für die Folgewoche wieder normalere Werte gezeigt. Ein Bekannter sagt: „Das hat sich eben ausgeglichen. Die schlechte Woche musste durch eine bessere wettgemacht werden.“","options":["Extreme Werte sind selten, deshalb folgt auf einen Ausreißer meist ein normalerer Wert. Dafür muss nichts „ausgeglichen“ werden.","Die schlechte Woche hat die Chance auf eine gute Folgewoche tatsächlich spürbar erhöht, weil sich die Werte ausgleichen müssen.","Abweichungen müssen langfristig wieder aufgeholt werden, sonst stimmt der Durchschnitt am Ende nicht mehr.","Der Zufall hat bei Alltagsdaten ein Gedächtnis und gleicht frühere Ausreißer in den Folgewochen wieder aus."],"correctIndex":0,"explanation":"Die Beobachtung selbst stimmt: Extreme Werte werden tatsächlich oft von normaleren gefolgt. Aber nicht, weil der Zufall etwas ausgleicht, sondern weil Extremwerte selten sind. Der Spielerfehlschluss dagegen unterstellt, dass eine Abweichung aktiv „ausgeglichen“ werden müsse. Das Gesetz der großen Zahlen gleicht aber nichts aus, es verdünnt Abweichungen nur: Frühe Ausreißer fallen immer weniger ins Gewicht, je mehr normale Werte dazukommen. Eine bessere Folgewoche ist also nicht „fällig“, sie ist einfach der wahrscheinlichere Normalfall.","coreRule":"⚡ Auf Extremes folgt oft Normales, aber nicht, weil der Zufall etwas schuldig wäre.","beleg":"Werkstück B.30 (Verbindungen: Nicht zu verwechseln mit Regression zur Mitte; Analyse)","status":"entwurf","kurz":"Extreme Werte sind selten, darum folgt auf einen Ausreißer meist ein normalerer Wert. Der Fehler wäre zu glauben, die gute Woche sei „fällig“; sie ist nur der wahrscheinlichere Normalfall, nichts wird ausgeglichen.","prueffrage":"Wie oft hat das Armband in früheren Wochen so schlechte Werte gezeigt, und wie oft normale?","rueckmeldung":[{"option":1,"text":"Dass nach der schlechten Woche eine normalere kam, trifft zu. Die schlechte Woche hat die Chance darauf aber nicht erhöht: Normale Werte sind einfach häufiger als extreme, darum war eine normalere Woche ohnehin der wahrscheinliche Fall."},{"option":2,"text":"Das erinnert an das Gesetz der großen Zahlen, das aber nichts aufholt. Es verdünnt Abweichungen nur: Mit mehr normalen Wochen fällt ein früher Ausreißer weniger ins Gewicht, ohne dass etwas nachgeholt werden müsste."},{"option":3,"text":"Dass auf einen Ausreißer oft normalere Werte folgen, stimmt. Dafür braucht es aber kein Gedächtnis des Zufalls, das etwas ausgleicht: Extreme Werte sind selten, normale häufig, also ist danach ein normalerer Wert ohnehin wahrscheinlicher."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Regression“, „Gambler’s“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Barnett, A. G.; van der Pols, J. C.; Dobson, A. J. (2005): Regression to the mean: what it is and how to deal with it. International Journal of Epidemiology 34(1), 215–220","oeffentlich":false,"doi":"10.1093/ije/dyh299"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1971): Belief in the law of small numbers. Psychological Bulletin 76(2), 105–110","oeffentlich":false,"doi":"10.1037/h0031322"}],"thema":"Gesundheit"},{"id":"qx-b2-057","clusterId":"B","werkstueckRef":"B.31","stufe":1,"question":"Welche Beobachtung würde die Behauptung der Kollegin am stärksten widerlegen?","options":["Die Jugendlichen bevorzugen beim Verteilen die eigene Gruppe, obwohl es weder Wettkampf noch Streit gab und die Einteilung zufällig war.","Die Jugendlichen bevorzugen die eigene Gruppe, nachdem sie in einem Wettkampf um einen knappen Preis gegeneinander angetreten sind.","Die Jugendlichen verteilen etwas mehr an Gruppenmitglieder, die sie persönlich gut kennen und mögen.","Die Jugendlichen bevorzugen die eigene Gruppe, wenn die Einteilung nach einem echten Unterschied wie dem Kunstgeschmack erfolgt."],"correctIndex":0,"explanation":"Die Behauptung sagt: Ohne Konkurrenz und ohne Streitgeschichte entsteht keine Gruppenbevorzugung. Am stärksten widerlegt sie ein Fall, in dem beides fehlt, die Einteilung rein zufällig ist und die eigene Gruppe trotzdem bevorzugt wird; ähnlich war der Versuch von Tajfel mit britischen Schuljungen angelegt (Einteilung angeblich nach Bildgeschmack, tatsächlich zufällig), und in einem Folgeversuch blieb die Bevorzugung auch bei offen per Münzwurf gebildeten Gruppen bestehen, wenn auch schwächer. Ein Wettkampf um einen knappen Preis passt dagegen zur Behauptung und widerlegt sie nicht. Wer mehr an Menschen gibt, die er persönlich kennt und mag, kann damit einer Beziehung folgen statt der Gruppe; über Konkurrenz und Streit sagt das nichts. Eine Einteilung nach echtem Unterschied wie dem Kunstgeschmack spräche zwar ebenfalls gegen die Behauptung, aber schwächer, weil sich die Bevorzugung dann auch mit einer Vorliebe für Ähnliche statt mit der Gruppe selbst erklären ließe.","coreRule":"⚡ Wer behauptet, eine Ursache sei nötig, wird widerlegt durch einen Fall, in dem sie fehlt und die Wirkung trotzdem eintritt. Schon ein bloßes Etikett kann „wir“ gegen „die“ erzeugen.","beleg":"Werkstück B.31 (Eingangsszene); Fn. gl-b-tajfel (Tajfel 1970; Tajfel u. a. 1971; Billig/Tajfel 1973, S. 28 f.); Anmerkung zu gl-b-tajfel (Münzwurf-Bedingung im Folgeversuch)","status":"entwurf","scenario":"Eine Kollegin sagt: „Gruppenbevorzugung entsteht erst, wenn Gruppen um knappe Ressourcen konkurrieren und es eine Vorgeschichte von Streit gibt.“ In einem Versuch werden Jugendliche, die sich aus der Schule kennen, zufällig in zwei Gruppen eingeteilt, etwa per Münzwurf. Sie wissen nicht, wer sonst zu ihrer Gruppe gehört, und verteilen Geld an anonyme Empfänger beider Gruppen.","quote":"","quoteLabel":"","kurz":"Am stärksten widerlegt die Behauptung ein Fall, in dem Konkurrenz und Streitgeschichte fehlen, die Einteilung zufällig ist und die eigene Gruppe trotzdem bevorzugt wird. Ein Wettkampf passt dagegen zu ihr, und Sympathie oder echte Unterschiede liefern eigene Gründe.","prueffrage":"Unter welchen Umständen würde die Kollegin selbst gar keine Bevorzugung der eigenen Gruppe erwarten?","rueckmeldung":[{"option":1,"text":"Dass die eigene Gruppe bevorzugt wird, stimmt zwar, aber hier gab es einen Wettkampf um einen knappen Preis. Das ist genau die Bedingung, die die Kollegin nennt, und passt daher zu ihrer Behauptung, statt sie zu widerlegen."},{"option":2,"text":"Wer mehr an Menschen gibt, die er kennt und mag, kann damit einer persönlichen Beziehung folgen statt der Gruppe. Ob Gruppenbevorzugung auch ohne Konkurrenz und Streit entsteht, lässt sich daran nicht ablesen."},{"option":3,"text":"Eine Einteilung nach echtem Unterschied wie dem Kunstgeschmack liefert einen eigenen Grund für Vorlieben, etwa Ähnlichkeit. Gegen die Behauptung spricht das schwächer als eine zufällige Einteilung, bei der jeder solche Grund fehlt."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Tajfel, H.; Turner, J. C. (1979): An Integrative Theory of Intergroup Conflict. In: Austin, W. G.; Worchel, S. (Hg.): The Social Psychology of Intergroup Relations (Kopie bei ALNAP)","oeffentlich":true,"url":"https://alnap.org/documents/8612/tajfel-turner-1979-compressed.pdf","seite":"38–39","abruf":"2026-10-12"},{"typ":"doi","kurz":"Billig, M.; Tajfel, H. (1973): Social categorization and similarity in intergroup behaviour. European Journal of Social Psychology 3(1)","oeffentlich":false,"doi":"10.1002/ejsp.2420030103","seite":"27–29, 34, 39"},{"typ":"literatur","kurz":"Tajfel, H. (1970): Experiments in Intergroup Discrimination. Scientific American 223(5)","oeffentlich":false,"seite":"99–102"}],"thema":"Zusammenleben"},{"id":"qx-b2-058","clusterId":"B","werkstueckRef":"B.31","stufe":3,"question":"Ein Kommentator behauptet: „Das Experiment beweist es: Sobald Menschen in ‚wir‘ und ‚die‘ eingeteilt werden, ist der Weg zur Entmenschlichung vorgezeichnet. Wer Gruppen bildet, bekommt am Ende Feindbilder.“ Was ist an diesem Schluss am ehesten fehlerhaft?","options":["Er springt von einer milden Bevorzugung der eigenen Gruppe auf eine extreme Folge, ohne zu zeigen, dass die Einteilung allein diesen Weg zurücklegt.","Er ignoriert, dass die Jugendlichen ihre Entscheidungen bewusst getroffen haben und deshalb für jede Folge ihres Verhaltens selbst verantwortlich sind.","Er unterschätzt, dass Menschen in Gruppen grundsätzlich fair verteilen und deshalb jede Bevorzugung der eigenen Gruppe nur ein Messfehler sein kann.","Er verwechselt die Bevorzugung der eigenen Gruppe mit einer Eigenschaft einzelner Personen und übersieht, dass sie nur in großen Gruppen auftritt."],"correctIndex":0,"explanation":"Das Experiment zeigt eine milde, messbare Bevorzugung der eigenen Gruppe bei bloßer, sogar zufälliger Einteilung. Zwischen diesem Befund und der Entmenschlichung, bei der der Fremdgruppe die Menschlichkeit selbst abgesprochen wird, liegt ein weiter Weg, den die bloße Einteilung allein nicht zurücklegt. Den Weg dorthin treibt dieselbe Gruppenbindung unter wachsendem Druck: Bedrohung, Konkurrenz um knappe Ressourcen und eine Führung, die die Distanz zwischen „wir“ und „die“ vergrößert. Zudem lässt sich der Ursprung der Gruppenbindung auch ohne Feindschaft erklären: Eine mögliche Erklärung sieht in ihr eine Gemeinschaft gegenseitigen Vertrauens, die Verbündeten Schutz und geteilte Nahrung brachte – eine Hypothese, kein Messergebnis. Und auch Entmenschlichung ist kein Entweder-oder, sondern hat Stufen von subtil bis offen. Der Kommentator schließt also von einem Anfangsbefund auf ein Endergebnis, ohne die Zwischenstrecke zu belegen.","coreRule":"⚡ Wer von einem milden Befund auf eine extreme Folge schließt, muss den Weg dazwischen belegen: Wir-Gefühl ist noch keine Feindschaft.","beleg":"Werkstück B.31 (Kontext & Tiefe; Kipppunkt); Fn. gl-b-brewer (Brewer 1999, S. 432–434); Fn. gl-b-kteily (Kteily u. a. 2015)","status":"entwurf","scenario":"In einem Experiment werden Jugendliche per Zufall in zwei Gruppen eingeteilt, angeblich nach ihrem Bildgeschmack. Sie verteilen anschließend kleine Geldbeträge an anonyme Mitglieder beider Gruppen und bevorzugen dabei systematisch die eigene Gruppe, teils sogar auf Kosten des absoluten Gewinns der eigenen Gruppe, solange der Abstand zur anderen Gruppe wächst.","kurz":"Der Befund zeigt nur eine milde Bevorzugung der eigenen Gruppe. Von dort bis zur Entmenschlichung ist es weit, und der Kommentator belegt die Zwischenstrecke nicht: Bedrohung, Konkurrenz und Führung kommen als Treiber hinzu.","prueffrage":"Was taten die Jugendlichen im Experiment gegenüber der anderen Gruppe, und was davon wurde gemessen?","rueckmeldung":[{"option":1,"text":"Ob die Jugendlichen für ihr Verhalten verantwortlich sind, ist eine andere Frage als die, ob der Befund den Schluss stützt. Der Kommentator irrt, weil er von einem milden Anfangsbefund auf ein extremes Ergebnis schließt."},{"option":2,"text":"Grundsätzliche Fairness würde den Befund zum Messfehler machen. Doch die Bevorzugung zeigt sich systematisch, teils sogar auf Kosten des absoluten Gewinns der eigenen Gruppe. Fehlerhaft ist nicht der Befund, sondern der Schluss daraus."},{"option":3,"text":"Eine Beschränkung auf große Gruppen gibt der Befund nicht her, über die Gruppengröße sagt er nichts. Der Schluss kippt an anderer Stelle: beim Sprung von einer milden Bevorzugung der eigenen Gruppe zur Entmenschlichung."}],"familie":"dammbruch-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Brewer, M. B. (1999): The Psychology of Prejudice: Ingroup Love or Outgroup Hate? Journal of Social Issues 55(3) (inoffizielle Kopie auf Server des Bard College)","oeffentlich":true,"url":"https://bcsh.bard.edu/files/2019/06/Brewer-ingroup-love-or-outgroup-hate.pdf","seite":"431–437","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kteily, N.; Bruneau, E.; Waytz, A.; Cotterill, S. (2015): The Ascent of Man: Theoretical and Empirical Evidence for Blatant Dehumanization. JPSP 109(5)","oeffentlich":false,"doi":"10.1037/pspp0000048"},{"typ":"url","kurz":"Tajfel, H.; Turner, J. C. (1979): An Integrative Theory of Intergroup Conflict (Kopie bei ALNAP)","oeffentlich":true,"url":"https://alnap.org/documents/8612/tajfel-turner-1979-compressed.pdf","seite":"38–39","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-059","clusterId":"B","werkstueckRef":"B.31","stufe":4,"question":"Was zeigt diese Beobachtung am ehesten über den Charakter der Debatte?","scenario":"In einer Debatte über eine Klimamaßnahme werden Abweichler in der eigenen Gruppe heftiger angegriffen als die eigentliche Gegenseite. Die Gegenseite wird nur noch als einheitliche Masse beschrieben.","options":["Die Gruppe nimmt Widerspruch auch im Inneren ernst, und die Debatte ist dadurch sachlicher geworden.","Die Gruppe prüft Abweichler strenger als externe Gegner, weil ihr die Sache besonders wichtig ist.","Die Gruppengrenze ist wichtiger geworden als die Sache selbst, und die Gegenseite gilt nur noch als Masse.","Die Gegenseite hat in der Sache recht, weil Gruppen auf unbequeme Wahrheiten besonders heftig reagieren."],"correctIndex":2,"explanation":"Wenn Abweichler in der eigenen Gruppe härter angegriffen werden als die eigentliche Gegenseite, geht es erkennbar nicht mehr um die Klimamaßnahme, sondern um Loyalität: Wer abweicht, stellt die Zugehörigkeit infrage. Dazu passt, dass die Gegenseite nur noch als einheitliche Masse ohne eigene Stimmen beschrieben wird. Das ist ein typisches Zeichen dafür, dass die Gruppenzugehörigkeit die Sachfrage überlagert: Wichtiger als die Argumente wird, was die Zugehörigkeit zur eigenen Gruppe signalisiert. Eine einfache Prüffrage: Würdest du dasselbe Argument genauso bewerten, wenn es aus der eigenen Gruppe käme, und ihm genauso widersprechen, wenn ein Mitglied deiner Gruppe es verträte?","coreRule":"⚡ Wo Zustimmung vor allem Zugehörigkeit signalisiert, verliert das Argument sein Gewicht.","quote":"","quoteLabel":"","beleg":"Werkstück B.31 (Red Flags; Anwendung: Politische Polarisierung; Anti-Denkmuster)","status":"entwurf","kurz":"Wer Abweichler härter angreift als die Gegenseite und diese nur noch als Masse beschreibt, kämpft erkennbar um Zugehörigkeit statt um die Klimamaßnahme. Der naheliegende Fehler ist, Härte für besondere Sachstrenge zu halten.","prueffrage":"Wen trifft die schärfste Kritik: Menschen mit anderen Argumenten oder Menschen aus den eigenen Reihen?","rueckmeldung":[{"option":0,"text":"Kritik von innen kann ein Zeichen offener Debatte sein. Hier werden Abweichler aber heftig angegriffen statt angehört, und die Gegenseite kommt nur als Masse vor. Das spricht nicht für mehr Sachlichkeit."},{"option":1,"text":"Wem eine Sache wichtig ist, der prüft genau, das wirkt plausibel. Doch wer wirklich die Sache prüft, nimmt sich die Gegenseite mindestens so genau vor wie Abweichler und beschreibt sie nicht nur als einheitliche Masse."},{"option":3,"text":"Heftige Reaktionen sagen etwas über die Gruppe, nicht darüber, wer in der Sache recht hat. Zudem treffen sie hier vor allem Abweichler aus den eigenen Reihen und nicht die Gegenseite."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Ditto, P. H. u. a. (2019): At Least Bias Is Bipartisan: A Meta-Analytic Comparison of Partisan Bias in Liberals and Conservatives. Perspectives on Psychological Science 14(2) (Kopie auf der Seite des Ditto-Labors, UC Irvine)","oeffentlich":true,"url":"https://sites.uci.edu/peterdittolab/files/2018/06/Ditto-et-al.-2018-At-Least-Bias-is-Bipartisan-A-Meta-Analytic-Comparison-of-Partisan-Bias-in-Liberals-Conservatives.pdf","abruf":"2026-10-12"},{"typ":"url","kurz":"Castano, E.; Yzerbyt, V. Y. (1998): The highs and lows of group homogeneity. Behavioural Processes 42 (Kopie auf der Seite von V. Yzerbyt, UCLouvain)","oeffentlich":true,"url":"https://perso.uclouvain.be/vincent.yzerbyt/Castano%20&%20Yzerbyt%20BP%201998.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-060","clusterId":"B","werkstueckRef":"B.31","stufe":2,"question":"Welche Erklärung für diese Wahl ist am sparsamsten und erklärt zugleich, warum die Verteilung mit weniger Punkten für die eigene Gruppe gewählt wird?","scenario":"Zwei Gruppen von Schülern wurden eben erst zufällig eingeteilt, ohne Wettkampf und ohne vorherigen Streit; niemand weiß, wer sonst zur eigenen Gruppe gehört. Nun dürfen sie Punkte an anonyme Empfänger beider Gruppen verteilen, die später in echtes Geld umgetauscht werden. Viele wählen eine Verteilung, bei der die eigene Gruppe 7 Punkte und die andere 1 Punkt bekommt, statt einer Verteilung mit 10 Punkten für die eigene und 12 für die andere Gruppe. Dabei verteilen sie nie an sich selbst.","options":["Die Gruppe ist ihnen schon so wichtig, dass sie vor allem den Abstand zur anderen Gruppe vergrößern wollen, auch wenn die eigene Gruppe dabei absolut weniger erhält.","Sie haben die Verteilungen nicht verstanden und wählen deshalb zufällig, sodass sich die eigene Gruppe nur durch Zufall im Vorteil befindet.","Sie rechnen damit, dass die andere Gruppe sie später benachteiligen wird, und schützen sich deshalb vorab vor dieser Gefahr.","Sie haben sich in der kurzen Zeit mit ihrer Gruppe auf eine gemeinsame Strategie geeinigt und setzen diese Absprache nun gemeinsam um."],"correctIndex":0,"explanation":"Wenn jemand die Verteilung mit weniger Punkten für die eigene Gruppe wählt, nur weil der Abstand größer ist, geht es nicht ums Gewinnen, sondern ums Besser-Dastehen. Das passt dazu, dass ein Teil des Selbstwerts an die Gruppe gekoppelt ist: Es genügt nicht, dass es „uns“ gut geht, „wir“ sollen mehr haben als „die“. Reiner Zufall würde die klare, systematische Bevorzugung der eigenen Gruppe nicht erklären. Für eine drohende Benachteiligung durch die andere Gruppe gibt es keinen Anhaltspunkt, denn es gab keinen Wettkampf und keine Vorgeschichte, nur ein Etikett; und eine Absprache ist ausgeschlossen, weil die Schüler nicht wussten, wer außer ihnen selbst zur Gruppe gehörte. Dass schon eine zufällige Einteilung ausreicht, ist der Kern des Befunds: Das Gruppenetikett allein genügt, damit der Vergleich mit der anderen Gruppe wichtig wird.","coreRule":"⚡ Wenn jemand lieber weniger für alle will, solange „wir“ mehr haben als „die“, geht es nicht um Gewinn, sondern um den Vergleich.","beleg":"Werkstück B.31 (Kernidee; Kontext & Tiefe: Sozialer Vergleich & positive Distinktheit)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer der eigenen Gruppe weniger Punkte gibt, nur damit der Abstand zur anderen wächst, will nicht möglichst viel bekommen, sondern besser dastehen als „die anderen“. Dafür genügt schon das zufällige Etikett; Angst, Absprache oder Zufall erklären die Wahl nicht.","prueffrage":"Was haben die Schüler in der Verteilung für ihre eigene Gruppe verloren, und was haben sie dafür bekommen?","rueckmeldung":[{"option":1,"text":"Zufälliges Wählen würde sich im Mittel ausgleichen. Hier wählen aber viele dieselbe Verteilung, und die eigene Gruppe liegt dabei systematisch vorn. Das spricht gegen ein bloßes Missverständnis der Aufgabe."},{"option":2,"text":"Vorsorge gegen eine mögliche Benachteiligung wirkt vernünftig. Doch die Gruppen wurden eben erst zufällig gebildet, ohne Wettkampf und ohne Vorgeschichte; für eine solche Gefahr fehlt jeder Anhaltspunkt."},{"option":3,"text":"Eine gemeinsame Strategie würde die Bevorzugung gut erklären. Doch niemand wusste, wer sonst zur eigenen Gruppe gehört, und verteilt wurde an anonyme Empfänger. Eine Absprache war schon deshalb nicht möglich."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Tajfel, H.; Turner, J. C. (1979): An Integrative Theory of Intergroup Conflict (Kopie bei ALNAP)","oeffentlich":true,"url":"https://alnap.org/documents/8612/tajfel-turner-1979-compressed.pdf","seite":"38–42","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Tajfel, H. (1970): Experiments in Intergroup Discrimination. Scientific American 223(5)","oeffentlich":false,"seite":"101–102"}],"thema":"Zusammenleben"},{"id":"qx-b2-061","clusterId":"B","werkstueckRef":"B.32","stufe":1,"question":"Welche Annahme steckt hinter dieser Einschätzung, und warum ist sie riskant?","options":["Er unterstellt, die fremde Regierung denke und werte wie er selbst, und füllt so die Wissenslücke mit dem eigenen Bild statt mit Wissen über ihre Sicht.","Er unterstellt, die fremde Regierung verfolge das genaue Gegenteil dessen, was er selbst an ihrer Stelle verfolgen würde, und verfehlt so ihre tatsächlichen Ziele.","Er überträgt die Eigenschaften der Regierung auf jeden einzelnen Bürger des Landes und übergeht so die Vielfalt der Meinungen im Land.","Er stellt seine eigene Urteilsfähigkeit vor dem Team besonders positiv dar und blendet dadurch widersprechende Hinweise aus der Analyse aus."],"correctIndex":0,"explanation":"Die Einschätzung beantwortet nicht die Frage, wie die fremde Regierung ihre Lage sieht, sondern eine andere: Was würde ich an ihrer Stelle wollen? Sie stützt sich auf nichts, was von der anderen Seite stammt, weder Äußerungen noch Kenntnis ihrer Lage. Wo Wissen fehlt, setzt man unbemerkt das einzige Modell eines Geistes ein, das man von innen kennt: sich selbst. Das nennt man Spiegelbild-Denken (Mirror-Imaging). So wurde 1977 ein mutmaßliches Atomtestgelände in Südafrika von vielen Analysten abgetan, mit genau diesem Argument. Als Notbehelf lässt sich der Blick in den Spiegel manchmal nicht vermeiden, aber ein solches Urteil verdient wenig Vertrauen. Besser prüft man, ob die andere Seite ihre Lage selbst beschrieben hat, und zieht Menschen hinzu, die sie aus eigener Anschauung kennen.","coreRule":"⚡ Wo Wissen über den anderen fehlt, setzt man sich selbst ein, ohne es zu merken. Frag daher: Weiß ich, wie die andere Seite ihre Lage sieht, oder setze ich nur ein, was ich an ihrer Stelle täte?","beleg":"Werkstück B.32 (Kernidee; Analyse); Fn. gl-b-heuer (Heuer 1999, Psychology of Intelligence Analysis, S. 70)","status":"entwurf","scenario":"Ein Analyst soll einschätzen, ob ein ihm kaum bekannter Staat Atomwaffen anstrebt. Er schreibt: „Das Land hat keinen Feind, gegen den sich eine Atomwaffe wirksam einsetzen ließe. Also will es keine. An seiner Stelle würde ich auch darauf verzichten.“ Niemand im Team kennt das Land aus eigener Anschauung, und es liegen keine Äußerungen der dortigen Regierung vor.","kurz":"Der Analyst beantwortet nicht, wie das Land seine Lage sieht, sondern was er selbst an dessen Stelle wollte. Wo Wissen fehlt, setzt man unbemerkt das eigene Denken ein, und ein solches Urteil verdient wenig Vertrauen.","prueffrage":"Was von dem, worauf sich die Einschätzung stützt, stammt tatsächlich von der Regierung des Landes selbst?","rueckmeldung":[{"option":1,"text":"Vom Gegenteil ist hier nichts zu sehen: Er hält einen Verzicht für vernünftig und nimmt an, die andere Seite sehe es genauso. Das Risiko liegt darin, dass er sich selbst als Maßstab nimmt, nicht darin, dass er das Gegenteil unterstellt."},{"option":2,"text":"Dass Meinungen in einem Land auseinandergehen, stimmt allgemein. Hier geht es aber um die Absichten der Regierung, über Bürger sagt der Analyst nichts. Seine Schwäche: Er schließt von seinem eigenen Denken auf das der Regierung."},{"option":3,"text":"Von Selbstdarstellung vor dem Team oder ausgeblendeten Hinweisen ist nirgends die Rede. Das Problem ist eher, dass es kaum Hinweise gibt: Diese Lücke füllt er mit dem eigenen Blick, statt zu klären, wie die andere Seite ihre Lage sieht."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"70–71, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-062","clusterId":"B","werkstueckRef":"B.32","stufe":3,"question":"Was ist der entscheidende Fehler an diesem Vorgehen?","options":["Die Annahme wurde als Behelf für eine Wissenslücke eingeführt, ist aber inzwischen als gesicherte Tatsache in eine folgenreiche Entscheidung eingegangen.","Es wurde zu früh auf Sanktionen gesetzt, obwohl man vor einer Entscheidung grundsätzlich erst die Lage der Gegenseite vollständig klären muss.","Die Annahme, die Gegenseite denke ähnlich wie man selbst, ist nur dann zulässig, wenn es sich um eine demokratisch regierte Nachbarregierung handelt.","Die Gruppe hat zu wenig Zeit auf die Frage verwendet, ob die Nachbarregierung ihre Truppen aus Sicht des eigenen Landes abziehen sollte."],"correctIndex":0,"explanation":"Die eigene Sicht ist das einzige Modell eines Geistes, das wir von innen kennen. Als vorläufiger Notbehelf bei fehlendem Wissen ist sie kaum zu vermeiden, solange allen klar bleibt, dass es nur eine Vermutung ist. Der Fehler liegt im Wechsel von der Vermutung zur Gewissheit: Aus „So würden wir handeln“ wurde „So wird sie handeln, alles andere wäre unvernünftig“, und das Wort „unvernünftig“ misst das Gegenüber an den eigenen Maßstäben. Wo niemand die andere Seite kennt, trägt diese Annahme allein keine folgenreiche Entscheidung. Dann hilft es, Fachleute hinzuzuziehen, die das Land kennen, oder die andere Seite mit ihren eigenen Worten zu Wort kommen zu lassen.","coreRule":"⚡ Ein Spiegel ist als Notbehelf erlaubt, solange du weißt, dass du in einen Spiegel blickst.","beleg":"Werkstück B.32 (Adaptives Talent; Kipppunkt; Anwendung & Relevanz: Fachleute von außen); Fn. gl-b-heuer (Heuer 1999, S. 70 f. und 181)","status":"entwurf","scenario":"In einer Lagebesprechung sagt ein Berater: „Über die Absichten der Nachbarregierung wissen wir wenig. Also nehmen wir vorläufig an, sie handelt so, wie wir es an ihrer Stelle täten.“ Drei Wochen später steht im Entwurf einer Sanktionsentscheidung als Ausgangslage: „Die Nachbarregierung wird ihre Truppen abziehen, denn alles andere wäre unvernünftig.“ Niemand im Raum kennt das Land aus eigener Anschauung.","kurz":"Aus der vorläufigen Vermutung „So würden wir handeln“ wurde stillschweigend ein „So wird sie handeln“. Als Notbehelf bei fehlendem Wissen geht das, solange es als Vermutung erkennbar bleibt; als Grundlage einer Sanktionsentscheidung trägt es nicht.","prueffrage":"Welche neuen Erkenntnisse über das Nachbarland liegen zwischen der Lagebesprechung und dem Entwurf drei Wochen später?","rueckmeldung":[{"option":1,"text":"Sanktionen auf ungeprüfter Grundlage sind riskant, das stimmt. Aber „erst vollständig klären“ ist kaum je erfüllbar, und als Behelf war die Annahme zulässig. Fehlerhaft ist der Wechsel von der Vermutung zur Gewissheit, nicht der Zeitpunkt."},{"option":2,"text":"Ob die Annahme tragfähig ist, hängt nicht vom Regierungssystem ab. Auch eine Demokratie handelt nicht immer so, wie man selbst es täte. Als Notbehelf geht die Annahme, solange alle wissen, dass sie nur eine Vermutung ist."},{"option":3,"text":"Mehr Zeit für die Frage, was aus eigener Sicht vernünftig wäre, verstärkt gerade das Problem: Die eigene Sicht ist schon zum Maßstab geworden, und eine Vermutung zur Tatsache. Es fehlt Wissen darüber, wie das Land selbst seine Lage sieht."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"70–71, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-063","clusterId":"B","werkstueckRef":"B.32","stufe":4,"question":"Was ist die klügste Reaktion auf diesen Satz in einer Lageanalyse?","scenario":"In einer Lageanalyse zu einem fremden Land steht: „Das Vorgehen dieser Regierung ist völlig irrational und gegen ihre eigenen Interessen.“ Keiner der Autoren hat das Land je besucht, und die Regierung selbst kommt in der Analyse nicht zu Wort.","options":["Den Satz als Hinweis nehmen, dass die Regierung intern von Gruppendenken geprägt ist, in dem Abweichler unterdrückt werden und Fehler entstehen.","Den Satz als Hinweis nehmen, dass der anderen Seite Informationen fehlen, während ihre Motive von uns richtig eingeschätzt und verstanden sind.","Den Satz als Beleg nehmen, dass die Regierung tatsächlich irrational handelt, weil Interessen von außen objektiv bestimmbar und eindeutig sind.","Den Satz als Warnzeichen nehmen, dass womöglich eigene Werte und Denkrahmen übertragen wurden, und prüfen, wie die Regierung ihre Lage selbst sieht."],"correctIndex":3,"explanation":"Wenn das Verhalten einer fremden Regierung „irrational“ oder „gegen ihre eigenen Interessen“ wirkt, liegt der Fehler oft beim Beobachter: Er hat die eigenen Werte und Denkrahmen auf sie übertragen, statt die Logik der Lage so zu verstehen, wie sie sich ihr selbst darstellt. Wer nicht weiß, wie das Gegenüber denkt, setzt meist unbemerkt das einzige Modell eines Geistes ein, das er von innen kennt: sich selbst. Dass die Analyse keine Selbstauskunft der Regierung enthält und niemand das Land kennt, verstärkt den Verdacht. Das Etikett „irrational“ beendet die Erklärung, wo sie beginnen sollte. Die bessere Frage lautet: Weiß ich, wie die andere Seite ihre Lage sieht, oder setze ich nur ein, was ich an ihrer Stelle täte? Reden, Interviews und Programme der Regierung selbst sowie Fachleute, die das Land aus eigener Anschauung kennen, prüfen das. Gruppendenken oder bloßer Informationsmangel können vorkommen, sind aber Zusatzannahmen, für die der Satz nichts liefert. Und dass Interessen von außen eindeutig bestimmbar seien, ist genau die Annahme, die hier zum Fehlurteil führt.","coreRule":"⚡ „Irrational“ sagt oft mehr über den Beobachter als über den Beobachteten.","quote":"","quoteLabel":"","beleg":"Werkstück B.32 (Analyse; Red Flags; Anti-Denkmuster); Fn. gl-b-heuer (Heuer 1999, S. 33)","status":"entwurf","kurz":"„Irrational“ sagt oft mehr über den Beobachter als über die Regierung: Er setzt eigene Werte und Denkrahmen ein. Ohne Selbstauskunft und Landeskenntnis ist der Satz ein Warnzeichen, und zu prüfen ist, wie die Regierung ihre Lage selbst sieht.","prueffrage":"Auf welchen Quellen beruht das Urteil „irrational“, und wer von den Autoren war je in diesem Land?","rueckmeldung":[{"option":0,"text":"Gruppendenken kommt in Regierungen tatsächlich vor. Für interne Abläufe liefert der Satz aber keinen Anhaltspunkt, und die Regierung kommt gar nicht zu Wort. Die Deutung bleibt eine Zusatzannahme, die das Urteil „Fehler“ schon voraussetzt."},{"option":1,"text":"Dass der anderen Seite Informationen fehlen, kann vorkommen. Die Sicherheit, ihre Motive selbst richtig zu verstehen, trägt aber nicht: Niemand kennt das Land, und die Regierung wird nicht gehört. Genau dieses Nichtwissen sollte misstrauisch machen."},{"option":2,"text":"Der Satz belegt allenfalls, wie die Autoren die Lage bewerten. Interessen lassen sich von außen nicht so eindeutig bestimmen, wie es hier vorausgesetzt wird. Mit „irrational“ endet die Erklärung, wo sie erst beginnen sollte."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"33, 70, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-b2-064","clusterId":"B","werkstueckRef":"B.32","stufe":2,"question":"Was ist an dieser Schlussfolgerung fehlerhaft, und was wäre der nächste sinnvolle Schritt?","scenario":"In einer Verhandlung stellt der andere Verband plötzlich eine Forderung, die deinem Team völlig unverständlich vorkommt. Eine Kollegin sagt: „Ich hätte an seiner Stelle nie so etwas verlangt. Er muss also bluffen und will uns nur unter Druck setzen.“ Ihr habt nie mit jemandem aus seinem Verband gesprochen, und in euren Unterlagen steht nichts darüber, wie er die eigene Lage beschreibt.","options":["Sie setzt das eigene Denken an die Stelle seines Denkens; sinnvoll wäre, zuerst herauszufinden, wie er seine eigene Lage und seine Ziele selbst beschreibt.","Sie sucht nur Hinweise, die die Vermutung stützen; sinnvoll wäre, die Vermutung als Hypothese zu formulieren und dafür Belege zu sammeln.","Sie hält die eigenen Ziele für moralisch besser als seine; sinnvoll wäre, die eigenen Ziele offen und ausführlich zu begründen.","Sie nimmt an, die Wahrheit liege in der Mitte zwischen beiden Positionen; sinnvoll wäre, sofort einen Kompromiss anzubieten."],"correctIndex":0,"explanation":"Die Kollegin beantwortet nicht die Frage, wie der andere seine Lage sieht, sondern eine andere: was sie selbst an seiner Stelle wollen würde. Das ist Spiegelbild-Denken. Die Frage „Warum würde ich so etwas tun?“ liefert eine Antwort über einen selbst, nicht über den anderen. Sie füllt eine Wissenslücke mit dem einzigen Modell eines Geistes, das sie von innen kennt: ihrem eigenen. Gerade weil niemand im Team die andere Seite aus eigener Anschauung kennt und ihre Sicht in den Unterlagen nirgends mit eigenen Worten vorkommt, ist die Schlussfolgerung „Bluff“ nur eine Vermutung und sollte nicht als Tatsache in die Verhandlung eingehen. Der nächste Schritt ist, die Sicht des anderen zu klären: über seine eigenen Worte, etwa eine Rede, ein Interview oder eine Beschreibung seiner Lage, und über Menschen, die seine Seite aus eigener Anschauung kennen. Mit dem Symmetrie-Trugschluss ist das nicht zu verwechseln: Dort liegt der Fehler in der Annahme, die Wahrheit liege in der Mitte zwischen zwei Positionen; hier darin, dass der andere als Spiegelbild von einem selbst gesehen wird. Ein sofortiges Kompromissangebot würde deshalb am eigentlichen Fehler vorbeigehen.","coreRule":"⚡ „Was würde ich tun?“ ist eine Frage über dich, nicht über den anderen.","beleg":"Werkstück B.32 (Anwendung: Verhandlung & Alltag; Anti-Denkmuster)","status":"entwurf","kurz":"Die Kollegin beantwortet nicht, wie der andere seine Lage sieht, sondern was sie selbst an seiner Stelle wollen würde. „Bluff“ ist damit nur eine Vermutung. Sinnvoll ist, zuerst seine eigene Sicht zu klären.","prueffrage":"Was hat der andere Verband selbst über seine Forderung gesagt, und wer im Team hat je mit jemandem von dort gesprochen?","rueckmeldung":[{"option":1,"text":"Dass „Bluff“ nur eine Vermutung ist, stimmt. Doch die Kollegin sucht gar keine Hinweise, sie schließt von sich auf ihn; und Belege nur für die eigene Vermutung zu sammeln, klärt nicht, wie er seine Lage sieht."},{"option":2,"text":"Die eigenen Ziele offen zu begründen, ist nützlich. Von einer moralischen Wertung ist in der Aussage aber gar nicht die Rede, und die Begründung klärt nichts darüber, wie der andere seine Lage sieht."},{"option":3,"text":"Ein Kompromiss klingt vernünftig, wenn zwei Positionen aufeinandertreffen. Hier fehlt aber erst das Wissen darüber, was der andere will. Der Fehler liegt im Blick auf ihn als Spiegelbild, nicht in einer Mitte-Annahme."}],"familie":"aus-ihrer-lage-urteilen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis. CIA, Center for the Study of Intelligence","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"70, 181","abruf":"2026-10-12"}],"thema":"Zusammenleben"}]`);export{t as n,n as t};